export default "nvalidTokenError, match=\\\"EXTERNAL_AUTH_JWKS_URL\\\"):\\n        await decode_external_jwt(\\\"anything\\\", settings)\\n\\n\\n# ---------------------------------------------------------------------------\\n# decode_external_jwt (JWKS path)\\n# ---------------------------------------------------------------------------\\n\\n_JWKS_URL = \\\"https://idp.example.com/.well-known/jwks.json\\\"\\n_JWKS_AUDIENCE = \\\"langflow\\\"\\n\\n\\ndef _jwks_settings(tmp_path) -> AuthSettings:\\n    return _auth_settings(\\n        tmp_path,\\n        EXTERNAL_AUTH_TRUSTED_JWT_DECODE=False,\\n        EXTERNAL_AUTH_JWKS_URL=_JWKS_URL,\\n        EXTERNAL_AUTH_ALGORITHMS=\\\"HS256\\\",\\n        EXTERNAL_AUTH_AUDIENCE=_JWKS_AUDIENCE,\\n    )\\n\\n\\ndef _symmetric_jwk(secret: str, kid: str) -> dict:\\n    return {\\n        \\\"kty\\\": \\\"oct\\\",\\n        \\\"alg\\\": \\\"HS256\\\",\\n        \\\"kid\\\": kid,\\n        \\\"k\\\": base64.urlsafe_b64encode(secret.encode()).rstrip(b\\\"=\\\").decode(),\\n    }\\n\\n\\ndef _install_fake_jwks_endpoint(monkeypatch, payloads: list[dict]) -> list[str]:\\n    \\\"\\\"\\\"Serve payloads[i] for the i-th JWKS fetch (last payload repeats); returns the call log.\\\"\\\"\\\"\\n    calls: list[str] = []\\n\\n    class _FakeResponse:\\n        def __init__(self, payload):\\n            self._payload = payload\\n\\n        def raise_for_status(self):\\n            return None\\n\\n        def json(self):\\n            return self._payload\\n\\n    class _FakeAsyncClient:\\n        def __init__(self, **_kwargs):\\n            pass\\n\\n        async def __aenter__(self):\\n            return self\\n\\n        async def __aexit__(self, *_args):\\n            return False\\n\\n        async def get(self, url):\\n            calls.append(url)\\n            return _FakeResponse(payloads[min(len(calls) - 1, len(payloads) - 1)])\\n\\n    monkeypatch.setattr(external.httpx, \\\"AsyncClient\\\", _FakeAsyncClient)\\n    return calls\\n\\n\\n@pytest.mark.anyio\\nasync def test_jwks_decode_verifies_signature(tmp_path, monkeypatch):\\n    settings = _jwks_settings(tmp_path)\\n    monkeypatch.setattr(external, \\\"_jwks_cache\\\", {})\\n    _install_fake_jwks_endpoint(monkeypatch, [{\\\"keys\\\": [_symmetric_jwk(_TEST_JWT_SECRET, kid=\\\"key-1\\\")]}])\\n\\n    valid_exp = datetime.now(timezone.utc) + timedelta(minutes=5)\\n    token = jwt.encode(\\n        {\\\"sub\\\": \\\"subject-1\\\", \\\"aud\\\": _JWKS_AUDIENCE, \\\"exp\\\": valid_exp},\\n        _TEST_JWT_SECRET,\\n        algorithm=\\\"HS256\\\",\\n        headers={\\\"kid\\\": \\\"key-1\\\"},\\n    )\\n    claims = await decode_external_jwt(token, settings)\\n    assert claims[\\\"sub\\\"] == \\\"subject-1\\\"\\n\\n    wrong_secret = \\\"another-secret-that-did-not-sign-the-jwks-key\\\"  # noqa: S105 # pragma: allowlist secret\\n    tampered = jwt.encode(\\n        {\\\"sub\\\": \\\"subject-1\\\", \\\"aud\\\": _JWKS_AUDIENCE, \\\"exp\\\": valid_exp},\\n        wrong_secret,\\n        algorithm=\\\"HS256\\\",\\n        headers={\\\"kid\\\": \\\"key-1\\\"},\\n    )\\n    with pytest.raises(InvalidTokenError, match=\\\"validation failed\\\"):\\n        await decode_external_jwt(tampered, settings)\\n\\n\\n@pytest.mark.anyio\\nasync def test_jwks_decode_requires_audience(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"JWKS verification must reject the config when no expected audience is bound.\\\"\\\"\\\"\\n    settings = _jwks_settings(tmp_path)\\n    settings.EXTERNAL_AUTH_AUDIENCE = None\\n    monkeypatch.setattr(external, \\\"_jwks_cache\\\", {})\\n    calls = _install_fake_jwks_endpoint(monkeypatch, [{\\\"keys\\\": [_symmetric_jwk(_TEST_JWT_SECRET, kid=\\\"key-1\\\")]}])\\n\\n    token = jwt.encode({\\\"sub\\\": \\\"subject-1\\\"}, _TEST_JWT_SECRET, algorithm=\\\"HS256\\\", headers={\\\"kid\\\": \\\"key-1\\\"})\\n    with pytest.raises(InvalidTokenError, match=\\\"EXTERNAL_AUTH_AUDIENCE\\\"):\\n        await decode_external_jwt(token, settings)\\n    # Misconfiguration is rejected before any network call to the JWKS endpoint.\\n    assert calls == []\\n\\n\\n@pytest.mark.anyio\\nasync def test_jwks_decode_rejects_token_for_another_audience(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"A token the same IdP minted for a different relying party is rejected.\\\"\\\"\\\"\\n    settings = _jwks_settings(tmp_path)\\n    monkeypatch.setattr(external, \\\"_jwks_cache\\\", {})\\n    _install_fake_jwks_endpoint(monkeypatch, [{\\\"keys\\\": [_symmetric_jwk(_TEST_JWT_SECRET, kid=\\\"key-1\\\")]}])\\n\\n    foreign = jwt.encode(\\n        {\\\"sub\\\": \\\"subject-1\\\", \\\"aud\\\": \\\"some-other-service\\\", \\\"exp\\\": datetime.now(timezone.utc) + timedelta(minutes=5)},\\n        _TEST_JWT_SECRET,\\n        algorithm=\\\"HS256\\\",\\n        headers={\\\"kid\\\": \\\"key-1\\\"},\\n    )\\n    with pytest.raises(InvalidTokenError, match=\\\"validation failed\\\"):\\n        await decode_external_jwt(foreign, settings)\\n\\n\\n@pytest.mark.anyio\\nasync def test_jwks_refetches_when_kid_is_newer_than_cache(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"IdP key rotation: an unknown kid forces one cache-busting JWKS refetch.\\\"\\\"\\\"\\n    settings = _jwks_settings(tmp_path)\\n    old_jwks = {\\\"keys\\\": [_symmetric_jwk(_TEST_JWT_SECRET, kid=\\\"old-key\\\")]}\\n    new_jwks = {\\\"keys\\\": [_symmetric_jwk(_TEST_JWT_SECRET, kid=\\\"new-key\\\")]}\\n    # Cached entry is still valid but old enough to be past the refresh rate limit.\\n    fetched_at = time.monotonic() - external.JWKS_MIN_REFRESH_INTERVAL_SECONDS - 1\\n    monkeypatch.setattr(external, \\\"_jwks_cache\\\", {_JWKS_URL: (fetched_at + external.JWKS_CACHE_TTL_SECONDS, old_jwks)})\\n    calls = _install_fake_jwks_endpoint(monkeypatch, [new_jwks])\\n\\n    token = jwt.encode(\\n        {\\\"sub\\\": \\\"rotated\\\", \\\"aud\\\": _JWKS_AUDIENCE, \\\"exp\\\": datetime.now(timezone.utc) + timedelta(minutes=5)},\\n        _TEST_JWT_SECRET,\\n        algorithm=\\\"HS256\\\",\\n        headers={\\\"kid\\\": \\\"new-key\\\"},\\n    )\\n    claims = await decode_external_jwt(token, settings)\\n\\n    assert claims[\\\"sub\\\"] == \\\"rotated\\\"\\n    assert calls == [_JWKS_URL]\\n\\n\\n@pytest.mark.anyio\\nasync def test_jwks_refresh_is_rate_limited_for_unknown_kid(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"A freshly fetched JWKS is not refetched for an unknown kid (anti-hammering).\\\"\\\"\\\"\\n    settings = _jwks_settings(tmp_path)\\n    jwks = {\\\"keys\\\": [_symmetric_jwk(_TEST_JWT_SECRET, kid=\\\"key-1\\\")]}\\n    monkeypatch.setattr(\\n        external, \\\"_jwks_cache\\\", {_JWKS_URL: (time.monotonic() + external.JWKS_CACHE_TTL_SECONDS, jwks)}\\n    )\\n    calls = _install_fake_jwks_endpoint(monkeypatch, [jwks])\\n\\n    token = jwt.encode({\\\"sub\\\": \\\"nope\\\"}, _TEST_JWT_SECRET, algorithm=\\\"HS256\\\", headers={\\\"kid\\\": \\\"unknown-key\\\"})\\n    with pytest.raises(InvalidTokenError, match=\\\"not found in JWKS\\\"):\\n        await decode_external_jwt(token, settings)\\n\\n    assert calls == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# identity_from_claims / resolve_external_identity\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_identity_from_claims_uses_configured_mapping(tmp_path):\\n    settings = _auth_settings(tmp_path)\\n    identity = identity_from_claims(\\n        {\\n            \\\"sub\\\": \\\"subject-1\\\",\\n            \\\"preferred_username\\\": \\\"alice\\\",\\n            \\\"email\\\": \\\"alice@example.com\\\",\\n            \\\"name\\\": \\\"Alice\\\",\\n        },\\n        settings,\\n    )\\n    assert identity.provider == \\\"test-provider\\\"\\n    assert identity.subject == \\\"subject-1\\\"\\n    assert identity.username == \\\"alice\\\"\\n    assert identity.email == \\\"alice@example.com\\\"\\n    assert identity.name == \\\"Alice\\\"\\n\\n\\ndef test_identity_from_claims_requires_subject(tmp_path):\\n    settings = _auth_settings(tmp_path)\\n    with pytest.raises(InvalidTokenError, match=\\\"missing required claim\\\"):\\n        identity_from_claims({\\\"preferred_username\\\": \\\"no-sub\\\"}, settings)\\n\\n\\ndef test_identity_from_claims_falls_back_to_synthesized_username(tmp_path):\\n    settings = _auth_settings(tmp_path)\\n    identity = identity_from_claims({\\\"sub\\\": \\\"subject-9\\\"}, settings)\\n    assert identity.username.startswith(\\\"test-provider-\\\")\\n    assert identity.email is None\\n    assert identity.name is None\\n\\n\\ndef test_external_access_context_uses_configured_claim_mapping(tmp_path):\\n    settings = _auth_settings(\\n        tmp_path,\\n        EXTERNAL_AUTH_ACCESS_CEILING_ENABLED=True,\\n        EXTERNAL_AUTH_ACCESS_CLAIM=\\\"openrag_mode\\\",\\n        EXTERNAL_AUTH_ACCESS_CLAIM_MAPPING='{\\\"can_view\\\":\\\"viewer\\\",\\\"can_edit\\\":\\\"editor\\\"}',\\n    )\\n    identity = identity_from_claims({\\\"sub\\\": \\\"subject-1\\\", \\\"openrag_mode\\\": \\\"can_edit\\\"}, settings)\\n\\n    context = access_context_from_identity(identity, settings)\\n\\n    assert context is not None\\n    assert context.level == \\\"editor\\\"\\n    assert external_access_allows(\\\"write\\\", context)\\n    assert external_access_allows(\\\"execute\\\", context)\\n    # An editor may delete their own resources; only ``deploy`` stays admin-only.\\n    assert external_access_allows(\\\"delete\\\", context)\\n    assert not external_access_allows(\\\"deploy\\\", context)\\n\\n\\ndef test_external_access_context_defaults_to_viewer_for_missing_claim(tmp_path):\\n    settings = _auth_settings(\\n        tmp_path,\\n        EXTERNAL_AUTH_ACCESS_CEILING_ENABLED=True,\\n        EXTERNAL_AUTH_ACCESS_CLAIM=\\\"openrag_mode\\\",\\n    )\\n    identity = identity_from_claims({\\\"sub\\\": \\\"subject-1\\\"}, settings)\\n\\n    context = access_context_from_identity(identity, settings)\\n\\n    assert context is not None\\n    assert context.level == \\\"viewer\\\"\\n    assert external_access_allows(\\\"read\\\", context)\\n    assert not external_access_allows(\\\"write\\\", context)\\n\\n\\ndef test_filter_actions_by_external_access_ceiling_uses_request_context():\\n    set_current_external_access_context(\\n        external.ExternalAccessContext(provider=\\\"test-provider\\\", subject=\\\"subject-1\\\", level=\\\"viewer\\\")\\n    )\\n    try:\\n        assert filter_actions_by_external_access_ceiling([\\\"read\\\", \\\"write\\\", \\\"delete\\\"]) == [\\\"read\\\"]\\n        assert get_current_external_access_context() is not None\\n    finally:\\n        set_current_external_access_context(None)\\n\\n\\n@pytest.mark.anyio\\nasync def test_resolve_external_identity_uses_configured_resolver(tmp_path, monkeypatch):\\n    settings = _auth_settings(tmp_path)\\n    settings.EXTERNAL_AUTH_IDENTITY_RESOLVER = \\\"tests.fake:resolver\\\"\\n\\n    async def resolver(token, auth_settings):\\n        assert token == _OPAQUE_CREDENTIAL\\n        assert auth_settings is settings\\n        return {\\n            \\\"sub\\\": \\\"opaque-subject\\\",\\n            \\\"preferred_username\\\": \\\"opaque-user\\\",\\n            \\\"email\\\": \\\"opaque@example.com\\\",\\n            \\\"name\\\": \\\"Opaque User\\\",\\n        }\\n\\n    from lfx.services import config_discovery\\n\\n    def load_resolver(import_path, *, object_kind, object_key):\\n        assert import_path == settings.EXTERNAL_AUTH_IDENTITY_RESOLVER\\n        assert object_kind == \\\"external auth resolver\\\"\\n        assert object_key == \\\"EXTERNAL_AUTH_IDENTITY_RESOLVER\\\"\\n        return resolver\\n\\n    monkeypatch.setattr(config_discovery, \\\"load_object_from_import_path\\\", load_resolver)\\n\\n    identity = await resolve_external_identity(_OPAQUE_CREDENTIAL, settings)\\n\\n    assert identity.provider == \\\"test-provider\\\"\\n    assert identity.subject == \\\"opaque-subject\\\"\\n    assert identity.username == \\\"opaque-user\\\"\\n    assert identity.email == \\\"opaque@example.com\\\"\\n    assert identity.name == \\\"Opaque User\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_resolve_external_identity_default_uses_jwt(tmp_path):\\n    settings = _auth_settings(tmp_path)\\n    token = jwt.encode(\\n        {\\n            \\\"sub\\\": \\\"subject-1\\\",\\n            \\\"preferred_username\\\": \\\"bob\\\",\\n            \\\"exp\\\": datetime.now(timezone.utc) + timedelta(minutes=5),\\n        },\\n        _TEST_JWT_SECRET,\\n        algorithm=\\\"HS256\\\",\\n    )\\n    identity = await resolve_external_identity(token, settings)\\n    assert identity.subject == \\\"subject-1\\\"\\n    assert identity.username == \\\"bob\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# F7: exp is required on both decode paths (a token without exp never expires)\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.anyio\\nasync def test_trusted_jwt_decode_rejects_missing_exp(tmp_path):\\n    \\\"\\\"\\\"Trusted-decode path must reject a token that omits exp (never expires).\\\"\\\"\\\"\\n    settings = _auth_settings(tmp_path)\\n    token = jwt.encode({\\\"sub\\\": \\\"no-exp-subject\\\"}, _TEST_JWT_SECRET, algorithm=\\\"HS256\\\")\\n    with pytest.raises(InvalidTokenError, match=\\\"missing exp\\\"):\\n        await decode_external_jwt(token, settings)\\n\\n\\n@pytest.mark.anyio\\nasync def test_jwks_decode_rejects_missing_exp(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"JWKS path must reject a validly-signed token that omits exp.\\\"\\\"\\\"\\n    settings = _jwks_settings(tmp_path)\\n    monkeypatch.setattr(external, \\\"_jwks_cache\\\", {})\\n    _install_fake_jwks_endpoint(monkeypatch, [{\\\"keys\\\": [_symmetric_jwk(_TEST_JWT_SECRET, kid=\\\"key-1\\\")]}])\\n\\n    # Validly signed, correct audience, but no exp claim.\\n    token = jwt.encode(\\n        {\\\"sub\\\": \\\"subject-1\\\", \\\"aud\\\": _JWKS_AUDIENCE},\\n        _TEST_JWT_SECRET,\\n        algorithm=\\\"HS256\\\",\\n        headers={\\\"kid\\\": \\\"key-1\\\"},\\n    )\\n    with pytest.raises(InvalidTokenError, match=\\\"validation failed\\\"):\\n        await decode_external_jwt(token, settings)\\n\\n\\n# ---------------------------------------------------------------------------\\n# F8: EXTERNAL_AUTH_JWKS_URL must be https (http allowed only for loopback)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_jwks_url_rejects_http_scheme(tmp_path):\\n    \\\"\\\"\\\"An http:// JWKS URL is rejected (MITM could swap signing keys).\\\"\\\"\\\"\\n    with pytest.raises(ValidationError, match=\\\"https\\\"):\\n        AuthSettings(\\n            CONFIG_DIR=str(tmp_path),\\n            EXTERNAL_AUTH_JWKS_URL=\\\"http://idp.example.com/.well-known/jwks.json\\\",\\n        )\\n\\n\\ndef test_jwks_url_accepts_https_scheme(tmp_path):\\n    \\\"\\\"\\\"An https:// JWKS URL is accepted.\\\"\\\"\\\"\\n    settings = AuthSettings(\\n        CONFIG_DIR=str(tmp_path),\\n        EXTERNAL_AUTH_JWKS_URL=\\\"https://idp.example.com/.well-known/jwks.json\\\",\\n    )\\n    assert settings.EXTERNAL_AUTH_JWKS_URL == \\\"https://idp.example.com/.well-known/jwks.json\\\"\\n\\n\\ndef test_jwks_url_allows_http_for_localhost(tmp_path):\\n    \\\"\\\"\\\"http:// is permitted for loopback hosts to keep local development usable.\\\"\\\"\\\"\\n    for url in (\\n        \\\"http://localhost:8080/jwks.json\\\",\\n        \\\"http://127.0.0.1:8080/jwks.json\\\",\\n        \\\"http://[::1]:8080/jwks.json\\\",\\n    ):\\n        settings = AuthSettings(CONFIG_DIR=str(tmp_path), EXTERNAL_AUTH_JWKS_URL=url)\\n        assert url == settings.EXTERNAL_AUTH_JWKS_URL\\n\\n\\ndef test_jwks_url_none_is_allowed(tmp_path):\\n    \\\"\\\"\\\"JWKS URL is optional (None / empty) so the validator must not reject it.\\\"\\\"\\\"\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path), EXTERNAL_AUTH_JWKS_URL=None)\\n    assert settings.EXTERNAL_AUTH_JWKS_URL is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_fetch_jwks_guard_rejects_non_https(monkeypatch):\\n    \\\"\\\"\\\"Belt-and-suspenders: _fetch_jwks itself refuses a non-https URL.\\\"\\\"\\\"\\n    monkeypatch.setattr(external, \\\"_jwks_cache\\\", {})\\n    calls = _install_fake_jwks_endpoint(monkeypatch, [{\\\"keys\\\": []}])\\n    with pytest.raises(InvalidTokenError, match=\\\"https\\\"):\\n        await external._fetch_jwks(\\\"http://idp.example.com/jwks.json\\\")\\n    # No network call is made for a rejected scheme.\\n    assert calls == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# F11: EXTERNAL_AUTH_PROVIDER normalizes once at the config boundary\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_external_auth_provider_empty_normalizes_to_external(tmp_path):\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path), EXTERNAL_AUTH_PROVIDER=\\\"\\\")\\n    assert settings.EXTERNAL_AUTH_PROVIDER == \\\"external\\\"\\n\\n\\ndef test_external_auth_provider_whitespace_normalizes_to_external(tmp_path):\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path), EXTERNAL_AUTH_PROVIDER=\\\"   \\\")\\n    assert settings.EXTERNAL_AUTH_PROVIDER == \\\"external\\\"\\n\\n\\ndef test_external_auth_provider_strips_whitespace(tmp_path):\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path), EXTERNAL_AUTH_PROVIDER=\\\"  okta  \\\")\\n    assert settings.EXTERNAL_AUTH_PROVIDER == \\\"okta\\\"\\n\\n\\ndef test_external_auth_provider_normalizes_on_assignment(tmp_path):\\n    \\\"\\\"\\\"validate_assignment=True means setattr must normalize too (the test helper path).\\\"\\\"\\\"\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path))\\n    settings.EXTERNAL_AUTH_PROVIDER = \\\"  \\\"\\n    assert settings.EXTERNAL_AUTH_PROVIDER == \\\"external\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# F12: a configured access-claim mapping is authoritative (no alias fallthrough)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_access_mapping_unmapped_value_does_not_elevate_via_aliases(tmp_path):\\n    \\\"\\\"\\\"Unmapped value falls to the default, not the built-in alias table.\\n\\n    With a non-empty mapping, a claim value absent from it falls to the default\\n    (viewer) instead of being reinterpreted through the built-in alias table.\\n    \\\"\\\"\\\"\\n    settings = _auth_settings(\\n        tmp_path,\\n        EXTERNAL_AUTH_ACCESS_CEILING_ENABLED=True,\\n        EXTERNAL_AUTH_ACCESS_CLAIM=\\\"role\\\",\\n        EXTERNAL_AUTH_ACCESS_CLAIM_MAPPING='{\\\"can_view\\\":\\\"viewer\\\",\\\"can_edit\\\":\\\"editor\\\"}',\\n    )\\n    # Raw \\\"admin\\\" is an alias for the admin level, but it is NOT a key in the\\n    # configured mapping, so it must NOT elevate.\\n    identity = identity_from_claims({\\\"sub\\\": \\\"subject-1\\\", \\\"role\\\": \\\"admin\\\"}, settings)\\n\\n    context = access_context_from_identity(identity, settings)\\n\\n    assert context is not None\\n    assert context.level == \\\"viewer\\\"  # default, not admin\\n    assert external_access_allows(\\\"read\\\", context)\\n    assert not external_access_allows(\\\"write\\\", context)\\n    assert not external_access_allows(\\\"delete\\\", context)\\n\\n\\ndef test_access_mapping_unmapped_value_uses_configured_default(tmp_path):\\n    \\\"\\\"\\\"The configured default level is applied for an unmapped claim value.\\n\\n    The configured default level (not the viewer floor) is applied for an\\n    unmapped claim value when a mapping is present.\\n    \\\"\\\"\\\"\\n    settings = _auth_settings(\\n        tmp_path,\\n        EXTERNAL_AUTH_ACCESS_CEILING_ENABLED=True,\\n        EXTERNAL_AUTH_ACCESS_CLAIM=\\\"role\\\",\\n        EXTERNAL_AUTH_ACCESS_CLAIM_MAPPING='{\\\"can_edit\\\":\\\"editor\\\"}',\\n        EXTERNAL_AUTH_DEFAULT_ACCESS_LEVEL=\\\"editor\\\",\\n    )\\n    identity = identity_from_claims({\\\"sub\\\": \\\"subject-1\\\", \\\"role\\\": \\\"admin\\\"}, settings)\\n\\n    context = access_context_from_identity(identity, settings)\\n\\n    assert context is not None\\n    assert context.level == \\\"editor\\\"\\n\\n\\ndef test_no_mapping_still_interprets_raw_claim_via_aliases(tmp_path):\\n    \\\"\\\"\\\"With no mapping configured, built-in aliases still apply to the raw claim.\\n\\n    When NO mapping is configured the built-in aliases still apply to the raw\\n    claim value, so a raw 'admin' claim maps to the admin level.\\n    \\\"\\\"\\\"\\n    settings = _auth_settings(\\n        tmp_path,\\n        EXTERNAL_AUTH_ACCESS_CEILING_ENABLED=True,\\n        EXTERNAL_AUTH_ACCESS_CLAIM=\\\"role\\\",\\n    )\\n    identity = identity_from_claims({\\\"sub\\\": \\\"subject-1\\\", \\\"role\\\": \\\"admin\\\"}, settings)\\n\\n    context = access_context_from_identity(identity, settings)\\n\\n    assert context is not None\\n    assert context.level == \\\"admin\\\"\\n    assert external_access_allows(\\\"delete\\\", context)\\n\\n\\ndef test_configured_but_all_invalid_mapping_does_not_elevate_via_aliases(tmp_path):\\n    \\\"\\\"\\\"A configured-but-all-invalid mapping must still suppress alias fallthrough.\\n\\n    If an operator configures EXTERNAL_AUTH_ACCESS_CLAIM_MAPPING but every entry\\n    is invalid/typo'd, the parsed dict is empty. Gating the alias fallthrough on\\n    the parsed dict (``not mapping``) would treat this as \\\"no mapping\\\" and let a\\n    raw \\\"admin\\\" claim self-elevate through the built-in alias table, re-opening\\n    the hole F12 closes. The gate is on the RAW setting being configured, so an\\n    unmapped claim must fall to the default (viewer floor) instead.\\n    \\\"\\\"\\\"\\n    settings = _auth_settings(\\n        tmp_path,\\n        EXTERNAL_AUTH_ACCESS_CEILING_ENABLED=True,\\n        EXTERNAL_AUTH_ACCESS_CLAIM=\\\"role\\\",\\n        # Every value is an unrecognized level -> _access_claim_mapping returns {}.\\n        EXTERNAL_AUTH_ACCESS_CLAIM_MAPPING='{\\\"can_view\\\":\\\"bogus\\\",\\\"can_edit\\\":\\\"typo\\\"}',\\n    )\\n    identity = identity_from_claims({\\\"sub\\\": \\\"subject-1\\\", \\\"role\\\": \\\"admin\\\"}, settings)\\n\\n    context = access_context_from_identity(identity, settings)\\n\\n    assert context is not None\\n    assert context.level == \\\"viewer\\\"  # default/floor, NOT admin\\n    assert external_access_allows(\\\"read\\\", context)\\n    assert not external_access_allows(\\\"write\\\", context)\\n    assert not external_access_allows(\\\"delete\\\", context)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/auth/test_mcp_encryption.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a26d6813d973be49a56a8add7eb5426c08b6139fcb970e2afbf4600d6532d0f\",\"content\":\"\\\"\\\"\\\"Test MCP authentication encryption functionality.\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom cryptography.fernet import Fernet\\nfrom langflow.services.auth.mcp_encryption import (\\n    decrypt_auth_settings,\\n    encrypt_auth_settings,\\n    is_encrypted,\\n)\\nfrom langflow.services.auth.service import AuthService\\nfrom lfx.services.settings.auth import AuthSettings\\nfrom pydantic import SecretStr\\n\\n\\n@pytest.fixture\\ndef mock_auth_service(tmp_path):\\n    \\\"\\\"\\\"Create a real AuthService for testing encryption.\\\"\\\"\\\"\\n    # Create real auth settings with a valid Fernet key\\n    valid_key = Fernet.generate_key()\\n    valid_key_str = valid_key.decode(\\\"utf-8\\\")\\n\\n    auth_settings = AuthSettings(CONFIG_DIR=str(tmp_path))\\n    auth_settings.SECRET_KEY = SecretStr(valid_key_str)\\n\\n    settings_service = SimpleNamespace(\\n        auth_settings=auth_settings,\\n        settings=SimpleNamespace(config_dir=str(tmp_path)),\\n    )\\n    return AuthService(settings_service)\\n\\n\\n@pytest.fixture\\ndef sample_auth_settings():\\n    \\\"\\\"\\\"Sample auth settings with sensitive data.\\\"\\\"\\\"\\n    return {\\n        \\\"auth_type\\\": \\\"oauth\\\",\\n        \\\"oauth_host\\\": \\\"localhost\\\",\\n        \\\"oauth_port\\\": \\\"3000\\\",\\n        \\\"oauth_server_url\\\": \\\"http://localhost:3000\\\",\\n        \\\"oauth_callback_path\\\": \\\"/callback\\\",\\n        \\\"oauth_client_id\\\": \\\"my-client-id\\\",\\n        \\\"oauth_client_secret\\\": \\\"super-secret-password-123\\\",  # pragma: allowlist secret\\n        \\\"oauth_auth_url\\\": \\\"https://oauth.example.com/auth\\\",\\n        \\\"oauth_token_url\\\": \\\"https://oauth.example.com/token\\\",\\n        \\\"oauth_mcp_scope\\\": \\\"read write\\\",\\n        \\\"oauth_provider_scope\\\": \\\"user:email\\\",\\n    }\\n\\n\\nclass TestMCPEncryption:\\n    \\\"\\\"\\\"Test MCP encryption functionality.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.services.auth.utils.get_auth_service\\\")\\n    def test_encrypt_auth_settings(self, mock_get_auth, mock_auth_service, sample_auth_settings):\\n        \\\"\\\"\\\"Test that sensitive fields are encrypted.\\\"\\\"\\\"\\n        mock_get_auth.return_value = mock_auth_service\\n\\n        # Encrypt the settings\\n        encrypted = encrypt_auth_settings(sample_auth_settings)\\n\\n        # Check that sensitive fields are encrypted\\n        assert encrypted is not None\\n        assert encrypted[\\\"oauth_client_secret\\\"] != sample_auth_settings[\\\"oauth_client_secret\\\"]\\n\\n        # Check that non-sensitive fields remain unchanged\\n        assert encrypted[\\\"auth_type\\\"] == sample_auth_settings[\\\"auth_type\\\"]\\n        assert encrypted[\\\"oauth_host\\\"] == sample_auth_settings[\\\"oauth_host\\\"]\\n        assert encrypted[\\\"oauth_client_id\\\"] == sample_auth_settings[\\\"oauth_client_id\\\"]\\n\\n    @patch(\\\"langflow.services.auth.utils.get_auth_service\\\")\\n    def test_decrypt_auth_settings(self, mock_get_auth, mock_auth_service, sample_auth_settings):\\n        \\\"\\\"\\\"Test that encrypted fields can be decrypted.\\\"\\\"\\\"\\n        mock_get_auth.return_value = mock_auth_service\\n\\n        # First encrypt the settings\\n        encrypted = encrypt_auth_settings(sample_auth_settings)\\n\\n        # Then decrypt them\\n        decrypted = decrypt_auth_settings(encrypted)\\n\\n        # Verify all fields match the original\\n        assert decrypted == sample_auth_settings\\n\\n    def test_encrypt_none_returns_none(self):\\n        \\\"\\\"\\\"Test that encrypting None returns None.\\\"\\\"\\\"\\n        result = encrypt_auth_settings(None)\\n        assert result is None\\n\\n    def test_decrypt_none_returns_none(self):\\n        \\\"\\\"\\\"Test that decrypting None returns None.\\\"\\\"\\\"\\n        result = decrypt_auth_settings(None)\\n        assert result is None\\n\\n    def test_encrypt_empty_dict(self):\\n        \\\"\\\"\\\"Test that encrypting empty dict returns empty dict.\\\"\\\"\\\"\\n        result = encrypt_auth_settings({})\\n        assert result == {}\\n\\n    @patch(\\\"langflow.services.auth.utils.get_auth_service\\\")\\n    def test_idempotent_encryption(self, mock_get_auth, mock_auth_service, sample_auth_settings):\\n        \\\"\\\"\\\"Test that encrypting already encrypted data doesn't double-encrypt.\\\"\\\"\\\"\\n        mock_get_auth.return_value = mock_auth_service\\n\\n        # First encryption\\n        encrypted_once = encrypt_auth_settings(sample_auth_settings)\\n\\n        # Second encryption should detect already encrypted fields\\n        encrypted_twice = encrypt_auth_settings(encrypted_once)\\n\\n        # Should be the same\\n        assert encrypted_once == encrypted_twice\\n\\n    @patch(\\\"langflow.services.auth.utils.get_auth_service\\\")\\n    def test_partial_auth_settings(self, mock_get_auth, mock_auth_service):\\n        \\\"\\\"\\\"Test encryption with only some sensitive fields present.\\\"\\\"\\\"\\n        mock_get_auth.return_value = mock_auth_service\\n\\n        partial_settings = {\\n            \\\"auth_type\\\": \\\"api\\\",\\n            \\\"api_key\\\": \\\"sk-test-api-key-123\\\",  # pragma: allowlist secret\\n            \\\"username\\\": \\\"admin\\\",\\n        }\\n\\n        encrypted = encrypt_auth_settings(partial_settings)\\n\\n        # API key should be encrypted\\n        assert encrypted[\\\"api_key\\\"] != partial_settings[\\\"api_key\\\"]\\n\\n        # Other fields unchanged\\n        assert encrypted[\\\"auth_type\\\"] == partial_settings[\\\"auth_type\\\"]\\n        assert encrypted[\\\"username\\\"] == partial_settings[\\\"username\\\"]\\n\\n    @patch(\\\"langflow.services.auth.utils.get_auth_service\\\")\\n    def test_backward_compatibility(self, mock_get_auth, mock_auth_service):\\n        \\\"\\\"\\\"Test that plaintext data is handled gracefully during decryption.\\\"\\\"\\\"\\n        mock_get_auth.return_value = mock_auth_service\\n\\n        # Simulate legacy plaintext data\\n        plaintext_settings = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_client_secret\\\": \\\"plaintext-secret\\\",  # pragma: allowlist secret\\n            \\\"oauth_client_id\\\": \\\"client-123\\\",\\n        }\\n\\n        # Decryption should handle plaintext gracefully\\n        decrypted = decrypt_auth_settings(plaintext_settings)\\n\\n        # Should return the same data\\n        assert decrypted == plaintext_settings\\n\\n    @patch(\\\"langflow.services.auth.utils.get_auth_service\\\")\\n    def test_is_encrypted(self, mock_get_auth, mock_auth_service):\\n        \\\"\\\"\\\"Test the is_encrypted helper function.\\\"\\\"\\\"\\n        mock_get_auth.return_value = mock_auth_service\\n\\n        # Test with plaintext\\n        assert not is_encrypted(\\\"plaintext-value\\\")\\n        assert not is_encrypted(\\\"\\\")\\n        assert not is_encrypted(None)\\n\\n        # Test with encrypted value\\n        encrypted_value = mock_auth_service.encrypt_api_key(\\\"secret-value\\\")\\n        assert is_encrypted(encrypted_value)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/auth/test_pluggable_auth.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fa7e0f1eb644f3ff50216c63cbbb0c8cadf907a8ae593320f8011f40cad47e8a\",\"content\":\"from __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langflow.services.auth import utils as auth_utils\\nfrom langflow.services.base import Service\\nfrom langflow.services.schema import ServiceType\\nfrom lfx.services.manager import get_service_manager\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\nclass DummyAuthService(Service):\\n    name = ServiceType.AUTH_SERVICE.value\\n\\n    def __init__(self, settings_service=None):\\n        self.settings_service = settings_service or SimpleNamespace()\\n        self.calls: list[tuple[str, tuple]] = []\\n        self.set_ready()\\n\\n    async def api_key_security(self, query_param, header_param):\\n        call = (\\\"api_key_security\\\", query_param, header_param)\\n        self.calls.append(call)\\n        return {\\\"call\\\": call}\\n\\n    async def get_current_user(self, token, query_param, header_param, db, external_token=None):\\n        call = (\\\"get_current_user\\\", token, query_param, header_param, external_token)\\n        self.calls.append(call)\\n        return {\\\"user\\\": \\\"dummy\\\", \\\"db\\\": db}\\n\\n\\n@pytest.fixture\\ndef dummy_auth_service():\\n    \\\"\\\"\\\"A single DummyAuthService instance for patching.\\\"\\\"\\\"\\n    return DummyAuthService()\\n\\n\\n@pytest.fixture\\ndef dummy_auth_registration(dummy_auth_service):\\n    \\\"\\\"\\\"Patch utils to return our DummyAuthService instance so delegation is tested.\\\"\\\"\\\"\\n    service_manager = get_service_manager()\\n    try:\\n        _ = service_manager.get(ServiceType.SETTINGS_SERVICE)\\n        if not service_manager._plugins_discovered:\\n            service_manager.discover_plugins(None)\\n    except Exception:  # noqa: S110\\n        pass\\n\\n    previous_class = service_manager.service_classes.get(ServiceType.AUTH_SERVICE)\\n    previous_instance = service_manager.services.pop(ServiceType.AUTH_SERVICE, None)\\n    service_manager.register_service_class(ServiceType.AUTH_SERVICE, DummyAuthService, override=True)\\n\\n    try:\\n        with patch.object(auth_utils, \\\"get_auth_service\\\", return_value=dummy_auth_service):\\n            yield dummy_auth_service\\n    finally:\\n        service_manager.services.pop(ServiceType.AUTH_SERVICE, None)\\n        if previous_class is not None:\\n            service_manager.service_classes[ServiceType.AUTH_SERVICE] = previous_class\\n        else:\\n            service_manager.service_classes.pop(ServiceType.AUTH_SERVICE, None)\\n        if previous_instance is not None:\\n            service_manager.services[ServiceType.AUTH_SERVICE] = previous_instance\\n\\n\\n@pytest.mark.anyio\\nasync def test_api_key_security_uses_registered_service(dummy_auth_registration):\\n    dummy = dummy_auth_registration\\n    sentinel = await auth_utils.api_key_security(\\\"query\\\", \\\"header\\\")\\n\\n    assert (\\\"api_key_security\\\", \\\"query\\\", \\\"header\\\") in dummy.calls\\n    assert sentinel[\\\"call\\\"] == (\\\"api_key_security\\\", \\\"query\\\", \\\"header\\\")\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_user_delegates_to_service(dummy_auth_registration):\\n    dummy = dummy_auth_registration\\n    db = MagicMock(spec=AsyncSession)\\n    # get_current_user now extracts the external credential from the request and\\n    # threads it to the service as external_token. With external auth disabled the\\n    # extractor returns None, so delegation records external_token=None.\\n    request = SimpleNamespace(headers={}, cookies={})\\n    response = await auth_utils.get_current_user(request, token=None, query_param=\\\"q\\\", header_param=None, db=db)\\n\\n    assert (\\\"get_current_user\\\", None, \\\"q\\\", None, None) in dummy.calls\\n    assert response[\\\"user\\\"] == \\\"dummy\\\"\\n    assert response[\\\"db\\\"] is db\\n\\n\\ndef test_get_auth_service_replaces_lfx_no_op_stub():\\n    \\\"\\\"\\\"LFX's no-op auth service must never be what Langflow resolves.\\n\\n    It self-registers for the ``auth_service`` slot at import time, so any process that\\n    touches auth before ``register_all_service_factories()`` would otherwise get a service\\n    that raises ``NotImplementedError`` for user/token operations and answers API-key\\n    checks with ``None``.\\n    \\\"\\\"\\\"\\n    from langflow.services.auth.service import AuthService as LangflowAuthService\\n    from langflow.services.deps import get_auth_service\\n    from lfx.services.auth.service import AuthService as LFXNoOpAuthService\\n\\n    service_manager = get_service_manager()\\n    previous_class = service_manager.service_classes.get(ServiceType.AUTH_SERVICE)\\n    previous_instance = service_manager.services.pop(ServiceType.AUTH_SERVICE, None)\\n    service_manager.register_service_class(ServiceType.AUTH_SERVICE, LFXNoOpAuthService, override=True)\\n\\n    try:\\n        assert isinstance(service_manager.get(ServiceType.AUTH_SERVICE), LFXNoOpAuthService)\\n        assert isinstance(get_auth_service(), LangflowAuthService)\\n    finally:\\n        service_manager.services.pop(ServiceType.AUTH_SERVICE, None)\\n        if previous_class is not None:\\n            service_manager.service_classes[ServiceType.AUTH_SERVICE] = previous_class\\n        else:\\n            service_manager.service_classes.pop(ServiceType.AUTH_SERVICE, None)\\n        if previous_instance is not None:\\n            service_manager.services[ServiceType.AUTH_SERVICE] = previous_instance\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/_common.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"678aa4e3f26aa74d5779a0c98e4c44219f0f88ffda5ac53b35e155fa1f6d0e52\",\"content\":\"\\\"\\\"\\\"Shared helpers for the split authorization-helper tests.\\n\\nAfter the ``utils.py`` refactor on PR #13153, the runtime helpers live in\\nthree modules:\\n\\n* ``langflow.services.authorization.audit``   \u2014 batched audit pipeline\\n* ``langflow.services.authorization.guards``  \u2014 ``ensure_*_permission`` family\\n* ``langflow.services.authorization.listing`` \u2014 ``filter_visible_resources``\\n\\nEach module imports ``get_settings_service`` / ``get_authorization_service``\\nat import time, so a test that wants to stub the live services must patch the\\nattributes on *every* module that uses them. This file centralises the\\npatching shape so individual test files stay focused.\\n\\nPytest fixtures (``fake_user``, ``fake_superuser``) live in\\n``conftest.py`` so they are discovered automatically without per-file imports.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\n\\nfrom langflow.services.authorization import audit as authz_audit\\nfrom langflow.services.authorization import guards as authz_guards\\nfrom langflow.services.authorization import listing as authz_listing\\n\\n\\nclass _StubAuthorizationService:\\n    \\\"\\\"\\\"Minimal stand-in for BaseAuthorizationService that records calls.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        *,\\n        allow: bool = True,\\n        batch_results: list[bool] | None = None,\\n        supports_api_key_scopes: bool = False,\\n        visible_ids: list | None = None,\\n    ) -> None:\\n        self.allow = allow\\n        self.batch_results = batch_results\\n        self._supports_api_key_scopes = supports_api_key_scopes\\n        # ``None`` mirrors the OSS pass-through (declines to prefilter); a list\\n        # mirrors a registered plugin returning a concrete visible-id set.\\n        self.visible_ids = visible_ids\\n        self.calls: list[dict] = []\\n        self.batch_calls: list[dict] = []\\n        self.visible_calls: list[dict] = []\\n\\n    async def enforce(self, **kwargs) -> bool:\\n        self.calls.append(kwargs)\\n        return self.allow\\n\\n    async def batch_enforce(self, **kwargs) -> list[bool]:\\n        self.batch_calls.append(kwargs)\\n        if self.batch_results is not None:\\n            return self.batch_results\\n        return [self.allow] * len(kwargs.get(\\\"requests\\\", []))\\n\\n    async def list_visible_resource_ids(self, **kwargs) -> list | None:\\n        self.visible_calls.append(kwargs)\\n        return self.visible_ids\\n\\n    async def supports_api_key_scopes(self) -> bool:\\n        return self._supports_api_key_scopes\\n\\n\\ndef install_settings(\\n    monkeypatch,\\n    *,\\n    authz_enabled: bool,\\n    audit_enabled: bool = False,\\n    audit_durable: bool = False,\\n) -> None:\\n    \\\"\\\"\\\"Patch settings on every module that calls ``get_settings_service``.\\\"\\\"\\\"\\n    settings = SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_ENABLED=authz_enabled,\\n            AUTHZ_AUDIT_ENABLED=audit_enabled,\\n            AUTHZ_AUDIT_DURABLE=audit_durable,\\n        ),\\n    )\\n    for module in (authz_audit, authz_guards, authz_listing):\\n        monkeypatch.setattr(module, \\\"get_settings_service\\\", lambda s=settings: s)\\n\\n\\ndef install_authz(monkeypatch, service: _StubAuthorizationService) -> None:\\n    \\\"\\\"\\\"Patch the authorization service factory on guards + listing.\\\"\\\"\\\"\\n    for module in (authz_guards, authz_listing):\\n        monkeypatch.setattr(module, \\\"get_authorization_service\\\", lambda s=service: s)\\n\\n\\ndef install_audit_recorder(monkeypatch) -> list[dict]:\\n    \\\"\\\"\\\"Replace ``audit_decision`` with a recorder so tests can assert audit writes.\\n\\n    ``ensure_permission`` in ``guards`` reaches for ``audit.audit_decision``\\n    via the module reference (``from ... import audit as _audit``), so patching\\n    the function attribute on the ``audit`` module is sufficient \u2014 every caller\\n    sees the recorder.\\n    \\\"\\\"\\\"\\n    calls: list[dict] = []\\n\\n    async def _recorder(**kwargs):\\n        calls.append(kwargs)\\n\\n    monkeypatch.setattr(authz_audit, \\\"audit_decision\\\", _recorder)\\n    return calls\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/_policy_double.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"094defe1697a82e337eba8b070c0e9be7e60d741959388ea138c6a45dc64f0fd\",\"content\":\"\\\"\\\"\\\"In-test authorization enforcer for OSS RBAC integration tests.\\n\\nThe OSS :class:`LangflowAuthorizationService` is a pass-through: ``enforce()``\\nalways returns ``True`` and ``SUPPORTS_CROSS_USER_FETCH`` is ``False``. That makes\\nit impossible to assert allow/deny semantics against the real routes \u2014 every\\nrequest is allowed and cross-user fetch never widens. This module supplies a\\nminimal, dependency-free stand-in that derives allow/deny from the seeded\\n``authz_role`` / ``authz_role_assignment`` / ``authz_share`` rows. It is enough\\nto validate that the OSS guard wiring, domain resolution, share-aware fetch, and\\n``deny_to_404`` masking behave correctly under a *real* allow/deny signal \u2014\\nwithout pulling in the EE Casbin package.\\n\\nInstall it for the duration of a test with :func:`install_policy_authz`, which\\nswaps the service registered on the service manager so every\\n``get_authorization_service()`` call site (guards, fetch, listing, helpers) sees\\nit, and flips ``AUTHZ_ENABLED=True`` / ``AUTHZ_SUPERUSER_BYPASS=False``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import UUID\\n\\nfrom langflow.services.database.models.auth import (\\n    AuthzRole,\\n    AuthzRoleAssignment,\\n    AuthzShare,\\n    AuthzTeam,\\n    AuthzTeamMember,\\n)\\nfrom lfx.services.authorization.base import BaseAuthorizationService, ResourceVisibilityScope\\nfrom sqlmodel import col, select\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Iterator, Sequence\\n\\n    from lfx.services.settings.service import SettingsService\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n# Actions granted by each AuthzShare.permission_level, ordered weakest to\\n# strongest. This is the canonical share contract enforced by the enterprise\\n# Casbin plugin (share_sync.PERMISSION_ACTIONS) and described by the share UI\\n# (Viewer/Runner/Editor/Admin): ``execute`` grants ``read`` so a runner can\\n# fetch the flow it invokes; ``write`` grants ``read`` + ``execute`` (an editor\\n# can also view and run); ``admin`` additionally grants ``delete``. The\\n# enterprise repo's check-authz-share-contract.py compares this dict against\\n# the plugin's mapping \u2014 keep the two in lockstep.\\n_SHARE_LEVEL_ACTIONS: dict[str, frozenset[str]] = {\\n    \\\"read\\\": frozenset({\\\"read\\\"}),\\n    \\\"execute\\\": frozenset({\\\"read\\\", \\\"execute\\\"}),\\n    \\\"write\\\": frozenset({\\\"read\\\", \\\"write\\\", \\\"execute\\\"}),\\n    \\\"admin\\\": frozenset({\\\"read\\\", \\\"write\\\", \\\"execute\\\", \\\"delete\\\"}),\\n}\\n\\n# Built-in role permission sets \u2014 mirrors migration 7c8d9e0f1a2b_authz_foundations\\n# so the test does not depend on whether the test DB ran the seed step.\\n_VIEWER: tuple[str, ...] = (\\n    \\\"flow:read\\\",\\n    \\\"flow:execute\\\",\\n    \\\"deployment:read\\\",\\n    \\\"project:read\\\",\\n    \\\"knowledge_base:read\\\",\\n    \\\"variable:read\\\",\\n    \\\"file:read\\\",\\n)\\n_DEVELOPER_EXTRA: tuple[str, ...] = (\\n    \\\"flow:write\\\",\\n    \\\"flow:create\\\",\\n    \\\"deployment:write\\\",\\n    \\\"deployment:create\\\",\\n    \\\"deployment:execute\\\",\\n    \\\"project:write\\\",\\n    \\\"project:create\\\",\\n    \\\"knowledge_base:write\\\",\\n    \\\"knowledge_base:create\\\",\\n    \\\"knowledge_base:ingest\\\",\\n    \\\"variable:write\\\",\\n    \\\"variable:create\\\",\\n    \\\"file:write\\\",\\n    \\\"file:create\\\",\\n)\\n_ADMIN_EXTRA: tuple[str, ...] = (\\n    \\\"flow:delete\\\",\\n    \\\"flow:deploy\\\",\\n    \\\"deployment:delete\\\",\\n    \\\"project:delete\\\",\\n    \\\"knowledge_base:delete\\\",\\n    \\\"variable:delete\\\",\\n    \\\"file:delete\\\",\\n    \\\"share:read\\\",\\n    \\\"share:create\\\",\\n    \\\"share:update\\\",\\n    \\\"share:delete\\\",\\n)\\nSYSTEM_ROLE_PERMISSIONS: dict[str, list[str]] = {\\n    \\\"viewer\\\": list(_VIEWER),\\n    \\\"developer\\\": list(_VIEWER + _DEVELOPER_EXTRA),\\n    \\\"admin\\\": list(_VIEWER + _DEVELOPER_EXTRA + _ADMIN_EXTRA),\\n}\\n\\n\\nclass PolicyTestAuthorizationService(BaseAuthorizationService):\\n    \\\"\\\"\\\"Allow/deny enforcer backed by the authz_* policy tables (test-only).\\n\\n    A request is allowed when the user holds a role (covering the request domain)\\n    whose permissions include ``{resource}:{action}``, OR when an ``authz_share``\\n    row grants the action on the specific resource. Superusers bypass only when\\n    ``AUTHZ_SUPERUSER_BYPASS`` is set.\\n    \\\"\\\"\\\"\\n\\n    SUPPORTS_CROSS_USER_FETCH = True\\n    SUPPORTS_API_KEY_SCOPES = True\\n\\n    def __init__(self, settings_service: SettingsService) -> None:\\n        super().__init__()\\n        self.settings_service = settings_service\\n        self.set_ready()\\n\\n    async def is_enabled(self) -> bool:\\n        return bool(self.settings_service.auth_settings.AUTHZ_ENABLED)\\n\\n    async def enforce(\\n        self,\\n        *,\\n        user_id: UUID,\\n        domain: str,\\n        obj: str,\\n        act: str,\\n        context: dict[str, Any] | None = None,\\n    ) -> bool:\\n        auth_settings = self.settings_service.auth_settings\\n        if context and context.get(\\\"is_superuser\\\") and getattr(auth_settings, \\\"AUTHZ_SUPERUSER_BYPASS\\\", False):\\n            return True\\n\\n        resource_type, _, resource_id_str = obj.partition(\\\":\\\")\\n        # Each enforce opens its own session \u2014 a real plugin reads policy from its\\n        # own connection, independent of the request's transaction.\\n        from langflow.services.deps import session_scope\\n\\n        async with session_scope() as session:\\n            if await self._role_allows(session, user_id, domain, resource_type, act):\\n                return True\\n            if resource_id_str and resource_id_str != \\\"*\\\":\\n                with contextlib.suppress(ValueError):\\n                    resource_id = UUID(str(resource_id_str))\\n                    if await self._share_allows(session, resource_id, user_id, resource_type, act):\\n                        return True\\n        return False\\n\\n    async def batch_enforce(\\n        self,\\n        *,\\n        user_id: UUID,\\n        domain: str,\\n        requests: Sequence[tuple[str, str]],\\n        context: dict[str, Any] | None = None,\\n    ) -> list[bool]:\\n        return [\\n            await self.enforce(user_id=user_id, domain=domain, obj=obj, act=act, context=context)\\n            for obj, act in requests\\n        ]\\n\\n    async def get_resource_visibility(\\n        self,\\n        *,\\n        user_id: UUID,\\n        resource_type: str,\\n        domain: str = \\\"*\\\",  # noqa: ARG002 - scopes are returned rather than matched here\\n        act: str = \\\"read\\\",\\n        context: dict[str, Any] | None = None,  # noqa: ARG002\\n    ) -> ResourceVisibilityScope:\\n        \\\"\\\"\\\"Return global/scoped role grants plus direct and team share IDs.\\\"\\\"\\\"\\n        from langflow.services.deps import session_scope\\n\\n        resource_ids: set[UUID] = set()\\n        workspace_ids: set[UUID] = set()\\n        project_ids: set[UUID] = set()\\n        async with session_scope() as session:\\n            assignments = (\\n                await session.exec(select(AuthzRoleAssignment).where(AuthzRoleAssignment.user_id == user_id))\\n            ).all()\\n            role_ids = [assignment.role_id for assignment in assignments]\\n            roles = (\\n                (await session.exec(select(AuthzRole).where(col(AuthzRole.id).in_(role_ids)))).all() if role_ids else []\\n            )\\n            permissions_by_role = {role.id: set(role.permissions or []) for role in roles}\\n            needed = f\\\"{resource_type}:{act}\\\"\\n            wildcard = f\\\"{resource_type}:*\\\"\\n            for assignment in assignments:\\n                permissions = permissions_by_role.get(assignment.role_id, set())\\n                if not ({needed, wildcard, \\\"*:*\\\"} & permissions):\\n                    continue\\n                if assignment.domain_type == \\\"global\\\":\\n                    return ResourceVisibilityScope(all_resources=True)\\n                if assignment.domain_id is None:\\n                    continue\\n                if assignment.domain_type == \\\"workspace\\\":\\n                    workspace_ids.add(assignment.domain_id)\\n                elif assignment.domain_type == \\\"project\\\":\\n                    project_ids.add(assignment.domain_id)\\n\\n            shares = (await session.exec(select(AuthzShare).where(AuthzShare.resource_type == resource_type))).all()\\n            for share in shares:\\n                if act not in _SHARE_LEVEL_ACTIONS.get(share.permission_level, frozenset()):\\n                    continue\\n                if await _share_targets_user(session, share, user_id):\\n                    resource_ids.add(share.resource_id)\\n\\n        return ResourceVisibilityScope(\\n            resource_ids=tuple(sorted(resource_ids, key=str)),\\n            workspace_ids=tuple(sorted(workspace_ids, key=str)),\\n            project_ids=tuple(sorted(project_ids, key=str)),\\n        )\\n\\n    async def _role_allows(\\n        self,\\n        session: AsyncSession,\\n        user_id: UUID,\\n        domain: str,\\n        resource_type: str,\\n        act: str,\\n    ) -> bool:\\n        assignments = (\\n            await session.exec(select(AuthzRoleAssignment).where(AuthzRoleAssignment.user_id == user_id))\\n        ).all()\\n        role_ids = [a.role_id for a in assignments if _assignment_covers(a, domain)]\\n        if not role_ids:\\n            return False\\n        roles = (await session.exec(select(AuthzRole).where(col(AuthzRole.id).in_(role_ids)))).all()\\n        needed = f\\\"{resource_type}:{act}\\\"\\n        wildcard = f\\\"{resource_type}:*\\\"\\n        return any(\\n            needed in (role.permissions or [])\\n            or wildcard in (role.permissions or [])\\n            or \\\"*:*\\\" in (role.permissions or [])\\n            for role in roles\\n        )\\n\\n    async def _share_allows(\\n        self,\\n        session: AsyncSession,\\n        resource_id: UUID,\\n        user_id: UUID,\\n        resource_type: str,\\n        act: str,\\n    ) -> bool:\\n        shares = (\\n            await session.exec(\\n                select(AuthzShare).where(\\n                    AuthzShare.resource_type == resource_type,\\n                    AuthzShare.resource_id == resource_id,\\n                )\\n            )\\n        ).all()\\n        for share in shares:\\n            if not await _share_targets_user(session, share, user_id):\\n                continue\\n            if act in _SHARE_LEVEL_ACTIONS.get(share.permission_level, frozenset()):\\n                return True\\n        return False\\n\\n\\ndef _assignment_covers(assignment: AuthzRoleAssignment, request_domain: str) -> bool:\\n    \\\"\\\"\\\"A global assignment covers every domain; a scoped one must match exactly.\\n\\n    The scoped form is intentionally exact (``{domain_type}:{domain_id}`` ==\\n    request domain) so a regression that changes the domain the route resolves\\n    flips the decision and trips the test. A scoped assignment missing its\\n    ``domain_id`` is malformed and never widened to global coverage.\\n    \\\"\\\"\\\"\\n    if assignment.domain_type == \\\"global\\\":\\n        return True\\n    if assignment.domain_id is None:\\n        return False\\n    return f\\\"{assignment.domain_type}:{assignment.domain_id}\\\" == request_domain\\n\\n\\nasync def _share_targets_user(session: AsyncSession, share: AuthzShare, user_id: UUID) -> bool:\\n    if share.scope == \\\"public\\\":\\n        return True\\n    if share.scope == \\\"user\\\":\\n        return str(share.target_id) == str(user_id)\\n    if share.scope == \\\"team\\\" and share.target_id is not None:\\n        team = await session.get(AuthzTeam, share.target_id)\\n        if team is None or not team.is_active:\\n            return False\\n        membership = (\\n            await session.exec(\\n                select(AuthzTeamMember).where(\\n                    AuthzTeamMember.team_id == share.target_id,\\n                    AuthzTeamMember.user_id == user_id,\\n                )\\n            )\\n        ).first()\\n        return membership is not None\\n    return False\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Seeding helpers \u2014 write policy rows the enforcer reads.\\n# --------------------------------------------------------------------------- #\\n\\n\\nasync def seed_system_roles(session: AsyncSession) -> dict[str, UUID]:\\n    \\\"\\\"\\\"Get-or-create viewer/developer/admin roles; return ``{name: role_id}``.\\n\\n    Preexisting rows (migration seed or another fixture) are overwritten so the\\n    policy matrix asserted by these tests is exactly ``SYSTEM_ROLE_PERMISSIONS``.\\n    \\\"\\\"\\\"\\n    ids: dict[str, UUID] = {}\\n    for name, permissions in SYSTEM_ROLE_PERMISSIONS.items():\\n        existing = (await session.exec(select(AuthzRole).where(AuthzRole.name == name))).first()\\n        if existing is None:\\n            existing = AuthzRole(\\n                name=name, description=f\\\"{name} (test seed)\\\", is_system=True, permissions=list(permissions)\\n            )\\n            session.add(existing)\\n            await session.flush()\\n        else:\\n            existing.permissions = list(permissions)\\n            existing.is_system = True\\n        ids[name] = existing.id\\n    await session.commit()\\n    return ids\\n\\n\\nasync def assign_role(\\n    session: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    role_id: UUID,\\n    domain_type: str = \\\"global\\\",\\n    domain_id: UUID | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Bind ``user_id`` to ``role_id`` within an optional domain.\\n\\n    Non-global assignments must name their domain \u2014 a scoped grant without a\\n    ``domain_id`` would silently behave like (or be rejected as) something else\\n    and hide domain-resolution regressions.\\n    \\\"\\\"\\\"\\n    if domain_type != \\\"global\\\" and domain_id is None:\\n        msg = f\\\"domain_id is required for non-global assignments (domain_type={domain_type!r})\\\"\\n        raise ValueError(msg)\\n    session.add(AuthzRoleAssignment(user_id=user_id, role_id=role_id, domain_type=domain_type, domain_id=domain_id))\\n    await session.commit()\\n\\n\\nasync def create_user_share(\\n    session: AsyncSession,\\n    *,\\n    resource_type: str,\\n    resource_id: UUID,\\n    target_user_id: UUID,\\n    permission_level: str,\\n    created_by: UUID,\\n) -> AuthzShare:\\n    \\\"\\\"\\\"Create a ``scope='user'`` AuthzShare granting ``target_user_id`` access.\\\"\\\"\\\"\\n    share = AuthzShare(\\n        resource_type=resource_type,\\n        resource_id=resource_id,\\n        scope=\\\"user\\\",\\n        target_id=target_user_id,\\n        permission_level=permission_level,\\n        created_by=created_by,\\n    )\\n    session.add(share)\\n    await session.commit()\\n    return share\\n\\n\\n@contextlib.contextmanager\\ndef install_policy_authz(settings_service: SettingsService) -> Iterator[PolicyTestAuthorizationService]:\\n    \\\"\\\"\\\"Install the policy test-double + enable enforcement for the block; restore on exit.\\n\\n    Swaps the cached authorization service on the service manager (string-enum\\n    keys make ``ServiceType.AUTHORIZATION_SERVICE`` interchangeable across the\\n    lfx/langflow enums) so every ``get_authorization_service()`` resolves to the\\n    double, and flips the auth settings the guards read.\\n    \\\"\\\"\\\"\\n    from langflow.services.schema import ServiceType\\n    from lfx.services.manager import get_service_manager\\n\\n    auth_settings = settings_service.auth_settings\\n    saved_enabled = auth_settings.AUTHZ_ENABLED\\n    saved_bypass = auth_settings.AUTHZ_SUPERUSER_BYPASS\\n\\n    service_manager = get_service_manager()\\n    previous_service = service_manager.services.get(ServiceType.AUTHORIZATION_SERVICE)\\n\\n    auth_settings.AUTHZ_ENABLED = True\\n    auth_settings.AUTHZ_SUPERUSER_BYPASS = False\\n    double = PolicyTestAuthorizationService(settings_service)\\n    service_manager.services[ServiceType.AUTHORIZATION_SERVICE] = double\\n    try:\\n        yield double\\n    finally:\\n        if previous_service is not None:\\n            service_manager.services[ServiceType.AUTHORIZATION_SERVICE] = previous_service\\n        else:\\n            service_manager.services.pop(ServiceType.AUTHORIZATION_SERVICE, None)\\n        auth_settings.AUTHZ_ENABLED = saved_enabled\\n        auth_settings.AUTHZ_SUPERUSER_BYPASS = saved_bypass\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/conftest.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"778173072082bba6ac9257a2d220695a29c609aa7812fc90ba2336b154d0f5c4\",\"content\":\"\\\"\\\"\\\"Shared fixtures for the split authorization-helper tests.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\n\\n\\n@pytest.fixture\\ndef fake_user():\\n    \\\"\\\"\\\"Build a non-superuser user object compatible with ensure_permission.\\\"\\\"\\\"\\n    return SimpleNamespace(id=uuid4(), is_superuser=False)\\n\\n\\n@pytest.fixture\\ndef fake_superuser():\\n    \\\"\\\"\\\"Build a superuser user object compatible with ensure_permission.\\\"\\\"\\\"\\n    return SimpleNamespace(id=uuid4(), is_superuser=True)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_access_ceiling_levels.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fd1bef8609b82d3e76ed63338efedbacb4e286851d63309d0304afe8bbe5529c\",\"content\":\"\\\"\\\"\\\"Regression tests for the external access-ceiling action vocabulary.\\n\\nThese guard the deny-only ceiling levels enforced by\\n``langflow.services.authorization.access_ceiling`` (see PR #13293). The\\neditor level is expected to permit ``delete`` (a user editing their own\\nresources should be able to remove them) while ``deploy`` stays admin-only.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom langflow.services.authorization.access_ceiling import (\\n    ExternalAccessContext,\\n    external_access_allows,\\n    filter_actions_by_external_access_ceiling,\\n    set_current_external_access_context,\\n)\\n\\n_ALL_ACTIONS = (\\\"read\\\", \\\"write\\\", \\\"create\\\", \\\"delete\\\", \\\"execute\\\", \\\"ingest\\\", \\\"deploy\\\")\\n\\n\\ndef _ctx(level: str) -> ExternalAccessContext:\\n    return ExternalAccessContext(provider=\\\"openrag\\\", subject=\\\"subject-1\\\", level=level)\\n\\n\\n@pytest.mark.parametrize(\\\"action\\\", [\\\"read\\\"])\\ndef test_viewer_ceiling_allows_read(action: str) -> None:\\n    assert external_access_allows(action, _ctx(\\\"viewer\\\")) is True\\n\\n\\n@pytest.mark.parametrize(\\\"action\\\", [\\\"write\\\", \\\"create\\\", \\\"delete\\\", \\\"execute\\\", \\\"ingest\\\", \\\"deploy\\\"])\\ndef test_viewer_ceiling_denies_non_read(action: str) -> None:\\n    assert external_access_allows(action, _ctx(\\\"viewer\\\")) is False\\n\\n\\n@pytest.mark.parametrize(\\\"action\\\", [\\\"read\\\", \\\"write\\\", \\\"create\\\", \\\"delete\\\", \\\"execute\\\", \\\"ingest\\\"])\\ndef test_editor_ceiling_allows_crud_and_execute(action: str) -> None:\\n    # ``delete`` is included deliberately (regression for PR #13293): an editor\\n    # may remove their own resources.\\n    assert external_access_allows(action, _ctx(\\\"editor\\\")) is True\\n\\n\\ndef test_editor_ceiling_denies_deploy() -> None:\\n    # Deploy is intentionally reserved for admin.\\n    assert external_access_allows(\\\"deploy\\\", _ctx(\\\"editor\\\")) is False\\n\\n\\n@pytest.mark.parametrize(\\\"action\\\", _ALL_ACTIONS)\\ndef test_admin_ceiling_allows_everything(action: str) -> None:\\n    assert external_access_allows(action, _ctx(\\\"admin\\\")) is True\\n\\n\\n@pytest.mark.parametrize(\\\"action\\\", _ALL_ACTIONS)\\ndef test_no_ceiling_allows_everything(action: str) -> None:\\n    \\\"\\\"\\\"When no external ceiling is installed, every action is permitted.\\\"\\\"\\\"\\n    assert external_access_allows(action, None) is True\\n\\n\\ndef test_filter_actions_through_editor_ceiling_keeps_delete_drops_deploy() -> None:\\n    set_current_external_access_context(_ctx(\\\"editor\\\"))\\n    try:\\n        kept = filter_actions_by_external_access_ceiling([\\\"read\\\", \\\"delete\\\", \\\"deploy\\\"])\\n    finally:\\n        set_current_external_access_context(None)\\n    assert kept == [\\\"read\\\", \\\"delete\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_actions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cc626c59408becf84bf69628a274d6ec8812d4240d55ac21671aaed4408f5b38\",\"content\":\"\\\"\\\"\\\"Tests for the FlowAction enum and its coercion in ensure_flow_permission.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.services.authorization.actions import (\\n    DeploymentAction,\\n    FileAction,\\n    FlowAction,\\n    KnowledgeBaseAction,\\n    ShareAction,\\n    VariableAction,\\n)\\n\\n\\ndef test_flow_action_values_match_policy_strings():\\n    \\\"\\\"\\\"Policy action strings match FlowAction enum values.\\\"\\\"\\\"\\n    assert FlowAction.READ.value == \\\"read\\\"\\n    assert FlowAction.WRITE.value == \\\"write\\\"\\n    assert FlowAction.CREATE.value == \\\"create\\\"\\n    assert FlowAction.DELETE.value == \\\"delete\\\"\\n    assert FlowAction.EXECUTE.value == \\\"execute\\\"\\n    assert FlowAction.DEPLOY.value == \\\"deploy\\\"\\n\\n\\ndef test_flow_action_subclasses_str():\\n    \\\"\\\"\\\"Subclassing str lets the enum be passed wherever a string is accepted.\\\"\\\"\\\"\\n    assert isinstance(FlowAction.READ, str)\\n    assert FlowAction.WRITE == \\\"write\\\"\\n\\n\\ndef test_flow_action_is_iterable_and_complete():\\n    \\\"\\\"\\\"The enum exposes exactly the six canonical actions.\\\"\\\"\\\"\\n    values = {member.value for member in FlowAction}\\n    assert values == {\\\"read\\\", \\\"write\\\", \\\"create\\\", \\\"delete\\\", \\\"execute\\\", \\\"deploy\\\"}\\n\\n\\ndef test_deployment_action_values_match_policy_strings():\\n    \\\"\\\"\\\"Policy action strings match DeploymentAction enum values.\\\"\\\"\\\"\\n    assert DeploymentAction.READ.value == \\\"read\\\"\\n    assert DeploymentAction.WRITE.value == \\\"write\\\"\\n    assert DeploymentAction.CREATE.value == \\\"create\\\"\\n    assert DeploymentAction.DELETE.value == \\\"delete\\\"\\n    assert DeploymentAction.EXECUTE.value == \\\"execute\\\"\\n\\n\\ndef test_deployment_action_subclasses_str():\\n    \\\"\\\"\\\"Subclassing str lets the enum be passed wherever a string is accepted.\\\"\\\"\\\"\\n    assert isinstance(DeploymentAction.WRITE, str)\\n    assert DeploymentAction.DELETE == \\\"delete\\\"\\n\\n\\ndef test_deployment_action_is_iterable_and_complete():\\n    \\\"\\\"\\\"The enum exposes exactly the five canonical deployment actions (no DEPLOY).\\\"\\\"\\\"\\n    values = {member.value for member in DeploymentAction}\\n    assert values == {\\\"read\\\", \\\"write\\\", \\\"create\\\", \\\"delete\\\", \\\"execute\\\"}\\n\\n\\ndef test_knowledge_base_action_values():\\n    \\\"\\\"\\\"Knowledge bases support read/write/create/delete plus an INGEST verb.\\\"\\\"\\\"\\n    values = {member.value for member in KnowledgeBaseAction}\\n    assert values == {\\\"read\\\", \\\"write\\\", \\\"create\\\", \\\"delete\\\", \\\"ingest\\\"}\\n\\n\\ndef test_variable_action_values():\\n    values = {member.value for member in VariableAction}\\n    assert values == {\\\"read\\\", \\\"write\\\", \\\"create\\\", \\\"delete\\\"}\\n\\n\\ndef test_file_action_values():\\n    values = {member.value for member in FileAction}\\n    assert values == {\\\"read\\\", \\\"write\\\", \\\"create\\\", \\\"delete\\\"}\\n\\n\\ndef test_share_action_values():\\n    \\\"\\\"\\\"Share actions cover CRUD over ``authz_share`` rows themselves.\\\"\\\"\\\"\\n    values = {member.value for member in ShareAction}\\n    assert values == {\\\"read\\\", \\\"create\\\", \\\"update\\\", \\\"delete\\\"}\\n\\n\\ndef test_new_actions_subclass_str():\\n    \\\"\\\"\\\"All new action enums subclass str so they coerce in audit/log paths.\\\"\\\"\\\"\\n    for member in (\\n        KnowledgeBaseAction.READ,\\n        VariableAction.CREATE,\\n        FileAction.DELETE,\\n        ShareAction.UPDATE,\\n    ):\\n        assert isinstance(member, str)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_audit.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a293753c32300750db8dc157fcb535c4d2883ffdac889a68730b21eb52e49bf5\",\"content\":\"\\\"\\\"\\\"Tests for the batched audit pipeline (``audit_decision`` + writer).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom contextlib import asynccontextmanager\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.services.auth.context import (\\n    AUTH_METHOD_API_KEY,\\n    AUTH_METHOD_JWT,\\n    AuthCredentialContext,\\n    clear_current_auth_context,\\n    set_current_auth_context,\\n)\\nfrom langflow.services.authorization import audit as authz_audit\\nfrom lfx.services.authorization import base as authz_base\\nfrom lfx.services.settings.auth import AuthSettings\\n\\nfrom ._common import (\\n    install_audit_recorder,\\n    install_settings,\\n)\\n\\n\\n@pytest.fixture\\ndef patched_audit_flush(monkeypatch):\\n    \\\"\\\"\\\"Replace ``_flush_audit_batch`` with a recorder so we exercise the writer without touching the DB.\\\"\\\"\\\"\\n    flushed: list[list[object]] = []\\n\\n    async def _record(batch):\\n        flushed.append(list(batch))\\n\\n    monkeypatch.setattr(authz_audit, \\\"_flush_audit_batch\\\", _record)\\n    return flushed\\n\\n\\n@pytest.fixture(autouse=True)\\ndef reset_auth_context():\\n    \\\"\\\"\\\"Prevent request-local credential metadata from leaking between tests.\\\"\\\"\\\"\\n    clear_current_auth_context()\\n    yield\\n    clear_current_auth_context()\\n\\n\\nasync def _reset_audit_pipeline() -> None:\\n    \\\"\\\"\\\"Best-effort teardown so each test starts with a clean audit pipeline.\\\"\\\"\\\"\\n    await authz_audit.drain_pending_audit_writes(timeout=0.5)\\n    authz_audit._audit_queue = None\\n    authz_audit._audit_queue_loop = None\\n    authz_audit._audit_writer_task = None\\n    authz_audit._audit_inflight = ()\\n    authz_audit._audit_accepting = True\\n    authz_audit._audit_capacity_waiters.clear()\\n    authz_audit._audit_dropped_count = 0\\n    authz_audit._audit_last_drop_warn = 0.0\\n    authz_audit._audit_submitted_count = 0\\n    authz_audit._audit_persisted_count = 0\\n    authz_audit._audit_failed_count = 0\\n    authz_audit._audit_last_failure_code = None\\n    authz_audit._pending_audit_tasks.clear()\\n\\n\\ndef test_durable_audit_mode_is_explicitly_disabled_by_default(tmp_path) -> None:\\n    assert AuthSettings(CONFIG_DIR=str(tmp_path)).AUTHZ_AUDIT_DURABLE is False\\n\\n\\n@pytest.mark.anyio\\nasync def test_durable_audit_call_returns_only_after_its_batch_is_persisted(monkeypatch):\\n    await _reset_audit_pipeline()\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n    flush_started = asyncio.Event()\\n    release_flush = asyncio.Event()\\n    flushed: list[object] = []\\n\\n    async def controlled_flush(batch):\\n        flush_started.set()\\n        await release_flush.wait()\\n        flushed.extend(batch)\\n\\n    monkeypatch.setattr(authz_audit, \\\"_flush_audit_batch\\\", controlled_flush)\\n    call = asyncio.create_task(\\n        authz_audit.audit_decision(\\n            user_id=uuid4(),\\n            action=\\\"flow:read\\\",\\n            obj=\\\"flow:*\\\",\\n            result=\\\"allow\\\",\\n        )\\n    )\\n    await asyncio.wait_for(flush_started.wait(), timeout=1.0)\\n    try:\\n        assert not call.done(), \\\"durable audit returned before its database batch completed\\\"\\n    finally:\\n        release_flush.set()\\n        await call\\n\\n    health = authz_audit.get_audit_producer_health()\\n    assert len(flushed) == 1\\n    assert health == {\\n        \\\"enabled\\\": True,\\n        \\\"durable\\\": True,\\n        \\\"active\\\": True,\\n        \\\"healthy\\\": True,\\n        \\\"queue_depth\\\": 0,\\n        \\\"queue_capacity\\\": authz_audit._AUDIT_QUEUE_MAX,\\n        \\\"submitted_count\\\": 1,\\n        \\\"persisted_count\\\": 1,\\n        \\\"failed_count\\\": 0,\\n        \\\"dropped_count\\\": 0,\\n        \\\"last_failure_code\\\": None,\\n    }\\n\\n\\n@pytest.mark.anyio\\nasync def test_durable_audit_backpressures_at_capacity_instead_of_dropping(monkeypatch):\\n    monkeypatch.setattr(authz_audit, \\\"_AUDIT_QUEUE_MAX\\\", 1)\\n    await _reset_audit_pipeline()\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n    flush_started = asyncio.Event()\\n    release_flush = asyncio.Event()\\n    persisted: list[object] = []\\n\\n    async def blocked_first_flush(batch):\\n        flush_started.set()\\n        await release_flush.wait()\\n        persisted.extend(batch)\\n\\n    monkeypatch.setattr(authz_audit, \\\"_flush_audit_batch\\\", blocked_first_flush)\\n\\n    def submit(index: int) -> asyncio.Task[None]:\\n        return asyncio.create_task(\\n            authz_audit.audit_decision(\\n                user_id=uuid4(),\\n                action=f\\\"flow:read:{index}\\\",\\n                obj=\\\"flow:*\\\",\\n                result=\\\"allow\\\",\\n            )\\n        )\\n\\n    first = submit(1)\\n    await asyncio.wait_for(flush_started.wait(), timeout=1.0)\\n    second = submit(2)\\n    await asyncio.sleep(0)\\n    third = submit(3)\\n    await asyncio.sleep(0)\\n    try:\\n        assert not third.done(), \\\"a full durable queue must backpressure the caller\\\"\\n        assert authz_audit.get_audit_producer_health()[\\\"dropped_count\\\"] == 0\\n    finally:\\n        release_flush.set()\\n        await asyncio.gather(first, second, third)\\n\\n    health = authz_audit.get_audit_producer_health()\\n    assert len(persisted) == 3\\n    assert health[\\\"submitted_count\\\"] == 3\\n    assert health[\\\"persisted_count\\\"] == 3\\n    assert health[\\\"dropped_count\\\"] == 0\\n\\n\\n@pytest.mark.anyio\\nasync def test_durable_audit_failure_is_sanitized_and_propagated_to_the_caller(monkeypatch):\\n    await _reset_audit_pipeline()\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n\\n    sensitive_error = \\\"postgres://user:secret@db/audit\\\"  # pragma: allowlist secret\\n\\n    async def failed_flush(_batch):\\n        raise RuntimeError(sensitive_error)\\n\\n    monkeypatch.setattr(authz_audit, \\\"_flush_audit_batch\\\", failed_flush)\\n    with pytest.raises(authz_audit.AuditPersistenceError, match=\\\"Durable authorization audit persistence failed\\\"):\\n        await authz_audit.audit_decision(\\n            user_id=uuid4(),\\n            action=\\\"flow:read\\\",\\n            obj=\\\"flow:*\\\",\\n            result=\\\"allow\\\",\\n        )\\n\\n    health = authz_audit.get_audit_producer_health()\\n    assert health[\\\"healthy\\\"] is False\\n    assert health[\\\"submitted_count\\\"] == 1\\n    assert health[\\\"persisted_count\\\"] == 0\\n    assert health[\\\"failed_count\\\"] == 1\\n    assert health[\\\"last_failure_code\\\"] == \\\"RuntimeError\\\"\\n    assert \\\"secret\\\" not in str(health)\\n\\n\\n@pytest.mark.anyio\\nasync def test_durable_caller_timeout_does_not_cancel_an_accepted_persistence(monkeypatch):\\n    await _reset_audit_pipeline()\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n    flush_started = asyncio.Event()\\n    release_flush = asyncio.Event()\\n\\n    async def delayed_flush(_batch):\\n        flush_started.set()\\n        await release_flush.wait()\\n\\n    monkeypatch.setattr(authz_audit, \\\"_flush_audit_batch\\\", delayed_flush)\\n    call = asyncio.create_task(\\n        asyncio.wait_for(\\n            authz_audit.audit_decision(\\n                user_id=uuid4(),\\n                action=\\\"flow:read\\\",\\n                obj=\\\"flow:*\\\",\\n                result=\\\"allow\\\",\\n            ),\\n            timeout=0.01,\\n        )\\n    )\\n    await asyncio.wait_for(flush_started.wait(), timeout=1.0)\\n    with pytest.raises(asyncio.TimeoutError):\\n        await call\\n\\n    release_flush.set()\\n    assert authz_audit._audit_queue is not None\\n    await asyncio.wait_for(authz_audit._audit_queue.join(), timeout=1.0)\\n    health = authz_audit.get_audit_producer_health()\\n    assert health[\\\"submitted_count\\\"] == 1\\n    assert health[\\\"persisted_count\\\"] == 1\\n    assert health[\\\"failed_count\\\"] == 0\\n    assert health[\\\"dropped_count\\\"] == 0\\n\\n\\n@pytest.mark.anyio\\nasync def test_durable_shutdown_gives_inflight_and_queued_entries_terminal_failures(monkeypatch):\\n    await _reset_audit_pipeline()\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n    flush_started = asyncio.Event()\\n\\n    async def never_finishes(_batch):\\n        flush_started.set()\\n        await asyncio.Event().wait()\\n\\n    monkeypatch.setattr(authz_audit, \\\"_flush_audit_batch\\\", never_finishes)\\n\\n    def submit(index: int) -> asyncio.Task[None]:\\n        return asyncio.create_task(\\n            authz_audit.audit_decision(\\n                user_id=uuid4(),\\n                action=f\\\"flow:read:{index}\\\",\\n                obj=\\\"flow:*\\\",\\n                result=\\\"allow\\\",\\n            )\\n        )\\n\\n    inflight = submit(1)\\n    await asyncio.wait_for(flush_started.wait(), timeout=1.0)\\n    queued = submit(2)\\n    await asyncio.sleep(0)\\n    await authz_audit.drain_pending_audit_writes(timeout=0.2)\\n    results = await asyncio.wait_for(\\n        asyncio.gather(inflight, queued, return_exceptions=True),\\n        timeout=1.0,\\n    )\\n\\n    assert all(isinstance(result, authz_audit.AuditPersistenceError) for result in results)\\n    health = authz_audit.get_audit_producer_health()\\n    assert health[\\\"queue_depth\\\"] == 0\\n    assert health[\\\"submitted_count\\\"] == 2\\n    assert health[\\\"persisted_count\\\"] == 0\\n    assert health[\\\"failed_count\\\"] == 2\\n    assert health[\\\"last_failure_code\\\"] == \\\"writer_stopped\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_durable_shutdown_rejects_a_producer_blocked_on_full_capacity(monkeypatch):\\n    \\\"\\\"\\\"Closing admission must wake a producer that has not reached the queue yet.\\\"\\\"\\\"\\n    monkeypatch.setattr(authz_audit, \\\"_AUDIT_QUEUE_MAX\\\", 1)\\n    await _reset_audit_pipeline()\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n    flush_started = asyncio.Event()\\n\\n    async def never_finishes(_batch):\\n        flush_started.set()\\n        await asyncio.Event().wait()\\n\\n    monkeypatch.setattr(authz_audit, \\\"_flush_audit_batch\\\", never_finishes)\\n\\n    def submit(index: int) -> asyncio.Task[None]:\\n        return asyncio.create_task(\\n            authz_audit.audit_decision(\\n                user_id=uuid4(),\\n                action=f\\\"flow:read:{index}\\\",\\n                obj=\\\"flow:*\\\",\\n                result=\\\"allow\\\",\\n            )\\n        )\\n\\n    inflight = submit(1)\\n    await asyncio.wait_for(flush_started.wait(), timeout=1.0)\\n    queued = submit(2)\\n    await asyncio.sleep(0)\\n    blocked = submit(3)\\n    await asyncio.sleep(0)\\n    assert authz_audit.get_audit_producer_health()[\\\"queue_depth\\\"] == 1\\n    assert not blocked.done()\\n\\n    await authz_audit.drain_pending_audit_writes(timeout=0.2)\\n    results = await asyncio.wait_for(\\n        asyncio.gather(inflight, queued, blocked, return_exceptions=True),\\n        timeout=1.0,\\n    )\\n\\n    assert all(isinstance(result, authz_audit.AuditPersistenceError) for result in results)\\n    assert authz_audit._audit_writer_task is None\\n    assert authz_audit.get_audit_producer_health()[\\\"queue_depth\\\"] == 0\\n\\n\\n@pytest.mark.anyio\\nasync def test_durable_post_drain_rejection_does_not_restart_writer(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"A stopped same-loop durable pipeline stays stopped until a new loop owns it.\\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n\\n    await authz_audit.audit_decision(\\n        user_id=uuid4(),\\n        action=\\\"flow:read\\\",\\n        obj=\\\"flow:*\\\",\\n        result=\\\"allow\\\",\\n    )\\n    await authz_audit.drain_pending_audit_writes(timeout=1.0)\\n    assert len(patched_audit_flush) == 1\\n    assert authz_audit._audit_writer_task is None\\n\\n    with pytest.raises(authz_audit.AuditPersistenceError):\\n        await authz_audit.audit_decision(\\n            user_id=uuid4(),\\n            action=\\\"flow:read\\\",\\n            obj=\\\"flow:*\\\",\\n            result=\\\"allow\\\",\\n        )\\n\\n    assert authz_audit._audit_writer_task is None\\n    assert authz_audit.get_audit_producer_health()[\\\"active\\\"] is False\\n\\n\\n@pytest.mark.anyio\\nasync def test_cancelled_capacity_waiter_is_never_admitted(monkeypatch):\\n    \\\"\\\"\\\"Cancellation before queue admission remains a normal caller cancellation.\\\"\\\"\\\"\\n    monkeypatch.setattr(authz_audit, \\\"_AUDIT_QUEUE_MAX\\\", 1)\\n    await _reset_audit_pipeline()\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n    flush_started = asyncio.Event()\\n    release_flush = asyncio.Event()\\n\\n    async def delayed_flush(_batch):\\n        flush_started.set()\\n        await release_flush.wait()\\n\\n    monkeypatch.setattr(authz_audit, \\\"_flush_audit_batch\\\", delayed_flush)\\n\\n    def submit(index: int) -> asyncio.Task[None]:\\n        return asyncio.create_task(\\n            authz_audit.audit_decision(\\n                user_id=uuid4(),\\n                action=f\\\"flow:read:{index}\\\",\\n                obj=\\\"flow:*\\\",\\n                result=\\\"allow\\\",\\n            )\\n        )\\n\\n    inflight = submit(1)\\n    await asyncio.wait_for(flush_started.wait(), timeout=1.0)\\n    queued = submit(2)\\n    await asyncio.sleep(0)\\n    blocked = submit(3)\\n    await asyncio.sleep(0)\\n    blocked.cancel()\\n    with pytest.raises(asyncio.CancelledError):\\n        await blocked\\n\\n    release_flush.set()\\n    await asyncio.gather(inflight, queued)\\n    await authz_audit.drain_pending_audit_writes(timeout=1.0)\\n    health = authz_audit.get_audit_producer_health()\\n    assert health[\\\"submitted_count\\\"] == 2\\n    assert health[\\\"persisted_count\\\"] == 2\\n    assert health[\\\"queue_depth\\\"] == 0\\n\\n\\n@pytest.mark.anyio\\nasync def test_audit_decision_runs_when_authz_disabled_but_audit_on(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"Audit is independent of enforcement.\\n\\n    Previously ``audit_decision`` short-circuited when ``AUTHZ_ENABLED=False``,\\n    which meant share CRUD writes left no audit trail on default installs. The\\n    new contract gates only on ``AUTHZ_AUDIT_ENABLED`` so operators can\\n    observe traffic before flipping enforcement on.\\n    \\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(monkeypatch, authz_enabled=False, audit_enabled=True)\\n\\n    await authz_audit.audit_decision(user_id=uuid4(), action=\\\"flow:read\\\", obj=\\\"flow:x\\\", result=\\\"allow\\\")\\n    await authz_audit.drain_pending_audit_writes(timeout=1.0)\\n\\n    assert sum(len(b) for b in patched_audit_flush) == 1\\n\\n\\n@pytest.mark.anyio\\nasync def test_audit_decision_noop_when_audit_disabled(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"AUTHZ_AUDIT_ENABLED=False suppresses audit writes.\\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=False)\\n\\n    await authz_audit.audit_decision(user_id=uuid4(), action=\\\"flow:read\\\", obj=\\\"flow:x\\\", result=\\\"allow\\\")\\n    await authz_audit.drain_pending_audit_writes(timeout=0.5)\\n\\n    assert patched_audit_flush == []\\n\\n\\n@pytest.mark.anyio\\nasync def test_audit_decision_enqueues_when_enabled(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"When both flags are on, ``audit_decision`` enqueues an entry the background writer flushes.\\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=True)\\n\\n    user_id = uuid4()\\n    await authz_audit.audit_decision(user_id=user_id, action=\\\"flow:read\\\", obj=\\\"flow:abc\\\", result=\\\"allow\\\")\\n    # Drain forces the writer to flush before we inspect.\\n    await authz_audit.drain_pending_audit_writes(timeout=1.0)\\n\\n    assert len(patched_audit_flush) == 1\\n    batch = patched_audit_flush[0]\\n    assert len(batch) == 1\\n    entry = batch[0]\\n    assert entry.user_id == user_id\\n    assert entry.action == \\\"flow:read\\\"\\n    assert entry.obj == \\\"flow:abc\\\"\\n    assert entry.result == \\\"allow\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_api_key_actor_is_captured_centrally_and_preserves_owner(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"Audit attribution reads request-local credentials without relying on a guard caller.\\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=True)\\n    owner_id = uuid4()\\n    api_key_id = uuid4()\\n    set_current_auth_context(\\n        AuthCredentialContext(\\n            method=AUTH_METHOD_API_KEY,\\n            api_key_id=api_key_id,\\n            api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n        )\\n    )\\n\\n    await authz_audit.audit_decision(\\n        user_id=owner_id,\\n        action=\\\"flow:read\\\",\\n        obj=f\\\"flow:{uuid4()}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"domain\\\": \\\"*\\\", \\\"actor_type\\\": \\\"user\\\", \\\"actor_id\\\": str(uuid4())},\\n    )\\n    await authz_audit.drain_pending_audit_writes(timeout=1.0)\\n\\n    entry = patched_audit_flush[0][0]\\n    assert entry.user_id == owner_id\\n    assert entry.actor_type == \\\"api_key\\\"\\n    assert entry.actor_id == api_key_id\\n    assert entry.details == {\\n        \\\"domain\\\": \\\"*\\\",\\n        \\\"auth_method\\\": \\\"api_key\\\",\\n        \\\"api_key_id\\\": str(api_key_id),\\n        \\\"api_key_source\\\": \\\"db\\\",  # pragma: allowlist secret\\n    }\\n\\n\\n@pytest.mark.anyio\\nasync def test_jwt_and_system_actor_identity_are_derived_per_queued_entry(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"Actor fields are captured at enqueue time so a mixed batch cannot inherit later context.\\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=True)\\n    user_id = uuid4()\\n\\n    set_current_auth_context(AuthCredentialContext(method=AUTH_METHOD_JWT))\\n    await authz_audit.audit_decision(\\n        user_id=user_id,\\n        action=\\\"flow:read\\\",\\n        obj=\\\"flow:*\\\",\\n        result=\\\"allow\\\",\\n    )\\n    lingering_api_key_id = uuid4()\\n    set_current_auth_context(\\n        AuthCredentialContext(\\n            method=AUTH_METHOD_API_KEY,\\n            api_key_id=lingering_api_key_id,\\n            api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n        )\\n    )\\n    await authz_audit.audit_decision(\\n        user_id=None,\\n        action=\\\"system:sync\\\",\\n        obj=\\\"system:*\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"job\\\": \\\"policy-sync\\\"},\\n    )\\n    await authz_audit.drain_pending_audit_writes(timeout=1.0)\\n\\n    entries = [entry for batch in patched_audit_flush for entry in batch]\\n    assert [(entry.actor_type, entry.actor_id) for entry in entries] == [\\n        (\\\"user\\\", user_id),\\n        (\\\"unknown\\\", None),\\n    ]\\n    assert entries[0].details == {\\\"auth_method\\\": \\\"jwt\\\"}\\n    assert entries[1].details == {\\\"job\\\": \\\"policy-sync\\\"}\\n\\n\\n@pytest.mark.anyio\\nasync def test_public_principal_uses_stable_non_user_audit_actor(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"Anonymous decisions populate actor columns without inventing a user foreign key.\\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(monkeypatch, authz_enabled=False, audit_enabled=True)\\n    principal_type = getattr(authz_base, \\\"AuthorizationPrincipal\\\", None)\\n    assert principal_type is not None\\n    principal = principal_type.public_anonymous()\\n\\n    await authz_audit.audit_decision(\\n        user_id=None,\\n        principal=principal,\\n        action=\\\"flow:execute\\\",\\n        obj=f\\\"flow:{uuid4()}\\\",\\n        result=\\\"allow\\\",\\n    )\\n    await authz_audit.drain_pending_audit_writes(timeout=1.0)\\n\\n    entry = patched_audit_flush[0][0]\\n    assert entry.user_id is None\\n    assert entry.actor_type == \\\"anonymous_public\\\"\\n    assert entry.actor_id == principal.actor_id\\n\\n\\n@pytest.mark.anyio\\nasync def test_invalid_api_key_actor_uuid_is_safely_dropped(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"Malformed request metadata must not crash or poison the background DB batch.\\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=True)\\n    set_current_auth_context(\\n        AuthCredentialContext(\\n            method=AUTH_METHOD_API_KEY,\\n            api_key_id=\\\"not-a-uuid\\\",  # type: ignore[arg-type]\\n            api_key_source=\\\"plugin\\\",  # pragma: allowlist secret\\n        )\\n    )\\n\\n    await authz_audit.audit_decision(user_id=uuid4(), action=\\\"flow:read\\\", obj=\\\"flow:*\\\", result=\\\"deny\\\")\\n    await authz_audit.drain_pending_audit_writes(timeout=1.0)\\n\\n    entry = patched_audit_flush[0][0]\\n    assert entry.actor_type == \\\"api_key\\\"\\n    assert entry.actor_id is None\\n    assert entry.details[\\\"api_key_id\\\"] == \\\"not-a-uuid\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_flush_batch_maps_actor_fields_to_model(monkeypatch):\\n    \\\"\\\"\\\"The batched DB projection must retain actor fields captured at enqueue time.\\\"\\\"\\\"\\n    from langflow.services import deps\\n\\n    rows = []\\n\\n    class _Session:\\n        def add(self, row):\\n            rows.append(row)\\n\\n    @asynccontextmanager\\n    async def _scope():\\n        yield _Session()\\n\\n    monkeypatch.setattr(deps, \\\"session_scope\\\", _scope)\\n    actor_id = uuid4()\\n    user_id = uuid4()\\n    entry = authz_audit._AuditEntry(\\n        user_id=user_id,\\n        actor_type=\\\"api_key\\\",\\n        actor_id=actor_id,\\n        action=\\\"flow:read\\\",\\n        obj=f\\\"flow:{uuid4()}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"api_key_source\\\": \\\"db\\\"},  # pragma: allowlist secret\\n    )\\n\\n    await authz_audit._flush_audit_batch([entry])\\n\\n    assert len(rows) == 1\\n    assert rows[0].user_id == user_id\\n    assert rows[0].actor_type == \\\"api_key\\\"\\n    assert rows[0].actor_id == actor_id\\n    assert rows[0].details == {\\\"api_key_source\\\": \\\"db\\\"}  # pragma: allowlist secret\\n    assert rows[0].id == entry.event_id\\n    assert rows[0].timestamp == entry.occurred_at\\n\\n\\n@pytest.mark.anyio\\nasync def test_flush_batch_stages_plugin_events_in_same_transaction(monkeypatch):\\n    \\\"\\\"\\\"Plugins receive stable event identity on the audit row's open session.\\\"\\\"\\\"\\n    from langflow.services import deps\\n\\n    rows = []\\n    staged = []\\n\\n    class _Session:\\n        def add(self, row):\\n            rows.append(row)\\n\\n    class _AuthorizationService:\\n        def stage_audit_events(self, *, session, events):\\n            staged.append((session, tuple(events)))\\n\\n    session = _Session()\\n\\n    @asynccontextmanager\\n    async def _scope():\\n        yield session\\n\\n    monkeypatch.setattr(deps, \\\"session_scope\\\", _scope)\\n    monkeypatch.setattr(deps, \\\"get_authorization_service\\\", lambda: _AuthorizationService())\\n    entry = authz_audit._AuditEntry(\\n        user_id=uuid4(),\\n        actor_type=\\\"user\\\",\\n        actor_id=uuid4(),\\n        action=\\\"flow:read\\\",\\n        obj=f\\\"flow:{uuid4()}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"secret\\\": \\\"must-not-cross-plugin-seam\\\"},  # pragma: allowlist secret\\n    )\\n\\n    await authz_audit._flush_audit_batch([entry])\\n\\n    assert len(rows) == 1\\n    assert len(staged) == 1\\n    staged_session, events = staged[0]\\n    assert staged_session is session\\n    assert len(events) == 1\\n    assert events[0].event_id == entry.event_id\\n    assert events[0].occurred_at == entry.occurred_at\\n    assert not hasattr(events[0], \\\"details\\\")\\n\\n\\ndef test_stage_audit_decision_uses_caller_transaction(monkeypatch):\\n    \\\"\\\"\\\"Mutation audit rows and plugin events are staged without a separate commit.\\\"\\\"\\\"\\n    from langflow.services import deps\\n\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=True, audit_durable=True)\\n    rows = []\\n    staged = []\\n\\n    class _Session:\\n        def add(self, row):\\n            rows.append(row)\\n\\n    class _AuthorizationService:\\n        def stage_audit_events(self, *, session, events):\\n            staged.append((session, tuple(events)))\\n\\n    session = _Session()\\n    user_id = uuid4()\\n    resource_id = uuid4()\\n    monkeypatch.setattr(deps, \\\"get_authorization_service\\\", lambda: _AuthorizationService())\\n\\n    staged_in_transaction = authz_audit.stage_audit_decision(\\n        session=session,\\n        user_id=user_id,\\n        action=\\\"user:update\\\",\\n        obj=f\\\"user:{resource_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"event\\\": authz_audit.AUDIT_EVENT_MUTATION},\\n    )\\n\\n    assert len(rows) == 1\\n    assert rows[0].user_id == user_id\\n    assert rows[0].resource_type == \\\"user\\\"\\n    assert rows[0].resource_id == resource_id\\n    assert rows[0].details == {\\\"event\\\": authz_audit.AUDIT_EVENT_MUTATION}\\n    assert len(staged) == 1\\n    assert staged[0][0] is session\\n    assert staged[0][1][0].event_id == rows[0].id\\n    assert staged_in_transaction is True\\n\\n\\ndef test_stage_audit_decision_preserves_best_effort_pipeline(monkeypatch):\\n    \\\"\\\"\\\"Best-effort mutation audits remain asynchronous after commit.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=True, audit_durable=False)\\n\\n    class _Session:\\n        def add(self, _row):\\n            pytest.fail(\\\"best-effort audit must not join the mutation transaction\\\")\\n\\n    staged_in_transaction = authz_audit.stage_audit_decision(\\n        session=_Session(),\\n        user_id=uuid4(),\\n        action=\\\"user:update\\\",\\n        obj=f\\\"user:{uuid4()}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"event\\\": authz_audit.AUDIT_EVENT_MUTATION},\\n    )\\n\\n    assert staged_in_transaction is False\\n\\n\\n@pytest.mark.anyio\\nasync def test_audit_decision_batches_multiple_entries(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"Multiple concurrent ``audit_decision`` calls coalesce into a single DB batch.\\n\\n    This is the contract we want \u2014 the writer should pull every entry already\\n    in the queue when it wakes up, so we make N decisions before yielding and\\n    expect ONE batch of N rows, not N separate ``session_scope`` opens.\\n    \\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=True)\\n\\n    for _ in range(5):\\n        await authz_audit.audit_decision(user_id=uuid4(), action=\\\"flow:read\\\", obj=\\\"flow:x\\\", result=\\\"allow\\\")\\n\\n    await authz_audit.drain_pending_audit_writes(timeout=1.0)\\n\\n    total_rows = sum(len(batch) for batch in patched_audit_flush)\\n    assert total_rows == 5\\n    # All entries are emitted before the first await, so they should land in a single batch.\\n    assert len(patched_audit_flush) == 1, (\\n        f\\\"Expected 1 batch of 5 rows, got {len(patched_audit_flush)} batches \\\"\\n        f\\\"with sizes {[len(b) for b in patched_audit_flush]}\\\"\\n    )\\n\\n\\n@pytest.mark.anyio\\nasync def test_idle_drain_keeps_durable_admission_terminal(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"A same-loop durable submit cannot reopen a never-started drained pipeline.\\\"\\\"\\\"\\n    await _reset_audit_pipeline()\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n\\n    await authz_audit.drain_pending_audit_writes(timeout=0.1)\\n\\n    try:\\n        with pytest.raises(authz_audit.AuditPersistenceError):\\n            await authz_audit.audit_decision(\\n                user_id=uuid4(),\\n                action=\\\"flow:read\\\",\\n                obj=\\\"flow:*\\\",\\n                result=\\\"allow\\\",\\n            )\\n\\n        assert authz_audit._audit_accepting is False\\n        assert authz_audit._audit_queue is None\\n        assert authz_audit._audit_writer_task is None\\n        assert patched_audit_flush == []\\n    finally:\\n        await authz_audit.drain_pending_audit_writes(timeout=0.1)\\n\\n\\ndef test_new_loop_replaces_idle_drained_pipeline(monkeypatch, patched_audit_flush):\\n    \\\"\\\"\\\"A closed owner loop does not make durable shutdown process-global.\\\"\\\"\\\"\\n    install_settings(\\n        monkeypatch,\\n        authz_enabled=True,\\n        audit_enabled=True,\\n        audit_durable=True,\\n    )\\n\\n    async def stop_idle_pipeline() -> None:\\n        await _reset_audit_pipeline()\\n        await authz_audit.drain_pending_audit_writes(timeout=0.1)\\n\\n    async def submit_on_replacement_loop() -> None:\\n        await authz_audit.audit_decision(\\n            user_id=uuid4(),\\n            action=\\\"flow:read\\\",\\n            obj=\\\"flow:*\\\",\\n            result=\\\"allow\\\",\\n        )\\n        await authz_audit.drain_pending_audit_writes(timeout=0.1)\\n\\n    asyncio.run(stop_idle_pipeline())\\n    asyncio.run(submit_on_replacement_loop())\\n\\n    assert sum(len(batch) for batch in patched_audit_flush) == 1\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_permission_fails_closed_on_plugin_exception(monkeypatch, fake_user):\\n    \\\"\\\"\\\"If the authz plugin raises, ``ensure_permission`` must deny (403), not bubble 500.\\\"\\\"\\\"\\n    from langflow.services.authorization import guards as authz_guards\\n\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=False)\\n\\n    class _BrokenPlugin:\\n        async def enforce(self, **_kwargs):\\n            msg = \\\"policy store down\\\"\\n            raise RuntimeError(msg)\\n\\n        async def batch_enforce(self, **_kwargs):\\n            return []\\n\\n    monkeypatch.setattr(authz_guards, \\\"get_authorization_service\\\", lambda: _BrokenPlugin())\\n    captured = install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException) as excinfo:\\n        await authz_guards.ensure_permission(fake_user, domain=\\\"*\\\", obj=\\\"flow:abc\\\", act=\\\"read\\\")\\n\\n    assert excinfo.value.status_code == 403, \\\"Plugin exceptions must fail closed (deny), not 500\\\"\\n    # The deny path must still emit an audit row so the operator can see the failure.\\n    assert captured, \\\"Plugin exception must still produce an audit row\\\"\\n    assert captured[0][\\\"result\\\"] == \\\"deny\\\"\\n    assert \\\"error\\\" in captured[0][\\\"details\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_audit_cleanup_worker.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b2a675abd30295d576b5b197c585ad37d1bb4db8d1cb0c1b979efd4ee8d6eb70\",\"content\":\"\\\"\\\"\\\"Tests for the scheduled ``authz_audit_log`` retention worker.\\n\\nThese cover the behaviour that the startup-only sweep lacked (gap C): the\\ncleanup must run repeatedly on a recurring schedule, must be a no-op when\\nretention is disabled (``AUTHZ_AUDIT_RETENTION_DAYS=0``) or auditing is off\\n(``AUTHZ_AUDIT_ENABLED=False``), and must keep best-effort semantics.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nfrom datetime import datetime, timedelta, timezone\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.auth import AuthzAuditLog\\nfrom langflow.services.task import audit_cleanup\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\nfrom sqlalchemy.pool import StaticPool\\nfrom sqlmodel import SQLModel, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\ndef _svc(*, enabled: bool, retention: int, interval: int = 86400) -> SimpleNamespace:\\n    \\\"\\\"\\\"A stand-in settings service exposing only the audit knobs the worker reads.\\\"\\\"\\\"\\n    return SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_AUDIT_ENABLED=enabled,\\n            AUTHZ_AUDIT_RETENTION_DAYS=retention,\\n            AUTHZ_AUDIT_CLEANUP_INTERVAL=interval,\\n        )\\n    )\\n\\n\\ndef _audit_row(*, days_old: int, resource_id=None) -> AuthzAuditLog:\\n    timestamp = datetime.now(timezone.utc) - timedelta(days=days_old)\\n    return AuthzAuditLog(\\n        user_id=uuid4(),\\n        action=\\\"flow:read\\\",\\n        resource_type=\\\"flow\\\",\\n        resource_id=resource_id or uuid4(),\\n        result=\\\"allow\\\",\\n        details={\\\"domain\\\": \\\"*\\\"},\\n        timestamp=timestamp,\\n    )\\n\\n\\n@contextlib.asynccontextmanager\\nasync def _fake_session_scope():\\n    \\\"\\\"\\\"No-op session scope for tests that patch out the cleanup helper.\\\"\\\"\\\"\\n    yield SimpleNamespace()\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Scheduling behaviour (the core of gap C)\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.asyncio\\nasync def test_worker_runs_cleanup_repeatedly_on_schedule(monkeypatch):\\n    \\\"\\\"\\\"The worker invokes the retention helper repeatedly, not just once.\\\"\\\"\\\"\\n    cleanup = AsyncMock(return_value=3)\\n    monkeypatch.setattr(audit_cleanup, \\\"clean_authz_audit_log\\\", cleanup)\\n    monkeypatch.setattr(audit_cleanup, \\\"session_scope\\\", _fake_session_scope)\\n    monkeypatch.setattr(audit_cleanup, \\\"get_settings_service\\\", lambda: _svc(enabled=True, retention=90))\\n\\n    worker = audit_cleanup.AuditLogCleanupWorker(interval=0.03)\\n    await worker.start()\\n    assert worker._task is not None\\n    try:\\n        # Several intervals worth of wall-clock; sleep-first means the first\\n        # sweep lands one interval in, with more following.\\n        await asyncio.sleep(0.25)\\n    finally:\\n        await worker.stop()\\n\\n    assert worker._task is None\\n    assert cleanup.call_count >= 2, f\\\"expected recurring sweeps, got {cleanup.call_count}\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_worker_is_noop_when_retention_disabled(monkeypatch):\\n    \\\"\\\"\\\"AUTHZ_AUDIT_RETENTION_DAYS=0 -> no task is scheduled and nothing is pruned.\\\"\\\"\\\"\\n    cleanup = AsyncMock()\\n    monkeypatch.setattr(audit_cleanup, \\\"clean_authz_audit_log\\\", cleanup)\\n    monkeypatch.setattr(audit_cleanup, \\\"session_scope\\\", _fake_session_scope)\\n    monkeypatch.setattr(audit_cleanup, \\\"get_settings_service\\\", lambda: _svc(enabled=True, retention=0))\\n\\n    worker = audit_cleanup.AuditLogCleanupWorker(interval=0.02)\\n    await worker.start()\\n    assert worker._task is None  # never scheduled\\n    await asyncio.sleep(0.08)\\n    cleanup.assert_not_called()\\n    await worker.stop()  # safe no-op\\n\\n\\n@pytest.mark.asyncio\\nasync def test_worker_is_noop_when_audit_disabled(monkeypatch):\\n    \\\"\\\"\\\"AUTHZ_AUDIT_ENABLED=False -> no task is scheduled and nothing is pruned.\\\"\\\"\\\"\\n    cleanup = AsyncMock()\\n    monkeypatch.setattr(audit_cleanup, \\\"clean_authz_audit_log\\\", cleanup)\\n    monkeypatch.setattr(audit_cleanup, \\\"session_scope\\\", _fake_session_scope)\\n    monkeypatch.setattr(audit_cleanup, \\\"get_settings_service\\\", lambda: _svc(enabled=False, retention=90))\\n\\n    worker = audit_cleanup.AuditLogCleanupWorker(interval=0.02)\\n    await worker.start()\\n    assert worker._task is None\\n    await asyncio.sleep(0.08)\\n    cleanup.assert_not_called()\\n    await worker.stop()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_worker_start_stop_and_idempotency(monkeypatch):\\n    \\\"\\\"\\\"start()/stop() manage the task and tolerate double calls.\\\"\\\"\\\"\\n    cleanup = AsyncMock()\\n    monkeypatch.setattr(audit_cleanup, \\\"clean_authz_audit_log\\\", cleanup)\\n    monkeypatch.setattr(audit_cleanup, \\\"session_scope\\\", _fake_session_scope)\\n    # interval read from settings (5s) so no sweep fires during the short test.\\n    monkeypatch.setattr(audit_cleanup, \\\"get_settings_service\\\", lambda: _svc(enabled=True, retention=90, interval=5))\\n\\n    worker = audit_cleanup.AuditLogCleanupWorker()\\n    await worker.start()\\n    assert worker._task is not None\\n    assert not worker._stop_event.is_set()\\n    assert worker._interval == 5  # resolved from AUTHZ_AUDIT_CLEANUP_INTERVAL\\n\\n    first_task = worker._task\\n    await worker.start()  # already running -> no-op, same task\\n    assert worker._task is first_task\\n\\n    await worker.stop()\\n    assert worker._task is None\\n    assert worker._stop_event.is_set()\\n    await worker.stop()  # idempotent no-op\\n\\n\\n@pytest.mark.asyncio\\nasync def test_worker_survives_cleanup_failure(monkeypatch):\\n    \\\"\\\"\\\"A failing sweep is swallowed and the loop keeps going.\\\"\\\"\\\"\\n    cleanup = AsyncMock(side_effect=RuntimeError(\\\"boom\\\"))\\n    monkeypatch.setattr(audit_cleanup, \\\"clean_authz_audit_log\\\", cleanup)\\n    monkeypatch.setattr(audit_cleanup, \\\"session_scope\\\", _fake_session_scope)\\n    monkeypatch.setattr(audit_cleanup, \\\"get_settings_service\\\", lambda: _svc(enabled=True, retention=90))\\n\\n    worker = audit_cleanup.AuditLogCleanupWorker(interval=0.03)\\n    await worker.start()\\n    try:\\n        await asyncio.sleep(0.2)\\n    finally:\\n        await worker.stop()\\n\\n    # Despite every sweep raising, the worker kept scheduling more.\\n    assert cleanup.call_count >= 2\\n\\n\\ndef test_interval_resolution_prefers_override():\\n    \\\"\\\"\\\"The constructor override wins; otherwise the value comes from the setting.\\n\\n    AUTHZ_AUDIT_CLEANUP_INTERVAL is a pydantic field (default 86400, ge=300), so\\n    the worker reads it directly without a missing/garbage fallback.\\n    \\\"\\\"\\\"\\n    overridden = audit_cleanup.AuditLogCleanupWorker(interval=1.5)\\n    assert overridden._resolve_interval(SimpleNamespace(AUTHZ_AUDIT_CLEANUP_INTERVAL=99)) == 1.5\\n\\n    from_settings = audit_cleanup.AuditLogCleanupWorker()\\n    assert from_settings._resolve_interval(SimpleNamespace(AUTHZ_AUDIT_CLEANUP_INTERVAL=99)) == 99.0\\n\\n\\n# --------------------------------------------------------------------------- #\\n# End-to-end: real retention helper deletes real rows on the schedule\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.fixture(name=\\\"audit_engine\\\")\\nasync def audit_engine():\\n    \\\"\\\"\\\"A shared in-memory SQLite engine (StaticPool so every session sees the same DB).\\\"\\\"\\\"\\n    engine = create_async_engine(\\n        \\\"sqlite+aiosqlite:///:memory:\\\",\\n        connect_args={\\\"check_same_thread\\\": False},\\n        poolclass=StaticPool,\\n    )\\n    async with engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n    yield engine\\n    await engine.dispose()\\n\\n\\ndef _scope_factory(engine):\\n    @contextlib.asynccontextmanager\\n    async def _scope():\\n        # Mirror the real session_scope: commit on clean exit, roll back on error.\\n        async with AsyncSession(engine, expire_on_commit=False) as session:\\n            try:\\n                yield session\\n                await session.commit()\\n            except Exception:\\n                await session.rollback()\\n                raise\\n\\n    return _scope\\n\\n\\nasync def _count(engine, resource_id) -> int:\\n    async with AsyncSession(engine, expire_on_commit=False) as session:\\n        rows = (await session.exec(select(AuthzAuditLog).where(AuthzAuditLog.resource_id == resource_id))).all()\\n    return len(rows)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_worker_prunes_old_rows_on_schedule(audit_engine, monkeypatch):\\n    \\\"\\\"\\\"A row inserted after startup is pruned by the scheduled worker; fresh rows survive.\\\"\\\"\\\"\\n    old_id = uuid4()\\n    fresh_id = uuid4()\\n    async with AsyncSession(audit_engine, expire_on_commit=False) as session:\\n        session.add(_audit_row(days_old=120, resource_id=old_id))  # outside 90-day window\\n        session.add(_audit_row(days_old=2, resource_id=fresh_id))  # inside window\\n        await session.commit()\\n\\n    monkeypatch.setattr(audit_cleanup, \\\"session_scope\\\", _scope_factory(audit_engine))\\n    monkeypatch.setattr(audit_cleanup, \\\"get_settings_service\\\", lambda: _svc(enabled=True, retention=90))\\n\\n    worker = audit_cleanup.AuditLogCleanupWorker(interval=0.05)\\n    await worker.start()\\n    old_remaining = 1\\n    try:\\n        loop = asyncio.get_event_loop()\\n        deadline = loop.time() + 5.0\\n        while loop.time() < deadline:\\n            await asyncio.sleep(0.1)\\n            old_remaining = await _count(audit_engine, old_id)\\n            if old_remaining == 0:\\n                break\\n    finally:\\n        await worker.stop()\\n\\n    # The stale row was deleted by the recurring worker (the seed happened after\\n    # any startup sweep would have run), and the fresh row was left intact.\\n    assert old_remaining == 0\\n    assert await _count(audit_engine, fresh_id) == 1\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_audit_retention.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"29c8b4c0b51e2b76ec602a924a9f7cbf8ca9561a6dccf74d565adc79a65ee354\",\"content\":\"\\\"\\\"\\\"Tests for the authz_audit_log retention helper and pass-through startup warning.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timedelta, timezone\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.authorization.service import LangflowAuthorizationService\\nfrom langflow.services.database.models.auth import AuthzAuditLog\\nfrom langflow.services.utils import clean_authz_audit_log\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\nfrom sqlmodel import SQLModel, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\n@pytest.fixture(name=\\\"authz_engine\\\")\\ndef authz_engine():\\n    engine = create_async_engine(\\\"sqlite+aiosqlite:///:memory:\\\", echo=False)\\n    yield engine\\n    engine.sync_engine.dispose()\\n\\n\\n@pytest.fixture(name=\\\"authz_session\\\")\\nasync def authz_session(authz_engine):\\n    async with authz_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n    async with AsyncSession(authz_engine, expire_on_commit=False) as session:\\n        yield session\\n    async with authz_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.drop_all)\\n    await authz_engine.dispose()\\n\\n\\ndef _audit_row(*, days_old: int) -> AuthzAuditLog:\\n    timestamp = datetime.now(timezone.utc) - timedelta(days=days_old)\\n    return AuthzAuditLog(\\n        user_id=uuid4(),\\n        action=\\\"flow:read\\\",\\n        resource_type=\\\"flow\\\",\\n        resource_id=uuid4(),\\n        result=\\\"allow\\\",\\n        details={\\\"domain\\\": \\\"*\\\"},\\n        timestamp=timestamp,\\n    )\\n\\n\\ndef _settings(*, retention_days: int) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_AUDIT_RETENTION_DAYS=retention_days,\\n        ),\\n    )\\n\\n\\n@pytest.mark.anyio\\nasync def test_clean_authz_audit_log_prunes_rows_past_retention(authz_session):\\n    \\\"\\\"\\\"Rows older than the retention window are deleted; fresh rows survive.\\\"\\\"\\\"\\n    authz_session.add(_audit_row(days_old=120))  # outside 90-day window\\n    authz_session.add(_audit_row(days_old=95))  # outside 90-day window\\n    authz_session.add(_audit_row(days_old=5))  # inside window\\n    await authz_session.commit()\\n\\n    await clean_authz_audit_log(_settings(retention_days=90), authz_session)\\n    await authz_session.commit()\\n\\n    surviving = (await authz_session.exec(select(AuthzAuditLog))).all()\\n    # Only the 5-day-old row should remain.\\n    assert len(surviving) == 1\\n\\n\\n@pytest.mark.anyio\\nasync def test_clean_authz_audit_log_zero_disables_retention(authz_session):\\n    \\\"\\\"\\\"A retention of 0 days is a no-op so external archival pipelines can manage the table.\\\"\\\"\\\"\\n    for days_old in (1, 30, 200, 365):\\n        authz_session.add(_audit_row(days_old=days_old))\\n    await authz_session.commit()\\n\\n    await clean_authz_audit_log(_settings(retention_days=0), authz_session)\\n    await authz_session.commit()\\n\\n    surviving = (await authz_session.exec(select(AuthzAuditLog))).all()\\n    assert len(surviving) == 4\\n\\n\\n@pytest.mark.anyio\\nasync def test_clean_authz_audit_log_empty_table(authz_session):\\n    \\\"\\\"\\\"Pruning an empty table is a no-op and must not raise.\\\"\\\"\\\"\\n    deleted = await clean_authz_audit_log(_settings(retention_days=30), authz_session)\\n    assert deleted in (0, -1)  # -1 acceptable when driver doesn't report rowcount\\n\\n\\nclass _RecordingLogger:\\n    \\\"\\\"\\\"Stand-in for loguru's logger that records each call by level.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        self.calls: list[tuple[str, str]] = []\\n\\n    def warning(self, message: str, *args, **kwargs) -> None:  # noqa: ARG002\\n        self.calls.append((\\\"warning\\\", message))\\n\\n    def debug(self, message: str, *args, **kwargs) -> None:  # noqa: ARG002\\n        self.calls.append((\\\"debug\\\", message))\\n\\n    def info(self, message: str, *args, **kwargs) -> None:  # noqa: ARG002\\n        self.calls.append((\\\"info\\\", message))\\n\\n\\n@pytest.mark.anyio\\nasync def test_passthrough_warning_emitted_when_authz_enabled(monkeypatch):\\n    \\\"\\\"\\\"LangflowAuthorizationService warns when AUTHZ_ENABLED=True but plugin is missing.\\\"\\\"\\\"\\n    from langflow.services.authorization import service as authz_service_module\\n\\n    recorder = _RecordingLogger()\\n    monkeypatch.setattr(authz_service_module, \\\"logger\\\", recorder)\\n\\n    settings = SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_ENABLED=True,\\n            AUTHZ_SUPERUSER_BYPASS=True,\\n        )\\n    )\\n    LangflowAuthorizationService(settings)\\n\\n    warning_messages = [msg for level, msg in recorder.calls if level == \\\"warning\\\"]\\n    assert any(\\\"OSS pass-through\\\" in msg for msg in warning_messages), (\\n        f\\\"Expected a WARNING about the OSS pass-through service; got {warning_messages}\\\"\\n    )\\n\\n\\n@pytest.mark.anyio\\nasync def test_passthrough_warning_silent_when_authz_disabled(monkeypatch):\\n    \\\"\\\"\\\"No warning is emitted when AUTHZ_ENABLED=False.\\\"\\\"\\\"\\n    from langflow.services.authorization import service as authz_service_module\\n\\n    recorder = _RecordingLogger()\\n    monkeypatch.setattr(authz_service_module, \\\"logger\\\", recorder)\\n\\n    settings = SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_ENABLED=False,\\n            AUTHZ_SUPERUSER_BYPASS=True,\\n        )\\n    )\\n    LangflowAuthorizationService(settings)\\n\\n    warning_messages = [msg for level, msg in recorder.calls if level == \\\"warning\\\"]\\n    assert not any(\\\"OSS pass-through\\\" in msg for msg in warning_messages), (\\n        f\\\"No pass-through warning expected when AUTHZ_ENABLED=False; got {warning_messages}\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_authorization_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c740512780296d19b9aa53f0ec117a371213fd3728519502816318455a202233\",\"content\":\"from __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.authorization.service import LangflowAuthorizationService\\n\\n\\n@pytest.fixture\\ndef authz_service():\\n    settings = SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_ENABLED=False,\\n            AUTHZ_SUPERUSER_BYPASS=True,\\n        )\\n    )\\n    return LangflowAuthorizationService(settings)\\n\\n\\n@pytest.mark.anyio\\nasync def test_enforce_allows_all_when_disabled(authz_service):\\n    user_id = uuid4()\\n    assert await authz_service.enforce(\\n        user_id=user_id,\\n        domain=\\\"*\\\",\\n        obj=\\\"flow:*\\\",\\n        act=\\\"write\\\",\\n    )\\n\\n\\n@pytest.mark.anyio\\nasync def test_enforce_allows_non_superuser_when_enabled():\\n    \\\"\\\"\\\"OSS stub does not deny; authorization plugin replaces this service for enforcement.\\\"\\\"\\\"\\n    settings = SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_ENABLED=True,\\n            AUTHZ_SUPERUSER_BYPASS=True,\\n        )\\n    )\\n    service = LangflowAuthorizationService(settings)\\n    user_id = uuid4()\\n    assert await service.enforce(\\n        user_id=user_id,\\n        domain=\\\"*\\\",\\n        obj=\\\"flow:abc\\\",\\n        act=\\\"write\\\",\\n        context={\\\"is_superuser\\\": False},\\n    )\\n\\n\\n@pytest.mark.anyio\\nasync def test_is_enabled_reflects_setting(authz_service):\\n    assert not await authz_service.is_enabled()\\n    authz_service.settings_service.auth_settings.AUTHZ_ENABLED = True\\n    assert await authz_service.is_enabled()\\n\\n\\n@pytest.mark.anyio\\nasync def test_batch_enforce_all_true_when_disabled(authz_service):\\n    \\\"\\\"\\\"When AUTHZ_ENABLED=False, batch_enforce returns True for every request.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    requests = [(\\\"flow:a\\\", \\\"read\\\"), (\\\"flow:b\\\", \\\"write\\\"), (\\\"flow:c\\\", \\\"delete\\\")]\\n    result = await authz_service.batch_enforce(\\n        user_id=user_id,\\n        domain=\\\"*\\\",\\n        requests=requests,\\n    )\\n    assert result == [True, True, True]\\n\\n\\n@pytest.mark.anyio\\nasync def test_batch_enforce_allows_non_superuser_when_enabled():\\n    \\\"\\\"\\\"OSS pass-through allows every batch request regardless of user context.\\\"\\\"\\\"\\n    settings = SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_ENABLED=True,\\n            AUTHZ_SUPERUSER_BYPASS=True,\\n        )\\n    )\\n    service = LangflowAuthorizationService(settings)\\n    requests = [(\\\"flow:a\\\", \\\"read\\\"), (\\\"flow:b\\\", \\\"write\\\")]\\n    result = await service.batch_enforce(\\n        user_id=uuid4(),\\n        domain=\\\"*\\\",\\n        requests=requests,\\n        context={\\\"is_superuser\\\": False},\\n    )\\n    assert result == [True, True]\\n\\n\\n@pytest.mark.anyio\\nasync def test_batch_enforce_empty_requests(authz_service):\\n    \\\"\\\"\\\"An empty request list returns an empty list.\\\"\\\"\\\"\\n    result = await authz_service.batch_enforce(\\n        user_id=uuid4(),\\n        domain=\\\"*\\\",\\n        requests=[],\\n    )\\n    assert result == []\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_allowed_actions_returns_all_actions():\\n    \\\"\\\"\\\"Pass-through service returns every requested action regardless of user/context.\\\"\\\"\\\"\\n    settings = SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_ENABLED=True,\\n            AUTHZ_SUPERUSER_BYPASS=True,\\n        )\\n    )\\n    service = LangflowAuthorizationService(settings)\\n    actions = [\\\"read\\\", \\\"write\\\", \\\"delete\\\"]\\n    result = await service.get_allowed_actions(\\n        user_id=uuid4(),\\n        domain=\\\"*\\\",\\n        obj=\\\"flow:abc\\\",\\n        actions=actions,\\n        context={\\\"is_superuser\\\": False},\\n    )\\n    assert result == actions\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_allowed_actions_returns_all_when_disabled(authz_service):\\n    \\\"\\\"\\\"When AUTHZ_ENABLED=False, every requested action is allowed.\\\"\\\"\\\"\\n    actions = [\\\"read\\\", \\\"write\\\", \\\"execute\\\"]\\n    result = await authz_service.get_allowed_actions(\\n        user_id=uuid4(),\\n        domain=\\\"*\\\",\\n        obj=\\\"flow:any\\\",\\n        actions=actions,\\n    )\\n    assert result == actions\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_cache_hooks.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6015f0be3d1844bc014fd1b714310c4b449befde53c019fe9616fa2eac4806cf\",\"content\":\"\\\"\\\"\\\"Tests for the OSS cache-invalidation hooks (no-op by default; plugin overrides).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.authorization.service import LangflowAuthorizationService\\n\\n\\n@pytest.fixture\\ndef authz_service():\\n    settings = SimpleNamespace(\\n        auth_settings=SimpleNamespace(AUTHZ_ENABLED=False, AUTHZ_SUPERUSER_BYPASS=True),\\n    )\\n    return LangflowAuthorizationService(settings)\\n\\n\\n@pytest.mark.anyio\\nasync def test_invalidate_user_is_noop(authz_service):\\n    \\\"\\\"\\\"Default invalidate_user returns None and does not raise.\\\"\\\"\\\"\\n    assert await authz_service.invalidate_user(uuid4()) is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_invalidate_role_is_noop(authz_service):\\n    \\\"\\\"\\\"Default invalidate_role returns None and does not raise.\\\"\\\"\\\"\\n    assert await authz_service.invalidate_role(uuid4()) is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_invalidate_all_is_noop(authz_service):\\n    \\\"\\\"\\\"Default invalidate_all returns None and does not raise.\\\"\\\"\\\"\\n    assert await authz_service.invalidate_all() is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_capability_flag.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d7b074d54f4bba70a89faacf3c197ece350237f2d5215be6aaecdcb98d0e7ca8\",\"content\":\"\\\"\\\"\\\"Tests for authorization service capability flags.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import FrozenInstanceError\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.authorization.service import LangflowAuthorizationService\\nfrom lfx.services.authorization import ShareRuleSnapshot\\nfrom lfx.services.authorization import base as authz_base\\nfrom lfx.services.authorization.base import BaseAuthorizationService\\nfrom lfx.services.authorization.service import AuthorizationService as LfxDefaultService\\n\\n\\ndef _settings(*, authz_enabled: bool = False) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_ENABLED=authz_enabled,\\n            AUTHZ_SUPERUSER_BYPASS=True,\\n        )\\n    )\\n\\n\\n@pytest.mark.anyio\\nasync def test_base_class_default_is_false():\\n    \\\"\\\"\\\"The class-level constant defaults False so subclasses must opt in.\\\"\\\"\\\"\\n    assert BaseAuthorizationService.SUPPORTS_CROSS_USER_FETCH is False\\n    assert BaseAuthorizationService.SUPPORTS_API_KEY_SCOPES is False\\n\\n\\n@pytest.mark.anyio\\nasync def test_public_principal_contract_is_explicit_and_defaults_deny():\\n    \\\"\\\"\\\"Anonymous authorization is a separate plugin contract, never a fake user allow-all path.\\\"\\\"\\\"\\n    principal_type = getattr(authz_base, \\\"AuthorizationPrincipal\\\", None)\\n    request_type = getattr(authz_base, \\\"PublicAuthorizationRequest\\\", None)\\n    action_type = getattr(authz_base, \\\"PublicResourceAction\\\", None)\\n\\n    assert principal_type is not None\\n    assert request_type is not None\\n    assert action_type is not None\\n\\n    first = principal_type.public_anonymous()\\n    second = principal_type.public_anonymous()\\n    assert first == second\\n    assert first.user_id is None\\n    assert first.actor_type == \\\"anonymous_public\\\"\\n\\n    request = request_type(\\n        principal=first,\\n        resource_type=\\\"flow\\\",\\n        resource_id=uuid4(),\\n        action=action_type.EXECUTE,\\n        domain_hint=\\\"*\\\",\\n        request_host=\\\"public.example.test\\\",\\n        grant_source=\\\"legacy_access_type\\\",\\n    )\\n    service = LfxDefaultService()\\n    assert await service.supports_public_principals() is False\\n    assert await service.resolve_public_tenant(request) is None\\n    assert await service.enforce_public(request, tenant=\\\"*\\\") is False\\n\\n\\n@pytest.mark.anyio\\nasync def test_lfx_default_service_does_not_support_cross_user_fetch():\\n    \\\"\\\"\\\"The lfx no-op service inherits the safe default.\\\"\\\"\\\"\\n    service = LfxDefaultService()\\n    assert await service.supports_cross_user_fetch() is False\\n    assert await service.supports_api_key_scopes() is False\\n\\n\\n@pytest.mark.anyio\\nasync def test_lfx_default_targeted_share_hooks_are_noops():\\n    \\\"\\\"\\\"New hooks stay source-compatible because the framework defaults do nothing.\\\"\\\"\\\"\\n    service = LfxDefaultService()\\n    share_id = uuid4()\\n    snapshot = ShareRuleSnapshot(\\n        share_id=share_id,\\n        resource_type=\\\"flow\\\",\\n        resource_id=uuid4(),\\n        scope=\\\"user\\\",\\n        target_id=uuid4(),\\n        permission_level=\\\"read\\\",\\n    )\\n\\n    assert await service.sync_share(share_id) is None\\n    assert await service.remove_share_rules(snapshot) is None\\n\\n\\ndef test_share_rule_snapshot_is_framework_neutral_and_immutable():\\n    snapshot = ShareRuleSnapshot(\\n        share_id=uuid4(),\\n        resource_type=\\\"flow\\\",\\n        resource_id=uuid4(),\\n        scope=\\\"team\\\",\\n        target_id=uuid4(),\\n        permission_level=\\\"write\\\",\\n    )\\n\\n    with pytest.raises(FrozenInstanceError):\\n        snapshot.permission_level = \\\"read\\\"  # type: ignore[misc]\\n\\n\\n@pytest.mark.anyio\\nasync def test_langflow_pass_through_does_not_support_cross_user_fetch():\\n    \\\"\\\"\\\"OSS pass-through must NOT opt in \u2014 that is the strict-pass-through contract.\\\"\\\"\\\"\\n    service = LangflowAuthorizationService(_settings())\\n    assert await service.supports_cross_user_fetch() is False\\n    assert await service.supports_api_key_scopes() is False\\n\\n\\n@pytest.mark.anyio\\nasync def test_subclass_can_opt_in():\\n    \\\"\\\"\\\"Authorization plugins flip capability constants; the base accepts them.\\\"\\\"\\\"\\n\\n    class _Plugin(LangflowAuthorizationService):\\n        SUPPORTS_CROSS_USER_FETCH = True\\n        SUPPORTS_API_KEY_SCOPES = True\\n\\n    service = _Plugin(_settings())\\n    assert await service.supports_cross_user_fetch() is True\\n    assert await service.supports_api_key_scopes() is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_decorators.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"11297d27d4582d0a450d908ab6ad11fc992f333668782aa483eea5c3f964daa8\",\"content\":\"\\\"\\\"\\\"Tests for authorization decorators and route dependencies.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.services.authorization.actions import FlowAction\\nfrom langflow.services.authorization.decorators import requires_flow_permission\\n\\nfrom ._common import install_audit_recorder, install_authz, install_settings\\n\\n\\n@pytest.mark.anyio\\nasync def test_requires_flow_permission_denies_before_body(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Decorator runs ensure_flow_permission before the wrapped function.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    from ._common import _StubAuthorizationService\\n\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    flow_id = uuid4()\\n    ran = False\\n\\n    @requires_flow_permission(\\n        FlowAction.READ, user_param=\\\"user\\\", flow_id_param=\\\"flow_id\\\", flow_user_id_param=\\\"owner_id\\\"\\n    )\\n    async def handler(*, user, flow_id, owner_id):  # noqa: ARG001\\n        nonlocal ran\\n        ran = True\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await handler(user=fake_user, flow_id=flow_id, owner_id=uuid4())\\n    assert exc_info.value.status_code == 403\\n    assert ran is False\\n\\n\\n@pytest.mark.anyio\\nasync def test_requires_flow_permission_maps_forbidden_to_value_error(monkeypatch, fake_user):\\n    \\\"\\\"\\\"forbidden_as_not_found preserves load_flow's ValueError contract.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    from ._common import _StubAuthorizationService\\n\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    class _Flow:\\n        id = uuid4()\\n        user_id = uuid4()\\n        workspace_id = None\\n        folder_id = None\\n        data = {\\\"nodes\\\": []}\\n\\n    @requires_flow_permission(\\n        FlowAction.EXECUTE,\\n        user_param=\\\"user\\\",\\n        flow_param=\\\"flow\\\",\\n        forbidden_as_not_found=True,\\n        not_found_template=\\\"Flow missing\\\",\\n    )\\n    async def handler(*, user, flow):  # noqa: ARG001\\n        return \\\"ok\\\"\\n\\n    with pytest.raises(ValueError, match=\\\"Flow missing\\\"):\\n        await handler(user=fake_user, flow=_Flow())\\n\\n\\ndef test_requires_flow_permission_raises_on_missing_user_param():\\n    \\\"\\\"\\\"Misconfigured decorators fail at decoration time.\\\"\\\"\\\"\\n    with pytest.raises(TypeError, match=\\\"must have a 'actor' parameter\\\"):\\n\\n        @requires_flow_permission(FlowAction.READ, user_param=\\\"actor\\\")\\n        async def bad(*, user):\\n            pass\\n\\n\\ndef test_requires_flow_permission_raises_on_missing_flow_id_param():\\n    \\\"\\\"\\\"Existing-resource actions must not silently authorize flow:*.\\\"\\\"\\\"\\n    with pytest.raises(TypeError, match=\\\"must have a 'missing_id' parameter\\\"):\\n\\n        @requires_flow_permission(FlowAction.READ, user_param=\\\"user\\\", flow_id_param=\\\"missing_id\\\")\\n        async def bad(*, user, flow_id):\\n            pass\\n\\n\\n@pytest.mark.anyio\\nasync def test_requires_flow_permission_rejects_none_flow_id_before_body(fake_user):\\n    \\\"\\\"\\\"A None resource id fails closed before ensure_flow_permission can see flow:*.\\\"\\\"\\\"\\n    ran = False\\n\\n    @requires_flow_permission(FlowAction.READ, user_param=\\\"user\\\", flow_id_param=\\\"flow_id\\\")\\n    async def handler(*, user, flow_id):  # noqa: ARG001\\n        nonlocal ran\\n        ran = True\\n\\n    with pytest.raises(ValueError, match=\\\"non-null 'flow_id'\\\"):\\n        await handler(user=fake_user, flow_id=None)\\n    assert ran is False\\n\\n\\n@pytest.mark.anyio\\nasync def test_requires_flow_permission_resource_param_rejects_missing_id_before_body(fake_user):\\n    \\\"\\\"\\\"Loaded-resource mode also fails closed when the row lacks an id.\\\"\\\"\\\"\\n    ran = False\\n\\n    class _Flow:\\n        id = None\\n        user_id = uuid4()\\n        workspace_id = None\\n        folder_id = None\\n\\n    @requires_flow_permission(FlowAction.EXECUTE, user_param=\\\"user\\\", flow_param=\\\"flow\\\")\\n    async def handler(*, user, flow):  # noqa: ARG001\\n        nonlocal ran\\n        ran = True\\n\\n    with pytest.raises(ValueError, match=\\\"non-null 'flow_id'\\\"):\\n        await handler(user=fake_user, flow=_Flow())\\n    assert ran is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_domain_resolution.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a0b379a1261691e57e804b3deb8a6b7c453bd5aff857f9cd373278955e1a51de\",\"content\":\"\\\"\\\"\\\"Tests for ``_resolve_authz_domain``, ``_split_obj``, and action coercion.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom uuid import uuid4\\n\\nfrom langflow.services.authorization import audit as authz_audit\\nfrom langflow.services.authorization import guards as authz_guards\\n\\n\\ndef test_resolve_authz_domain_precedence():\\n    \\\"\\\"\\\"Domain precedence: project > workspace > '*'.\\\"\\\"\\\"\\n    ws, scope = uuid4(), uuid4()\\n    assert authz_guards._resolve_authz_domain(workspace_id=ws, scope_id=scope) == f\\\"project:{scope}\\\"\\n    assert authz_guards._resolve_authz_domain(workspace_id=ws, scope_id=None) == f\\\"workspace:{ws}\\\"\\n    assert authz_guards._resolve_authz_domain(workspace_id=None, scope_id=scope) == f\\\"project:{scope}\\\"\\n    assert authz_guards._resolve_authz_domain(workspace_id=None, scope_id=None) == \\\"*\\\"\\n    # Backward-compatible alias still resolves to the same function.\\n    assert authz_guards._resolve_flow_domain is authz_guards._resolve_authz_domain\\n\\n\\ndef test_split_obj_parses_uuid_suffix():\\n    \\\"\\\"\\\"flow:<uuid> splits into ('flow', UUID).\\\"\\\"\\\"\\n    flow_id = uuid4()\\n    resource_type, resource_id = authz_audit._split_obj(f\\\"flow:{flow_id}\\\")\\n    assert resource_type == \\\"flow\\\"\\n    assert resource_id == flow_id\\n\\n\\ndef test_split_obj_wildcard_returns_none_id():\\n    \\\"\\\"\\\"flow:* keeps resource_type but emits None for resource_id.\\\"\\\"\\\"\\n    resource_type, resource_id = authz_audit._split_obj(\\\"flow:*\\\")\\n    assert resource_type == \\\"flow\\\"\\n    assert resource_id is None\\n\\n\\ndef test_split_obj_malformed_returns_nones():\\n    \\\"\\\"\\\"A key without a colon returns (None, None).\\\"\\\"\\\"\\n    assert authz_audit._split_obj(\\\"nothing\\\") == (None, None)\\n\\n\\ndef test_split_obj_non_uuid_suffix_returns_none_id():\\n    \\\"\\\"\\\"A non-UUID suffix is treated as a wildcard for the resource_id field.\\\"\\\"\\\"\\n    resource_type, resource_id = authz_audit._split_obj(\\\"flow:not-a-uuid\\\")\\n    assert resource_type == \\\"flow\\\"\\n    assert resource_id is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"33439ef08080b86cb972fffb2f69b55ce5719d43bbc06c581fde197fa00c1f36\",\"content\":\"\\\"\\\"\\\"Tests for AuthorizationServiceFactory.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\n\\nfrom langflow.services.authorization.factory import AuthorizationServiceFactory\\nfrom langflow.services.authorization.service import LangflowAuthorizationService\\nfrom lfx.services.authorization.base import BaseAuthorizationService\\n\\n\\ndef _make_settings_service(*, authz_enabled: bool = False, superuser_bypass: bool = True) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTHZ_ENABLED=authz_enabled,\\n            AUTHZ_SUPERUSER_BYPASS=superuser_bypass,\\n        )\\n    )\\n\\n\\ndef test_create_returns_base_authorization_service():\\n    \\\"\\\"\\\"Factory produces an instance conforming to the BaseAuthorizationService contract.\\\"\\\"\\\"\\n    factory = AuthorizationServiceFactory()\\n    service = factory.create(_make_settings_service())\\n    assert isinstance(service, BaseAuthorizationService)\\n    assert isinstance(service, LangflowAuthorizationService)\\n\\n\\ndef test_create_uses_injected_settings_service():\\n    \\\"\\\"\\\"The created service reads its configuration from the injected SettingsService.\\\"\\\"\\\"\\n    settings = _make_settings_service(authz_enabled=True)\\n    factory = AuthorizationServiceFactory()\\n    service = factory.create(settings)\\n    assert service.settings_service is settings\\n\\n\\ndef test_factory_name_matches_service_type():\\n    \\\"\\\"\\\"Factory exposes the canonical authorization service type name.\\\"\\\"\\\"\\n    from langflow.services.schema import ServiceType\\n\\n    factory = AuthorizationServiceFactory()\\n    assert factory.name == ServiceType.AUTHORIZATION_SERVICE.value\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_fetch.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"36cb757e16202ceb3bb14b9f19588fd7141c05338a8604e185b40092559f773f\",\"content\":\"\\\"\\\"\\\"Tests for share-aware fetch helpers (strict pass-through contract).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any, ClassVar\\nfrom unittest.mock import patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.services.authorization.fetch import authorized_or_owner_scoped, deny_to_404\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom lfx.services.authorization.base import BaseAuthorizationService\\n\\n# Reuse the live Flow model so the test exercises a real SQLAlchemy\\n# InstrumentedAttribute path. The session is fake \u2014 only the compiled SQL\\n# matters, not actual rows.\\n_DummyRow = Flow\\n\\n\\nclass _StubService(BaseAuthorizationService):\\n    \\\"\\\"\\\"Minimal subclass so tests can flip SUPPORTS_CROSS_USER_FETCH.\\n\\n    Cross-user fetch in the helper requires *both* the plugin capability\\n    *and* ``is_enabled()`` to be true, so tests opt into both together via\\n    ``supports_cross_user`` to mirror an authorization plugin with\\n    ``AUTHZ_ENABLED=true``.\\n    \\\"\\\"\\\"\\n\\n    SUPPORTS_CROSS_USER_FETCH: ClassVar[bool] = False\\n\\n    def __init__(self, *, supports_cross_user: bool = False) -> None:\\n        super().__init__()\\n        self._supports = supports_cross_user\\n        self.set_ready()\\n\\n    async def supports_cross_user_fetch(self) -> bool:\\n        return self._supports\\n\\n    async def is_enabled(self) -> bool:\\n        return self._supports\\n\\n    async def enforce(self, **_: Any) -> bool:\\n        return True\\n\\n    async def batch_enforce(self, *, requests, **_: Any) -> list[bool]:\\n        return [True] * len(requests)\\n\\n\\nclass _FakeResult:\\n    def __init__(self, value: Any) -> None:\\n        self._value = value\\n\\n    def first(self) -> Any:\\n        return self._value\\n\\n\\nclass _FakeSession:\\n    \\\"\\\"\\\"Captures the compiled SQL each call passes to ``exec``.\\\"\\\"\\\"\\n\\n    def __init__(self, *, returns: Any = \\\"row\\\") -> None:\\n        self.calls: list[str] = []\\n        self.statements: list[Any] = []\\n        self.returns = returns\\n\\n    async def exec(self, stmt: Any) -> _FakeResult:\\n        # str(stmt) gives the compiled SQL \u2014 enough to assert which branch ran.\\n        self.statements.append(stmt)\\n        self.calls.append(str(stmt))\\n        return _FakeResult(self.returns)\\n\\n\\n@pytest.mark.anyio\\nasync def test_owner_scoped_when_service_does_not_support_cross_user_fetch():\\n    \\\"\\\"\\\"OSS pass-through default keeps the owner predicate so visibility cannot widen.\\\"\\\"\\\"\\n    session = _FakeSession(returns=object())\\n    service = _StubService(supports_cross_user=False)\\n    with patch(\\n        \\\"langflow.services.authorization.fetch.get_authorization_service\\\",\\n        return_value=service,\\n    ):\\n        await authorized_or_owner_scoped(\\n            session,\\n            _DummyRow,\\n            id_column=_DummyRow.id,\\n            resource_id=uuid4(),\\n            owner_column=_DummyRow.user_id,\\n            owner_id=uuid4(),\\n        )\\n    # The owner-scoped branch adds a ``user_id =`` predicate in WHERE.\\n    assert \\\"user_id = :user_id\\\" in session.calls[0]\\n\\n\\n@pytest.mark.anyio\\nasync def test_id_only_when_service_supports_cross_user_fetch():\\n    \\\"\\\"\\\"Authorization plugin loads by id alone; route guard then decides access.\\\"\\\"\\\"\\n    session = _FakeSession(returns=object())\\n    service = _StubService(supports_cross_user=True)\\n    with patch(\\n        \\\"langflow.services.authorization.fetch.get_authorization_service\\\",\\n        return_value=service,\\n    ):\\n        await authorized_or_owner_scoped(\\n            session,\\n            _DummyRow,\\n            id_column=_DummyRow.id,\\n            resource_id=uuid4(),\\n            owner_column=_DummyRow.user_id,\\n            owner_id=uuid4(),\\n        )\\n    # No user_id = :user_id predicate in the share-aware path.\\n    assert \\\"user_id = :user_id\\\" not in session.calls[0]\\n    assert \\\"WHERE flow.id\\\" in session.calls[0]\\n\\n\\n@pytest.mark.anyio\\nasync def test_write_fetch_refreshes_identity_map_and_locks_row():\\n    \\\"\\\"\\\"Write attempts must authorize a current row that stays locked through mutation.\\\"\\\"\\\"\\n    session = _FakeSession(returns=object())\\n    service = _StubService(supports_cross_user=False)\\n    with patch(\\n        \\\"langflow.services.authorization.fetch.get_authorization_service\\\",\\n        return_value=service,\\n    ):\\n        await authorized_or_owner_scoped(\\n            session,\\n            _DummyRow,\\n            id_column=_DummyRow.id,\\n            resource_id=uuid4(),\\n            owner_column=_DummyRow.user_id,\\n            owner_id=uuid4(),\\n            for_update=True,\\n        )\\n\\n    assert \\\"FOR UPDATE\\\" in session.calls[0]\\n    assert session.statements[0].get_execution_options()[\\\"populate_existing\\\"] is True\\n\\n\\ndef test_deny_to_404_only_rewrites_403():\\n    \\\"\\\"\\\"The helper preserves UUID privacy by converting 403 \u2192 404 only.\\\"\\\"\\\"\\n    rewritten = deny_to_404(HTTPException(status_code=403, detail=\\\"nope\\\"))\\n    assert rewritten.status_code == 404\\n\\n    # A non-403 is surfaced unchanged \u2014 its detail is not relabeled as \\\"not found\\\".\\n    untouched = deny_to_404(HTTPException(status_code=500, detail=\\\"boom\\\"), detail=\\\"Variable not found\\\")\\n    assert untouched.status_code == 500\\n    assert untouched.detail == \\\"boom\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_filter_visible.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d2414ae0baa978c154fa167a640d85a16786e3cf4d90359903bd894266af12cc\",\"content\":\"\\\"\\\"\\\"Tests for ``filter_visible_resources`` (list-endpoint authorization filter).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.auth.context import (\\n    AUTH_METHOD_API_KEY,\\n    AuthCredentialContext,\\n    clear_current_auth_context,\\n    set_current_auth_context,\\n)\\nfrom langflow.services.authorization import guards as authz_guards\\nfrom langflow.services.authorization import listing as authz_listing\\nfrom langflow.services.authorization.actions import FlowAction\\n\\nfrom ._common import (\\n    _StubAuthorizationService,\\n    install_authz,\\n    install_settings,\\n)\\n\\n\\n@pytest.mark.anyio\\nasync def test_filter_visible_resources_noop_when_disabled(monkeypatch, fake_user):\\n    \\\"\\\"\\\"No batch_enforce call when AUTHZ_ENABLED=False; returns input unchanged.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=False)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n\\n    candidates = [SimpleNamespace(id=uuid4()) for _ in range(3)]\\n    result = await authz_listing.filter_visible_resources(\\n        fake_user,\\n        resource_type=\\\"flow\\\",\\n        candidates=candidates,\\n    )\\n    assert result == candidates\\n    assert service.batch_calls == []\\n\\n\\n@pytest.mark.anyio\\nasync def test_filter_visible_resources_empty_returns_empty(monkeypatch, fake_user):\\n    \\\"\\\"\\\"An empty candidates list is returned unchanged without contacting the service.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n\\n    result = await authz_listing.filter_visible_resources(fake_user, resource_type=\\\"flow\\\", candidates=[])\\n    assert result == []\\n    assert service.batch_calls == []\\n\\n\\n@pytest.mark.anyio\\nasync def test_filter_visible_resources_filters_via_batch_enforce(monkeypatch, fake_user):\\n    \\\"\\\"\\\"When AUTHZ_ENABLED=True, batch_enforce results filter the candidate list.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    candidates = [SimpleNamespace(id=uuid4()) for _ in range(3)]\\n    service = _StubAuthorizationService(batch_results=[True, False, True])\\n    install_authz(monkeypatch, service)\\n\\n    result = await authz_listing.filter_visible_resources(\\n        fake_user,\\n        resource_type=\\\"flow\\\",\\n        candidates=candidates,\\n    )\\n\\n    assert result == [candidates[0], candidates[2]]\\n    assert service.batch_calls[0][\\\"requests\\\"] == [\\n        (f\\\"flow:{candidates[0].id}\\\", \\\"read\\\"),\\n        (f\\\"flow:{candidates[1].id}\\\", \\\"read\\\"),\\n        (f\\\"flow:{candidates[2].id}\\\", \\\"read\\\"),\\n    ]\\n\\n\\n@pytest.mark.anyio\\nasync def test_filter_visible_resources_accepts_custom_key(monkeypatch, fake_user):\\n    \\\"\\\"\\\"A custom key extractor lets callers filter non-id-bearing items.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    items = [{\\\"resource_id\\\": uuid4()}, {\\\"resource_id\\\": uuid4()}]\\n    service = _StubAuthorizationService(batch_results=[False, True])\\n    install_authz(monkeypatch, service)\\n\\n    result = await authz_listing.filter_visible_resources(\\n        fake_user,\\n        resource_type=\\\"project\\\",\\n        candidates=items,\\n        key=lambda r: r[\\\"resource_id\\\"],\\n        act=FlowAction.WRITE,\\n    )\\n\\n    assert result == [items[1]]\\n    assert service.batch_calls[0][\\\"requests\\\"][0][1] == \\\"write\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_filter_visible_resources_groups_by_extracted_domain(monkeypatch, fake_user):\\n    \\\"\\\"\\\"With ``domain_extractor`` set, batch_enforce is called once per unique domain.\\n\\n    Each call sees only the candidates that resolved to that domain, so the\\n    authorization plugin evaluates each candidate against the right policy tuple\\n    (the single-domain default would force every candidate through the same\\n    wildcard domain, hiding project-scoped grants).\\n    \\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    workspace_a = uuid4()\\n    workspace_b = uuid4()\\n\\n    items = [\\n        SimpleNamespace(id=uuid4(), workspace_id=workspace_a, folder_id=None),\\n        SimpleNamespace(id=uuid4(), workspace_id=workspace_b, folder_id=None),\\n        SimpleNamespace(id=uuid4(), workspace_id=workspace_a, folder_id=None),\\n    ]\\n\\n    # Deny everything in workspace_b, allow everything in workspace_a.\\n    class _DomainAwareStub:\\n        def __init__(self) -> None:\\n            self.batch_calls: list[dict] = []\\n\\n        async def batch_enforce(self, **kwargs) -> list[bool]:\\n            self.batch_calls.append(kwargs)\\n            allowed = kwargs[\\\"domain\\\"] != f\\\"workspace:{workspace_b}\\\"\\n            return [allowed] * len(kwargs[\\\"requests\\\"])\\n\\n    service = _DomainAwareStub()\\n    install_authz(monkeypatch, service)\\n\\n    result = await authz_listing.filter_visible_resources(\\n        fake_user,\\n        resource_type=\\\"project\\\",\\n        candidates=items,\\n        domain_extractor=lambda project: authz_guards._resolve_authz_domain(project.workspace_id, None),\\n        act=FlowAction.READ,\\n    )\\n\\n    # Two calls \u2014 one per unique domain.\\n    domains_called = {call[\\\"domain\\\"] for call in service.batch_calls}\\n    assert domains_called == {f\\\"workspace:{workspace_a}\\\", f\\\"workspace:{workspace_b}\\\"}\\n\\n    # Output preserves the original order, with workspace_b's item dropped.\\n    assert result == [items[0], items[2]]\\n\\n\\n@pytest.mark.anyio\\nasync def test_filter_visible_resources_owner_override_skips_enforcer(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Items owned by the caller are force-included without consulting the enforcer.\\n\\n    Mirrors the owner-override short-circuit in ``_ensure_resource_permission``\\n    so list and direct-read agree under plugin enforcement. Without this,\\n    a deny-all plugin would hide the caller's own rows from the listing\\n    response while letting them read the same rows directly.\\n    \\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    other_user = uuid4()\\n\\n    items = [\\n        SimpleNamespace(id=uuid4(), user_id=fake_user.id),  # owned \u2192 must keep\\n        SimpleNamespace(id=uuid4(), user_id=other_user),  # not owned \u2192 enforcer decides\\n        SimpleNamespace(id=uuid4(), user_id=fake_user.id),  # owned \u2192 must keep\\n    ]\\n    # Deny-all stub so any item that reaches the enforcer would be dropped.\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n\\n    result = await authz_listing.filter_visible_resources(\\n        fake_user,\\n        resource_type=\\\"flow\\\",\\n        candidates=items,\\n        owner_extractor=lambda item: item.user_id,\\n        act=FlowAction.READ,\\n    )\\n\\n    # Owned items kept (positions 0 and 2); non-owned item dropped by deny.\\n    assert result == [items[0], items[2]]\\n    # Enforcer was consulted only for the non-owned item.\\n    assert len(service.batch_calls) == 1\\n    assert len(service.batch_calls[0][\\\"requests\\\"]) == 1\\n\\n\\n@pytest.mark.anyio\\nasync def test_filter_visible_resources_api_key_scope_plugin_evaluates_owned_rows(monkeypatch, fake_user):\\n    \\\"\\\"\\\"API-key scope plugins can filter owned rows instead of owner-skipping them.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    items = [\\n        SimpleNamespace(id=uuid4(), user_id=fake_user.id),\\n        SimpleNamespace(id=uuid4(), user_id=fake_user.id),\\n    ]\\n    service = _StubAuthorizationService(batch_results=[True, False], supports_api_key_scopes=True)\\n    install_authz(monkeypatch, service)\\n    set_current_auth_context(\\n        AuthCredentialContext(\\n            method=AUTH_METHOD_API_KEY,\\n            api_key_id=uuid4(),\\n            api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n        )\\n    )\\n\\n    try:\\n        result = await authz_listing.filter_visible_resources(\\n            fake_user,\\n            resource_type=\\\"flow\\\",\\n            candidates=items,\\n            owner_extractor=lambda item: item.user_id,\\n            act=FlowAction.READ,\\n        )\\n    finally:\\n        clear_current_auth_context()\\n\\n    assert result == [items[0]]\\n    assert len(service.batch_calls) == 1\\n    assert service.batch_calls[0][\\\"requests\\\"] == [\\n        (f\\\"flow:{items[0].id}\\\", \\\"read\\\"),\\n        (f\\\"flow:{items[1].id}\\\", \\\"read\\\"),\\n    ]\\n    assert service.batch_calls[0][\\\"context\\\"][\\\"auth_method\\\"] == \\\"api_key\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_guards.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"db1dfdd68a290eacc1a9ba0f28f679e26e0090ed4caa0491663164f212cff672\",\"content\":\"\\\"\\\"\\\"Tests for ``ensure_permission`` and the ``ensure_*_permission`` family.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.services.auth.context import (\\n    AUTH_METHOD_API_KEY,\\n    AuthCredentialContext,\\n    clear_current_auth_context,\\n    set_current_auth_context,\\n)\\nfrom langflow.services.authorization import guards as authz_guards\\nfrom langflow.services.authorization.access_ceiling import (\\n    ExternalAccessContext,\\n    set_current_external_access_context,\\n)\\nfrom langflow.services.authorization.actions import (\\n    DeploymentAction,\\n    FileAction,\\n    FlowAction,\\n    KnowledgeBaseAction,\\n    ProjectAction,\\n    ProviderAccountAction,\\n    ShareAction,\\n    VariableAction,\\n    VoiceAction,\\n)\\n\\nfrom ._common import (\\n    _StubAuthorizationService,\\n    install_audit_recorder,\\n    install_authz,\\n    install_settings,\\n)\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_permission\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_permission_noop_when_disabled(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Disabled enforcement allows without consulting the service but still audits.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=False, audit_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_permission(fake_user, domain=\\\"*\\\", obj=\\\"flow:abc\\\", act=\\\"read\\\")\\n    assert service.calls == []\\n    assert audit_calls[0][\\\"result\\\"] == \\\"allow\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_permission_allows_when_enforce_returns_true(monkeypatch, fake_user):\\n    \\\"\\\"\\\"A True enforce result returns None and forwards the merged context.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_permission(\\n        fake_user,\\n        domain=\\\"*\\\",\\n        obj=\\\"flow:abc\\\",\\n        act=\\\"read\\\",\\n        context={\\\"extra\\\": \\\"value\\\"},\\n    )\\n\\n    assert len(service.calls) == 1\\n    call = service.calls[0]\\n    assert call[\\\"user_id\\\"] == fake_user.id\\n    assert call[\\\"obj\\\"] == \\\"flow:abc\\\"\\n    assert call[\\\"act\\\"] == \\\"read\\\"\\n    assert call[\\\"context\\\"] == {\\\"is_superuser\\\": False, \\\"extra\\\": \\\"value\\\"}\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_permission_caller_context_cannot_override_is_superuser(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Caller-supplied context must not be able to overwrite the user-derived is_superuser flag.\\n\\n    Regression for PR #13153 review: previously the merge was\\n    ``{**_auth_context(user), **(context or {})}`` which let a caller forge\\n    ``context={\\\"is_superuser\\\": True}`` for a non-superuser. The merged context\\n    forwarded to ``enforce`` must always reflect the user's actual privilege.\\n    \\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_permission(\\n        fake_user,\\n        domain=\\\"*\\\",\\n        obj=\\\"flow:abc\\\",\\n        act=\\\"read\\\",\\n        context={\\\"is_superuser\\\": True, \\\"extra\\\": \\\"value\\\"},\\n    )\\n\\n    assert len(service.calls) == 1\\n    forwarded_context = service.calls[0][\\\"context\\\"]\\n    assert forwarded_context[\\\"is_superuser\\\"] is False\\n    assert forwarded_context[\\\"extra\\\"] == \\\"value\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_permission_raises_403_with_non_disclosing_default(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Default deny detail must NOT echo the resource UUID \u2014 see PR #13153 review item I2.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    install_authz(monkeypatch, _StubAuthorizationService(allow=False))\\n    install_audit_recorder(monkeypatch)\\n\\n    flow_id = uuid4()\\n    with pytest.raises(HTTPException) as exc_info:\\n        await authz_guards.ensure_permission(fake_user, domain=\\\"*\\\", obj=f\\\"flow:{flow_id}\\\", act=\\\"write\\\")\\n\\n    assert exc_info.value.status_code == 403\\n    # The default message MUST NOT contain the resource UUID or the action verb \u2014\\n    # otherwise a caller that forgets to wrap in deny_to_404 leaks existence.\\n    detail = exc_info.value.detail.lower()\\n    assert str(flow_id) not in detail\\n    assert \\\"write\\\" not in detail\\n    assert \\\"permission denied\\\" in detail\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_permission_accepts_explicit_detail_override(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Callers that have already verified resource existence may pass a richer message.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    install_authz(monkeypatch, _StubAuthorizationService(allow=False))\\n    install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await authz_guards.ensure_permission(\\n            fake_user,\\n            domain=\\\"*\\\",\\n            obj=\\\"flow:abc\\\",\\n            act=\\\"write\\\",\\n            detail=\\\"Cannot edit a published flow.\\\",\\n        )\\n\\n    assert exc_info.value.detail == \\\"Cannot edit a published flow.\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_permission_writes_audit_on_allow(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Allow path schedules an audit row with result='allow'.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    install_authz(monkeypatch, _StubAuthorizationService(allow=True))\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_permission(fake_user, domain=\\\"project:1\\\", obj=\\\"flow:abc\\\", act=\\\"read\\\")\\n\\n    assert len(audit_calls) == 1\\n    assert audit_calls[0][\\\"result\\\"] == \\\"allow\\\"\\n    assert audit_calls[0][\\\"obj\\\"] == \\\"flow:abc\\\"\\n    assert audit_calls[0][\\\"action\\\"] == \\\"flow:read\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_permission_writes_audit_on_deny(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Deny path schedules an audit row with result='deny' before the 403 raises.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    install_authz(monkeypatch, _StubAuthorizationService(allow=False))\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException):\\n        await authz_guards.ensure_permission(fake_user, domain=\\\"*\\\", obj=\\\"flow:abc\\\", act=\\\"delete\\\")\\n\\n    assert len(audit_calls) == 1\\n    assert audit_calls[0][\\\"result\\\"] == \\\"deny\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_permission_forwards_auth_context(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Credential metadata is available to plugins and audit without route signature churn.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n    api_key_id = uuid4()\\n    set_current_auth_context(\\n        AuthCredentialContext(\\n            method=AUTH_METHOD_API_KEY,\\n            api_key_id=api_key_id,\\n            api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n        )\\n    )\\n\\n    try:\\n        await authz_guards.ensure_permission(fake_user, domain=\\\"*\\\", obj=\\\"flow:abc\\\", act=\\\"read\\\")\\n    finally:\\n        clear_current_auth_context()\\n\\n    forwarded_context = service.calls[0][\\\"context\\\"]\\n    assert forwarded_context[\\\"auth_method\\\"] == \\\"api_key\\\"\\n    assert forwarded_context[\\\"api_key_id\\\"] == api_key_id\\n    assert forwarded_context[\\\"api_key_source\\\"] == \\\"db\\\"  # pragma: allowlist secret\\n    assert audit_calls[0][\\\"details\\\"][\\\"auth_method\\\"] == \\\"api_key\\\"\\n    assert audit_calls[0][\\\"details\\\"][\\\"api_key_id\\\"] == str(api_key_id)\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_flow_permission \u2014 enum coercion, domain, owner override\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flow_permission_accepts_enum(monkeypatch, fake_user):\\n    \\\"\\\"\\\"A FlowAction enum is coerced to its string value before enforce.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    flow_id = uuid4()\\n    await authz_guards.ensure_flow_permission(fake_user, FlowAction.READ, flow_id=flow_id)\\n\\n    assert service.calls[0][\\\"act\\\"] == \\\"read\\\"\\n    assert service.calls[0][\\\"obj\\\"] == f\\\"flow:{flow_id}\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flow_permission_accepts_string_for_backcompat(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Bare string actions still work \u2014 gradual migration is allowed.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_flow_permission(fake_user, \\\"write\\\", flow_id=uuid4())\\n    assert service.calls[0][\\\"act\\\"] == \\\"write\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flow_permission_computes_workspace_domain(monkeypatch, fake_user):\\n    \\\"\\\"\\\"workspace_id is mapped to a workspace: domain string and forwarded in context.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    workspace_id = uuid4()\\n    await authz_guards.ensure_flow_permission(\\n        fake_user,\\n        FlowAction.READ,\\n        flow_id=uuid4(),\\n        flow_user_id=uuid4(),\\n        workspace_id=workspace_id,\\n    )\\n\\n    assert service.calls[0][\\\"domain\\\"] == f\\\"workspace:{workspace_id}\\\"\\n    assert service.calls[0][\\\"context\\\"][\\\"workspace_id\\\"] == workspace_id\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flow_permission_falls_back_to_project_domain(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Without workspace_id, folder_id maps to a project: domain string.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    folder_id = uuid4()\\n    await authz_guards.ensure_flow_permission(\\n        fake_user,\\n        FlowAction.READ,\\n        flow_id=uuid4(),\\n        flow_user_id=uuid4(),\\n        folder_id=folder_id,\\n    )\\n\\n    assert service.calls[0][\\\"domain\\\"] == f\\\"project:{folder_id}\\\"\\n    assert service.calls[0][\\\"context\\\"][\\\"folder_id\\\"] == folder_id\\n    assert service.calls[0][\\\"context\\\"][\\\"workspace_id\\\"] is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flow_permission_project_beats_workspace(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Project domain wins when both workspace_id and folder_id are set.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    workspace_id = uuid4()\\n    folder_id = uuid4()\\n    await authz_guards.ensure_flow_permission(\\n        fake_user,\\n        FlowAction.READ,\\n        flow_id=uuid4(),\\n        flow_user_id=uuid4(),\\n        workspace_id=workspace_id,\\n        folder_id=folder_id,\\n    )\\n\\n    assert service.calls[0][\\\"domain\\\"] == f\\\"project:{folder_id}\\\"\\n    # workspace_id is still passed in context so the plugin can use it for ABAC matchers.\\n    assert service.calls[0][\\\"context\\\"][\\\"folder_id\\\"] == folder_id\\n    assert service.calls[0][\\\"context\\\"][\\\"workspace_id\\\"] == workspace_id\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flow_permission_wildcard_domain_when_neither_set(monkeypatch, fake_user):\\n    \\\"\\\"\\\"With neither workspace_id nor folder_id, domain falls back to '*'.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_flow_permission(fake_user, FlowAction.CREATE)\\n    assert service.calls[0][\\\"domain\\\"] == \\\"*\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_owner_override_skips_enforce(monkeypatch, fake_user):\\n    \\\"\\\"\\\"A flow owner short-circuits the enforce call entirely.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)  # Would deny if asked.\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_flow_permission(\\n        fake_user,\\n        FlowAction.DELETE,\\n        flow_id=uuid4(),\\n        flow_user_id=fake_user.id,\\n        workspace_id=uuid4(),\\n    )\\n\\n    assert service.calls == []\\n    assert len(audit_calls) == 1\\n    assert audit_calls[0][\\\"result\\\"] == \\\"owner_override\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_api_key_scope_plugin_sees_owner_resource_instead_of_owner_override(monkeypatch, fake_user):\\n    \\\"\\\"\\\"API-key scopes can be narrower than the owning user when a plugin opts in.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False, supports_api_key_scopes=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n    set_current_auth_context(\\n        AuthCredentialContext(\\n            method=AUTH_METHOD_API_KEY,\\n            api_key_id=uuid4(),\\n            api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n        )\\n    )\\n\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await authz_guards.ensure_flow_permission(\\n                fake_user,\\n                FlowAction.DELETE,\\n                flow_id=uuid4(),\\n                flow_user_id=fake_user.id,\\n            )\\n    finally:\\n        clear_current_auth_context()\\n\\n    assert exc_info.value.status_code == 403\\n    assert len(service.calls) == 1\\n    assert service.calls[0][\\\"context\\\"][\\\"flow_user_id\\\"] == fake_user.id\\n    assert service.calls[0][\\\"context\\\"][\\\"auth_method\\\"] == \\\"api_key\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_external_viewer_ceiling_denies_before_owner_override(monkeypatch, fake_user):\\n    \\\"\\\"\\\"A viewer claim is a deny-only ceiling even when the user owns the flow.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=False, audit_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n    set_current_external_access_context(ExternalAccessContext(provider=\\\"openrag\\\", subject=\\\"subject-1\\\", level=\\\"viewer\\\"))\\n\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await authz_guards.ensure_flow_permission(\\n                fake_user,\\n                FlowAction.WRITE,\\n                flow_id=uuid4(),\\n                flow_user_id=fake_user.id,\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    assert \\\"External credentials\\\" in exc_info.value.detail\\n    assert service.calls == []\\n    assert audit_calls[0][\\\"result\\\"] == \\\"deny\\\"\\n    assert audit_calls[0][\\\"details\\\"][\\\"external_access_level\\\"] == \\\"viewer\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_external_editor_ceiling_allows_write_then_owner_override(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Editor is still only a ceiling; normal owner/plugin logic continues after it passes.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True, audit_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n    set_current_external_access_context(ExternalAccessContext(provider=\\\"openrag\\\", subject=\\\"subject-1\\\", level=\\\"editor\\\"))\\n\\n    try:\\n        await authz_guards.ensure_flow_permission(\\n            fake_user,\\n            FlowAction.WRITE,\\n            flow_id=uuid4(),\\n            flow_user_id=fake_user.id,\\n        )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert service.calls == []\\n    assert audit_calls[0][\\\"result\\\"] == \\\"owner_override\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_owner_override_audits_even_when_authz_disabled(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Owner override on a disabled-authz install still writes an audit row.\\n\\n    Audit is now gated only on ``AUTHZ_AUDIT_ENABLED`` (the audit recorder\\n    here intercepts at that level), so operators can observe traffic ahead of\\n    flipping ``AUTHZ_ENABLED``. ``install_settings`` defaults the audit flag\\n    to False so we explicitly enable it here.\\n    \\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=False, audit_enabled=True)\\n    install_authz(monkeypatch, _StubAuthorizationService(allow=False))\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_flow_permission(\\n        fake_user,\\n        FlowAction.WRITE,\\n        flow_id=uuid4(),\\n        flow_user_id=fake_user.id,\\n    )\\n    assert len(audit_calls) == 1\\n    assert audit_calls[0][\\\"result\\\"] == \\\"owner_override\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_non_owner_falls_through_to_enforce(monkeypatch, fake_user):\\n    \\\"\\\"\\\"When flow_user_id differs from current user, enforce is called normally.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    install_authz(monkeypatch, _StubAuthorizationService(allow=False))\\n    install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException):\\n        await authz_guards.ensure_flow_permission(\\n            fake_user,\\n            FlowAction.WRITE,\\n            flow_id=uuid4(),\\n            flow_user_id=uuid4(),\\n        )\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_flows_permission \u2014 batched enforce\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flows_permission_batches_flow_ids(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Non-owned flow ids are authorized with one batch_enforce call.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    flow_ids = [uuid4(), uuid4(), uuid4()]\\n    workspace_id = uuid4()\\n\\n    await authz_guards.ensure_flows_permission(\\n        fake_user,\\n        FlowAction.DEPLOY,\\n        flow_ids=flow_ids,\\n        flow_user_id=uuid4(),\\n        workspace_id=workspace_id,\\n    )\\n\\n    assert len(service.batch_calls) == 1\\n    assert service.calls == []\\n    assert service.batch_calls[0][\\\"domain\\\"] == f\\\"workspace:{workspace_id}\\\"\\n    assert service.batch_calls[0][\\\"requests\\\"] == [\\n        (f\\\"flow:{flow_ids[0]}\\\", \\\"deploy\\\"),\\n        (f\\\"flow:{flow_ids[1]}\\\", \\\"deploy\\\"),\\n        (f\\\"flow:{flow_ids[2]}\\\", \\\"deploy\\\"),\\n    ]\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flows_permission_raises_when_any_denied(monkeypatch, fake_user):\\n    \\\"\\\"\\\"A single deny in the batch fails the whole call with 403.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(batch_results=[True, False])\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await authz_guards.ensure_flows_permission(\\n            fake_user,\\n            FlowAction.DEPLOY,\\n            flow_ids=[uuid4(), uuid4()],\\n            flow_user_id=uuid4(),\\n        )\\n\\n    assert exc_info.value.status_code == 403\\n    assert len(service.batch_calls) == 1\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flows_permission_fails_closed_on_result_count_mismatch(monkeypatch, fake_user):\\n    \\\"\\\"\\\"A malformed batch result is audited and denied instead of escaping as ValueError.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(batch_results=[True])\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await authz_guards.ensure_flows_permission(\\n            fake_user,\\n            FlowAction.DEPLOY,\\n            flow_ids=[uuid4(), uuid4()],\\n            flow_user_id=uuid4(),\\n        )\\n\\n    assert exc_info.value.status_code == 403\\n    assert len(service.batch_calls) == 1\\n    assert audit_calls[-1][\\\"result\\\"] == \\\"deny\\\"\\n    assert audit_calls[-1][\\\"details\\\"][\\\"error\\\"] == \\\"batch_enforce result count mismatch\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flows_permission_applies_external_ceiling_when_authz_disabled(monkeypatch, fake_user):\\n    \\\"\\\"\\\"The external deploy ceiling remains enforceable in the default OSS RBAC mode.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=False)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n    set_current_external_access_context(ExternalAccessContext(provider=\\\"openrag\\\", subject=\\\"subject-1\\\", level=\\\"editor\\\"))\\n\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await authz_guards.ensure_flows_permission(\\n                fake_user,\\n                FlowAction.DEPLOY,\\n                flow_ids=[uuid4()],\\n                flow_user_id=fake_user.id,\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    assert service.batch_calls == []\\n    assert audit_calls[-1][\\\"result\\\"] == \\\"deny\\\"\\n    assert audit_calls[-1][\\\"details\\\"][\\\"external_access_level\\\"] == \\\"editor\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_flows_permission_owner_override_skips_batch(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Owned flow ids short-circuit without batch_enforce when owner override applies.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_flows_permission(\\n        fake_user,\\n        FlowAction.DEPLOY,\\n        flow_ids=[uuid4(), uuid4()],\\n        flow_user_id=fake_user.id,\\n    )\\n\\n    assert service.batch_calls == []\\n    assert service.calls == []\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_project_permission\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_project_permission_accepts_enum(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    project_id = uuid4()\\n    await authz_guards.ensure_project_permission(fake_user, ProjectAction.READ, project_id=project_id)\\n    assert service.calls[0][\\\"act\\\"] == \\\"read\\\"\\n    assert service.calls[0][\\\"obj\\\"] == f\\\"project:{project_id}\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_project_permission_uses_project_domain(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    project_id = uuid4()\\n    workspace_id = uuid4()\\n    await authz_guards.ensure_project_permission(\\n        fake_user, ProjectAction.WRITE, project_id=project_id, project_user_id=uuid4(), workspace_id=workspace_id\\n    )\\n    assert service.calls[0][\\\"domain\\\"] == f\\\"project:{project_id}\\\"\\n    assert service.calls[0][\\\"context\\\"][\\\"project_id\\\"] == project_id\\n    assert service.calls[0][\\\"context\\\"][\\\"workspace_id\\\"] == workspace_id\\n\\n\\n@pytest.mark.anyio\\nasync def test_project_owner_override_skips_enforce(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_project_permission(\\n        fake_user,\\n        ProjectAction.DELETE,\\n        project_id=uuid4(),\\n        project_user_id=fake_user.id,\\n        workspace_id=uuid4(),\\n    )\\n\\n    assert service.calls == []\\n    assert len(audit_calls) == 1\\n    assert audit_calls[0][\\\"result\\\"] == \\\"owner_override\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_project_permission_create_uses_wildcard_obj(monkeypatch, fake_user):\\n    \\\"\\\"\\\"ProjectAction.CREATE without a project_id targets ``project:*`` (workspace-scoped create).\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_project_permission(fake_user, ProjectAction.CREATE)\\n    assert service.calls[0][\\\"domain\\\"] == \\\"*\\\"\\n    assert service.calls[0][\\\"obj\\\"] == \\\"project:*\\\"\\n    assert service.calls[0][\\\"act\\\"] == \\\"create\\\"\\n    assert service.calls[0][\\\"context\\\"][\\\"workspace_id\\\"] is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_project_permission_create_uses_workspace_domain(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    workspace_id = uuid4()\\n    await authz_guards.ensure_project_permission(fake_user, ProjectAction.CREATE, workspace_id=workspace_id)\\n\\n    assert service.calls[0][\\\"domain\\\"] == f\\\"workspace:{workspace_id}\\\"\\n    assert service.calls[0][\\\"obj\\\"] == \\\"project:*\\\"\\n    assert service.calls[0][\\\"context\\\"][\\\"project_id\\\"] is None\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_deployment_permission\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_ensure_deployment_permission_uses_project_domain(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    project_id = uuid4()\\n    await authz_guards.ensure_deployment_permission(\\n        fake_user,\\n        DeploymentAction.READ,\\n        deployment_id=uuid4(),\\n        deployment_user_id=uuid4(),\\n        project_id=project_id,\\n    )\\n\\n    assert service.calls[0][\\\"domain\\\"] == f\\\"project:{project_id}\\\"\\n    assert service.calls[0][\\\"context\\\"][\\\"project_id\\\"] == project_id\\n\\n\\n@pytest.mark.anyio\\nasync def test_deployment_owner_override_skips_enforce(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_deployment_permission(\\n        fake_user,\\n        DeploymentAction.DELETE,\\n        deployment_id=uuid4(),\\n        deployment_user_id=fake_user.id,\\n        project_id=uuid4(),\\n    )\\n\\n    assert service.calls == []\\n    assert len(audit_calls) == 1\\n    assert audit_calls[0][\\\"result\\\"] == \\\"owner_override\\\"\\n    assert audit_calls[0][\\\"action\\\"] == \\\"deployment:delete\\\"\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_provider_account_permission\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_provider_account_owner_and_scoped_api_key_personas(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Personal owner access yields only after external and scoped-key ceilings pass.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False, supports_api_key_scopes=True)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n    provider_account_id = uuid4()\\n\\n    await authz_guards.ensure_provider_account_permission(\\n        fake_user,\\n        ProviderAccountAction.WRITE,\\n        provider_account_id=provider_account_id,\\n        provider_account_user_id=fake_user.id,\\n    )\\n    assert service.calls == []\\n    assert audit_calls[-1][\\\"result\\\"] == \\\"owner_override\\\"\\n\\n    set_current_external_access_context(ExternalAccessContext(provider=\\\"openrag\\\", subject=\\\"subject-1\\\", level=\\\"viewer\\\"))\\n    try:\\n        with pytest.raises(HTTPException) as external_exc:\\n            await authz_guards.ensure_provider_account_permission(\\n                fake_user,\\n                ProviderAccountAction.CREATE,\\n                provider_account_user_id=fake_user.id,\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert external_exc.value.status_code == 403\\n    assert \\\"External credentials\\\" in external_exc.value.detail\\n    assert service.calls == []\\n\\n    set_current_auth_context(\\n        AuthCredentialContext(\\n            method=AUTH_METHOD_API_KEY,\\n            api_key_id=uuid4(),\\n            api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n        )\\n    )\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await authz_guards.ensure_provider_account_permission(\\n                fake_user,\\n                ProviderAccountAction.DELETE,\\n                provider_account_id=provider_account_id,\\n                provider_account_user_id=fake_user.id,\\n            )\\n    finally:\\n        clear_current_auth_context()\\n\\n    assert exc_info.value.status_code == 403\\n    assert service.calls[-1][\\\"obj\\\"] == f\\\"provider_account:{provider_account_id}\\\"\\n    assert service.calls[-1][\\\"act\\\"] == \\\"delete\\\"\\n    assert service.calls[-1][\\\"context\\\"][\\\"provider_account_user_id\\\"] == fake_user.id\\n\\n\\n@pytest.mark.anyio\\nasync def test_voice_owner_and_scoped_api_key_personas(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Voice metadata follows owner override but still honors a narrower API-key scope.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False, supports_api_key_scopes=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_voice_permission(\\n        fake_user,\\n        VoiceAction.READ,\\n        voice_user_id=fake_user.id,\\n    )\\n    assert service.calls == []\\n\\n    set_current_auth_context(\\n        AuthCredentialContext(\\n            method=AUTH_METHOD_API_KEY,\\n            api_key_id=uuid4(),\\n            api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n        )\\n    )\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await authz_guards.ensure_voice_permission(\\n                fake_user,\\n                VoiceAction.READ,\\n                voice_user_id=fake_user.id,\\n            )\\n    finally:\\n        clear_current_auth_context()\\n\\n    assert exc_info.value.status_code == 403\\n    assert service.calls[-1][\\\"obj\\\"] == \\\"voice:*\\\"\\n    assert service.calls[-1][\\\"context\\\"][\\\"voice_user_id\\\"] == fake_user.id\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_knowledge_base_permission\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_kb_permission_uses_kb_id_object_slug(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    kb_id = uuid4()\\n    await authz_guards.ensure_knowledge_base_permission(\\n        fake_user,\\n        KnowledgeBaseAction.READ,\\n        kb_id=kb_id,\\n        kb_name=\\\"my-kb\\\",\\n        kb_user_id=uuid4(),\\n    )\\n\\n    assert service.calls[0][\\\"obj\\\"] == f\\\"knowledge_base:{kb_id}\\\"\\n    assert service.calls[0][\\\"act\\\"] == \\\"read\\\"\\n    # ``kb_name`` is forwarded in the context for debugging.\\n    assert service.calls[0][\\\"context\\\"][\\\"kb_name\\\"] == \\\"my-kb\\\"\\n    assert service.calls[0][\\\"context\\\"][\\\"kb_id\\\"] == kb_id\\n\\n\\n@pytest.mark.anyio\\nasync def test_kb_permission_owner_override(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_knowledge_base_permission(\\n        fake_user,\\n        KnowledgeBaseAction.DELETE,\\n        kb_id=uuid4(),\\n        kb_name=\\\"my-kb\\\",\\n        kb_user_id=fake_user.id,\\n    )\\n\\n    assert service.calls == []\\n    assert audit_calls[0][\\\"result\\\"] == \\\"owner_override\\\"\\n    assert audit_calls[0][\\\"action\\\"] == \\\"knowledge_base:delete\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_kb_permission_denied_raises_403(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await authz_guards.ensure_knowledge_base_permission(\\n            fake_user,\\n            KnowledgeBaseAction.DELETE,\\n            kb_id=uuid4(),\\n            kb_name=\\\"someone-elses\\\",\\n            kb_user_id=uuid4(),\\n        )\\n    assert exc.value.status_code == 403\\n\\n\\n@pytest.mark.anyio\\nasync def test_kb_create_permission_ignores_prospective_owner(monkeypatch, fake_user):\\n    \\\"\\\"\\\"CREATE has no existing owner, so a prospective owner cannot bypass policy.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await authz_guards.ensure_knowledge_base_permission(\\n            fake_user,\\n            KnowledgeBaseAction.CREATE,\\n            kb_user_id=fake_user.id,\\n        )\\n\\n    assert exc.value.status_code == 403\\n    assert service.calls[0][\\\"obj\\\"] == \\\"knowledge_base:*\\\"\\n    assert service.calls[0][\\\"act\\\"] == \\\"create\\\"\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_variable_permission\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_variable_permission_uses_variable_object_slug(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    variable_id = uuid4()\\n    await authz_guards.ensure_variable_permission(\\n        fake_user,\\n        VariableAction.WRITE,\\n        variable_id=variable_id,\\n        variable_user_id=uuid4(),\\n    )\\n\\n    assert service.calls[0][\\\"obj\\\"] == f\\\"variable:{variable_id}\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_variable_permission_owner_override(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_variable_permission(\\n        fake_user,\\n        VariableAction.DELETE,\\n        variable_id=uuid4(),\\n        variable_user_id=fake_user.id,\\n    )\\n\\n    assert service.calls == []\\n    assert audit_calls[0][\\\"result\\\"] == \\\"owner_override\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_variable_create_permission_ignores_prospective_owner(monkeypatch, fake_user):\\n    \\\"\\\"\\\"The shared CREATE rule also closes the adjacent variable-owner bypass.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await authz_guards.ensure_variable_permission(\\n            fake_user,\\n            VariableAction.CREATE,\\n            variable_user_id=fake_user.id,\\n        )\\n\\n    assert exc.value.status_code == 403\\n    assert service.calls[0][\\\"obj\\\"] == \\\"variable:*\\\"\\n    assert service.calls[0][\\\"act\\\"] == \\\"create\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_create_audits_allow_when_enforcement_is_disabled(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Prospective ownership must not suppress audit-only CREATE visibility.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=False, audit_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_file_permission(\\n        fake_user,\\n        FileAction.CREATE,\\n        file_user_id=fake_user.id,\\n    )\\n\\n    assert service.calls == []\\n    assert len(audit_calls) == 1\\n    assert audit_calls[0][\\\"result\\\"] == \\\"allow\\\"\\n    assert audit_calls[0][\\\"action\\\"] == \\\"file:create\\\"\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_file_permission\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_file_permission_uses_file_object_slug(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    file_id = uuid4()\\n    await authz_guards.ensure_file_permission(\\n        fake_user,\\n        FileAction.READ,\\n        file_id=file_id,\\n        file_user_id=uuid4(),\\n    )\\n\\n    assert service.calls[0][\\\"obj\\\"] == f\\\"file:{file_id}\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_file_permission_owner_override(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_file_permission(\\n        fake_user,\\n        FileAction.DELETE,\\n        file_id=uuid4(),\\n        file_user_id=fake_user.id,\\n    )\\n\\n    assert service.calls == []\\n    assert audit_calls[0][\\\"result\\\"] == \\\"owner_override\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_file_create_permission_ignores_prospective_owner(monkeypatch, fake_user):\\n    \\\"\\\"\\\"CREATE has no existing owner, so a prospective owner cannot bypass policy.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await authz_guards.ensure_file_permission(\\n            fake_user,\\n            FileAction.CREATE,\\n            file_user_id=fake_user.id,\\n        )\\n\\n    assert exc.value.status_code == 403\\n    assert service.calls[0][\\\"obj\\\"] == \\\"file:*\\\"\\n    assert service.calls[0][\\\"act\\\"] == \\\"create\\\"\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# ensure_share_permission\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_share_permission_uses_share_object_slug(monkeypatch, fake_user):\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=True)\\n    install_authz(monkeypatch, service)\\n    install_audit_recorder(monkeypatch)\\n\\n    share_id = uuid4()\\n    await authz_guards.ensure_share_permission(\\n        fake_user,\\n        ShareAction.CREATE,\\n        share_id=share_id,\\n        share_user_id=uuid4(),\\n    )\\n\\n    assert service.calls[0][\\\"obj\\\"] == f\\\"share:{share_id}\\\"\\n    assert service.calls[0][\\\"act\\\"] == \\\"create\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_share_create_permission_uses_existing_resource_owner_override(monkeypatch, fake_user):\\n    \\\"\\\"\\\"Share CREATE is the exception: its owner is the existing target's owner.\\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=True)\\n    service = _StubAuthorizationService(allow=False)\\n    install_authz(monkeypatch, service)\\n    audit_calls = install_audit_recorder(monkeypatch)\\n\\n    await authz_guards.ensure_share_permission(\\n        fake_user,\\n        ShareAction.CREATE,\\n        share_user_id=fake_user.id,\\n    )\\n\\n    assert service.calls == []\\n    assert audit_calls[0][\\\"result\\\"] == \\\"owner_override\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_le1905_regressions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7f687821fccc5ce774ead0dbab431f4b2881ef121caf483c91a4bc1a3a29bfcb\",\"content\":\"\\\"\\\"\\\"Unit cover for the LE-1905 authorization-report fixes that live in OSS.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException, status\\nfrom langflow.services.authorization import audit as audit_module\\nfrom langflow.services.authorization.fetch import deny_to_404, deny_to_404_unless_readable\\n\\n# --------------------------------------------------------------------------- #\\n# Finding 1: a permission check must not read as a performed action.\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.asyncio\\nasync def test_guard_decisions_are_tagged_as_decisions(monkeypatch):\\n    \\\"\\\"\\\"Every row a guard writes carries the decision marker.\\\"\\\"\\\"\\n    from langflow.services.authorization import guards\\n\\n    captured: list[dict] = []\\n\\n    async def _capture(**kwargs):\\n        captured.append(kwargs)\\n\\n    monkeypatch.setattr(audit_module, \\\"audit_decision\\\", _capture)\\n\\n    await guards._audit_guard_decision(\\n        user_id=uuid4(),\\n        action=\\\"share:create\\\",\\n        obj=\\\"share:*\\\",\\n        result=audit_module.AUDIT_OWNER_OVERRIDE,\\n        details={\\\"domain\\\": \\\"*\\\"},\\n    )\\n\\n    assert captured[0][\\\"details\\\"][\\\"event\\\"] == audit_module.AUDIT_EVENT_DECISION\\n    # The caller's own details survive alongside the marker.\\n    assert captured[0][\\\"details\\\"][\\\"domain\\\"] == \\\"*\\\"\\n\\n\\ndef test_decision_and_mutation_markers_are_distinct():\\n    assert audit_module.AUDIT_EVENT_DECISION != audit_module.AUDIT_EVENT_MUTATION\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Finding 8: a denial on a resource the caller can read is a 403, not a 404.\\n# --------------------------------------------------------------------------- #\\n\\n\\ndef _denied() -> HTTPException:\\n    return HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=\\\"Permission denied\\\")\\n\\n\\n@pytest.mark.asyncio\\nasync def test_readable_resource_keeps_the_403():\\n    async def _can_read() -> None:\\n        return None\\n\\n    resolved = await deny_to_404_unless_readable(\\n        _denied(), _can_read, denied_detail=\\\"You don't have permission to execute this flow.\\\"\\n    )\\n\\n    assert resolved.status_code == status.HTTP_403_FORBIDDEN\\n    assert resolved.detail == \\\"You don't have permission to execute this flow.\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_unreadable_resource_still_masks_as_404():\\n    async def _cannot_read() -> None:\\n        raise _denied()\\n\\n    resolved = await deny_to_404_unless_readable(\\n        _denied(), _cannot_read, denied_detail=\\\"never used\\\", not_found_detail=\\\"Flow not found\\\"\\n    )\\n\\n    assert resolved.status_code == status.HTTP_404_NOT_FOUND\\n    assert resolved.detail == \\\"Flow not found\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_service_failure_during_the_read_check_is_not_a_404():\\n    \\\"\\\"\\\"A 503 from the plugin means \\\"cannot decide\\\", not \\\"does not exist\\\".\\n\\n    Collapsing it to 404 would hide an authorization-service outage behind a\\n    routine-looking response and send the caller to check an id that is fine.\\n    \\\"\\\"\\\"\\n    unavailable = HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=\\\"authz plugin down\\\")\\n\\n    async def _read_check_fails() -> None:\\n        raise unavailable\\n\\n    resolved = await deny_to_404_unless_readable(\\n        _denied(), _read_check_fails, denied_detail=\\\"never used\\\", not_found_detail=\\\"Flow not found\\\"\\n    )\\n\\n    assert resolved is unavailable\\n    assert resolved.status_code == status.HTTP_503_SERVICE_UNAVAILABLE\\n\\n\\n@pytest.mark.asyncio\\nasync def test_non_403_is_surfaced_unchanged():\\n    \\\"\\\"\\\"A 503 from the plugin must never be relabelled as a permission answer.\\\"\\\"\\\"\\n    upstream = HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=\\\"plugin down\\\")\\n\\n    async def _unreachable() -> None:  # pragma: no cover - must not be called\\n        pytest.fail(\\\"read check ran for a non-403\\\")\\n\\n    resolved = await deny_to_404_unless_readable(upstream, _unreachable, denied_detail=\\\"x\\\")\\n\\n    assert resolved is upstream\\n    assert deny_to_404(upstream).status_code == status.HTTP_503_SERVICE_UNAVAILABLE\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Finding 11: owner override covers creating a flow in a project you own.\\n# --------------------------------------------------------------------------- #\\n\\n\\ndef test_flow_spec_inherits_ownership_from_the_destination_project():\\n    from langflow.services.authorization.guards import _RESOURCE_SPECS\\n\\n    assert _RESOURCE_SPECS[\\\"flow\\\"].create_container_owner_kw == \\\"folder_user_id\\\"\\n    # The flow's own owner kwarg still must not enable the override on create:\\n    # it is the caller-supplied field and would let anyone assert ownership.\\n    assert _RESOURCE_SPECS[\\\"flow\\\"].owner_override_on_create is False\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_in_owned_project_takes_the_owner_override(monkeypatch):\\n    \\\"\\\"\\\"The plugin is never consulted: ownership is checked before any policy rule.\\\"\\\"\\\"\\n    from langflow.services.authorization import guards\\n\\n    user_id = uuid4()\\n    project_id = uuid4()\\n    results: list[str] = []\\n\\n    async def _capture(**kwargs):\\n        results.append(kwargs[\\\"result\\\"])\\n\\n    async def _never(*_args, **_kwargs) -> None:  # pragma: no cover - must not be called\\n        pytest.fail(\\\"enforce() ran despite owner override\\\")\\n\\n    monkeypatch.setattr(audit_module, \\\"audit_decision\\\", _capture)\\n    monkeypatch.setattr(guards, \\\"ensure_permission\\\", _never)\\n    monkeypatch.setattr(guards, \\\"should_apply_owner_override\\\", lambda: _true())\\n\\n    class _User:\\n        id = user_id\\n\\n    await guards.ensure_flow_permission(\\n        _User(), \\\"create\\\", workspace_id=None, folder_id=project_id, folder_user_id=user_id\\n    )\\n\\n    assert results == [audit_module.AUDIT_OWNER_OVERRIDE]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_in_someone_elses_project_still_reaches_the_policy(monkeypatch):\\n    from langflow.services.authorization import guards\\n\\n    reached: list[str] = []\\n\\n    async def _record(_user, **kwargs):\\n        reached.append(kwargs[\\\"act\\\"])\\n\\n    monkeypatch.setattr(guards, \\\"ensure_permission\\\", _record)\\n\\n    class _User:\\n        id = uuid4()\\n\\n    await guards.ensure_flow_permission(_User(), \\\"create\\\", workspace_id=None, folder_id=uuid4(), folder_user_id=uuid4())\\n\\n    assert reached == [\\\"create\\\"]\\n\\n\\nasync def _true() -> bool:\\n    return True\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Round 2, finding 1: a capability probe is not an action, so it is not audited.\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.asyncio\\nasync def test_capability_probe_writes_no_decision_row(monkeypatch):\\n    \\\"\\\"\\\"The UI asking whether to offer a control must not log ``share:create``.\\\"\\\"\\\"\\n    from langflow.services.authorization import capability_probe, guards\\n\\n    captured: list[dict] = []\\n\\n    async def _capture(**kwargs):\\n        captured.append(kwargs)\\n\\n    monkeypatch.setattr(audit_module, \\\"audit_decision\\\", _capture)\\n\\n    with capability_probe():\\n        await guards._audit_guard_decision(\\n            user_id=uuid4(),\\n            action=\\\"share:create\\\",\\n            obj=\\\"share:*\\\",\\n            result=audit_module.AUDIT_OWNER_OVERRIDE,\\n        )\\n\\n    assert captured == []\\n\\n\\n@pytest.mark.asyncio\\nasync def test_probe_suppression_does_not_leak_past_the_scope(monkeypatch):\\n    \\\"\\\"\\\"A real attempt after a probe is audited as usual.\\\"\\\"\\\"\\n    from langflow.services.authorization import capability_probe, guards\\n\\n    captured: list[dict] = []\\n\\n    async def _capture(**kwargs):\\n        captured.append(kwargs)\\n\\n    monkeypatch.setattr(audit_module, \\\"audit_decision\\\", _capture)\\n\\n    with capability_probe():\\n        await guards._audit_guard_decision(\\n            user_id=uuid4(),\\n            action=\\\"share:create\\\",\\n            obj=\\\"share:*\\\",\\n            result=audit_module.AUDIT_ALLOW,\\n        )\\n    await guards._audit_guard_decision(\\n        user_id=uuid4(),\\n        action=\\\"share:create\\\",\\n        obj=\\\"share:abc\\\",\\n        result=audit_module.AUDIT_DENY,\\n    )\\n\\n    assert len(captured) == 1\\n    assert captured[0][\\\"result\\\"] == audit_module.AUDIT_DENY\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Round 2, finding 3: the Playground posts the canvas, so a non-owner who holds\\n# ``flow:execute`` must still run \u2014 the stored graph, not their override.\\n# --------------------------------------------------------------------------- #\\n\\n\\nclass _Flow:\\n    def __init__(self, owner_id):\\n        self.id = uuid4()\\n        self.user_id = owner_id\\n        self.workspace_id = None\\n        self.folder_id = None\\n\\n\\nclass _User:\\n    def __init__(self):\\n        self.id = uuid4()\\n        self.is_superuser = False\\n\\n\\n@pytest.fixture\\ndef _reset_override_context():\\n    from langflow.services.authorization import flow_data_override\\n\\n    token = flow_data_override._flow_data_override_allowed.set(False)\\n    yield\\n    flow_data_override._flow_data_override_allowed.reset(token)\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.usefixtures(\\\"_reset_override_context\\\")\\nasync def test_owner_override_is_resolved_without_consulting_policy(monkeypatch):\\n    \\\"\\\"\\\"An owner is decided by ownership alone; the policy plugin is never consulted.\\\"\\\"\\\"\\n    from langflow.services.authorization import flow_data_override\\n\\n    called = False\\n\\n    async def _never(*_args, **_kwargs):\\n        nonlocal called\\n        called = True\\n\\n    monkeypatch.setattr(flow_data_override, \\\"ensure_flow_permission\\\", _never)\\n\\n    user = _User()\\n    flow = _Flow(owner_id=user.id)\\n\\n    assert await flow_data_override.resolve_flow_data_override(user, flow) is True\\n    assert called is False\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.usefixtures(\\\"_reset_override_context\\\")\\nasync def test_write_holder_may_override_someone_elses_flow(monkeypatch):\\n    \\\"\\\"\\\"``flow:write`` already allows persisting that graph, so running it grants nothing new.\\\"\\\"\\\"\\n    from langflow.services.authorization import flow_data_override\\n\\n    async def _allow(*_args, **_kwargs):\\n        return None\\n\\n    monkeypatch.setattr(flow_data_override, \\\"ensure_flow_permission\\\", _allow)\\n\\n    assert await flow_data_override.resolve_flow_data_override(_User(), _Flow(owner_id=uuid4())) is True\\n    assert flow_data_override.flow_data_override_allowed() is True\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.usefixtures(\\\"_reset_override_context\\\")\\nasync def test_execute_only_caller_may_not_override(monkeypatch):\\n    \\\"\\\"\\\"Holding execute but not write leaves the stored definition in charge.\\\"\\\"\\\"\\n    from langflow.services.authorization import flow_data_override\\n\\n    async def _deny(*_args, **_kwargs):\\n        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=\\\"nope\\\")\\n\\n    monkeypatch.setattr(flow_data_override, \\\"ensure_flow_permission\\\", _deny)\\n\\n    assert await flow_data_override.resolve_flow_data_override(_User(), _Flow(owner_id=uuid4())) is False\\n    assert flow_data_override.flow_data_override_allowed() is False\\n\\n\\n@pytest.mark.usefixtures(\\\"_reset_override_context\\\")\\ndef test_execute_only_run_keeps_going_with_the_stored_graph():\\n    \\\"\\\"\\\"The regression itself: this used to be a 404 that said the flow does not exist.\\\"\\\"\\\"\\n    from langflow.api.v2.workflow_validation import _apply_flow_data_override_policy\\n    from lfx.workflow.converters import ParsedWorkflowRun\\n\\n    user = _User()\\n    flow = _Flow(owner_id=uuid4())\\n    parsed = ParsedWorkflowRun(\\n        flow_id=str(flow.id),\\n        data={\\\"nodes\\\": [{\\\"id\\\": \\\"injected\\\"}], \\\"edges\\\": []},\\n        tweaks={\\\"Component\\\": {\\\"model_name\\\": \\\"attacker-chosen\\\"}},\\n    )\\n\\n    result = _apply_flow_data_override_policy(parsed, flow, user)\\n\\n    assert result.data is None\\n    assert result.tweaks == {}\\n    # Everything the caller is entitled to send survives.\\n    assert result.flow_id == str(flow.id)\\n\\n\\n@pytest.mark.usefixtures(\\\"_reset_override_context\\\")\\ndef test_owner_keeps_their_unsaved_canvas():\\n    \\\"\\\"\\\"The owner's debugging workflow is untouched.\\\"\\\"\\\"\\n    from langflow.api.v2.workflow_validation import _apply_flow_data_override_policy\\n    from lfx.workflow.converters import ParsedWorkflowRun\\n\\n    user = _User()\\n    flow = _Flow(owner_id=user.id)\\n    data = {\\\"nodes\\\": [{\\\"id\\\": \\\"mine\\\"}], \\\"edges\\\": []}\\n    parsed = ParsedWorkflowRun(flow_id=str(flow.id), data=data)\\n\\n    assert _apply_flow_data_override_policy(parsed, flow, user).data == data\\n\\n\\n@pytest.mark.usefixtures(\\\"_reset_override_context\\\")\\ndef test_a_run_with_no_override_is_untouched():\\n    \\\"\\\"\\\"A plain run carries no override, so there is nothing to strip.\\\"\\\"\\\"\\n    from langflow.api.v2.workflow_validation import _apply_flow_data_override_policy\\n    from lfx.workflow.converters import ParsedWorkflowRun\\n\\n    parsed = ParsedWorkflowRun(flow_id=\\\"abc\\\", input_value=\\\"hello\\\")\\n\\n    assert _apply_flow_data_override_policy(parsed, _Flow(owner_id=uuid4()), _User()) is parsed\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Round 2, finding 1: every row is classifiable, so a reader can ask for the\\n# actions people performed without losing rows written before classification.\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.asyncio\\nasync def test_event_class_filter_selects_and_never_hides_untagged_rows():\\n    \\\"\\\"\\\"The ``details.event`` filter the audit route applies, against a real database.\\\"\\\"\\\"\\n    import sqlalchemy as sa\\n    from langflow.services.database.models.auth.authz import AuthzAuditLog\\n    from sqlalchemy.ext.asyncio import create_async_engine\\n    from sqlmodel import col, or_, select\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    engine = create_async_engine(\\\"sqlite+aiosqlite://\\\")\\n    async with engine.begin() as conn:\\n        await conn.run_sync(lambda c: AuthzAuditLog.metadata.create_all(c, tables=[AuthzAuditLog.__table__]))\\n\\n    seeded = (\\n        (\\\"share:create\\\", {\\\"event\\\": audit_module.AUDIT_EVENT_DECISION}),\\n        (\\\"share:create\\\", {\\\"event\\\": audit_module.AUDIT_EVENT_MUTATION}),\\n        (\\\"audit:read\\\", {\\\"event\\\": audit_module.AUDIT_EVENT_ACCESS}),\\n        (\\\"flow:read\\\", None),\\n        (\\\"flow:write\\\", {\\\"domain\\\": \\\"*\\\"}),\\n    )\\n    async with AsyncSession(engine) as session:\\n        for action, details in seeded:\\n            session.add(\\n                AuthzAuditLog(\\n                    id=uuid4(),\\n                    timestamp=datetime.now(timezone.utc),\\n                    action=action,\\n                    resource_type=action.split(\\\":\\\")[0],\\n                    result=audit_module.AUDIT_ALLOW,\\n                    details=details,\\n                )\\n            )\\n        await session.commit()\\n\\n        event_class = col(AuthzAuditLog.details)[\\\"event\\\"].as_string()\\n\\n        async def actions(stmt):\\n            return sorted(row.action for row in (await session.exec(stmt)).all())\\n\\n        # Asking for what happened returns only the mutation.\\n        assert await actions(select(AuthzAuditLog).where(event_class.in_([audit_module.AUDIT_EVENT_MUTATION]))) == [\\n            \\\"share:create\\\"\\n        ]\\n\\n        # Hiding permission checks drops the check and keeps every other row,\\n        # including the two written before classification existed.\\n        hide_checks = select(AuthzAuditLog).where(\\n            or_(event_class.not_in([audit_module.AUDIT_EVENT_DECISION]), event_class.is_(None)),\\n            col(AuthzAuditLog.action).not_in([\\\"audit:read\\\"]),\\n        )\\n        assert await actions(hide_checks) == [\\\"flow:read\\\", \\\"flow:write\\\", \\\"share:create\\\"]\\n\\n        # The count the route reports comes off the same filtered subquery, so\\n        # pagination cannot disagree with the rows.\\n        total = int((await session.exec(select(sa.func.count()).select_from(hide_checks.subquery()))).first() or 0)\\n        assert total == 3\\n\\n    await engine.dispose()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_listing_null_owner_prefilter.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c49baca39cce9f74be12a762cf4240774d40797398e8db65a938c9f19c1da0c0\",\"content\":\"\\\"\\\"\\\"Regression: the DB-layer authz prefilter must apply the same null-owner semantics as the fallback.\\n\\nThe list endpoints (``read_projects`` / ``read_flows``) build two query paths:\\n\\n* **prefilter active** (a registered plugin returned a concrete visible-id set):\\n  ``restrict_to_owned_or_visible(select(Model), owner_clause=<owned-only>, visible_ids=...)``\\n* **fallback** (OSS pass-through declines): owner-scoped query + ``filter_visible_resources``\\n\\nA *null-owner* row \u2014 a legacy/manually-seeded project, or any flow under\\nAUTO_LOGIN \u2014 must be policy-checked on BOTH paths. The fallback already does\\nthis: ``filter_visible_resources``'s ``owner_extractor`` returns ``None`` for a\\nnull owner, which never equals a real user id, so the row is routed through\\n``batch_enforce``. The prefilter path used to diverge by folding a\\n``user_id IS NULL`` term into the owner clause, so every null-owner row came back\\nunconditionally (the reviewer's compiled\\n``... OR folder.user_id = :uid OR folder.user_id IS NULL``).\\n\\nThese tests install an authorization double whose ``list_visible_resource_ids``\\nreturns a concrete list (so the endpoints take the prefilter branch \u2014 the path\\n:class:`PolicyTestAuthorizationService` does not exercise, since it leaves the\\nbase ``None``) and assert a null-owner row appears ONLY when the plugin lists its\\nid \u2014 identical to what the fallback would decide.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport gzip\\nimport json\\nfrom typing import TYPE_CHECKING, Any\\nfrom unittest.mock import patch\\nfrom uuid import UUID, uuid4\\n\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_auth_service, get_settings_service, session_scope\\nfrom lfx.services.authorization.base import BaseAuthorizationService, ResourceVisibilityScope\\nfrom sqlalchemy.dialects.postgresql.asyncpg import PGDialect_asyncpg\\nfrom sqlalchemy.sql.sqltypes import NullType\\nfrom sqlmodel import select\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Iterator, Sequence\\n\\n    from lfx.services.settings.service import SettingsService\\n\\n_PASSWORD = \\\"testpassword\\\"  # noqa: S105 \u2014 test-only credential  # pragma: allowlist secret\\n\\n\\nclass _PrefilterAuthorizationService(BaseAuthorizationService):\\n    \\\"\\\"\\\"Authz double that returns a fixed visible-id set per resource type.\\n\\n    This is what forces the list endpoints onto the DB-layer prefilter branch:\\n    ``list_visible_resource_ids`` yields a concrete list instead of the base\\n    ``None``. ``enforce`` / ``batch_enforce`` are allow-all because the prefilter\\n    path is authoritative and never calls them (asserting that invariant too).\\n    \\\"\\\"\\\"\\n\\n    SUPPORTS_CROSS_USER_FETCH = True\\n\\n    def __init__(\\n        self,\\n        settings_service: SettingsService,\\n        visible_by_type: dict[str, list[UUID]],\\n        scope_by_type: dict[str, ResourceVisibilityScope] | None = None,\\n    ) -> None:\\n        super().__init__()\\n        self.settings_service = settings_service\\n        self._visible_by_type = visible_by_type\\n        self._scope_by_type = scope_by_type or {}\\n        self.batch_calls = 0\\n        self.set_ready()\\n\\n    async def is_enabled(self) -> bool:\\n        return bool(self.settings_service.auth_settings.AUTHZ_ENABLED)\\n\\n    async def enforce(self, **_kwargs: Any) -> bool:\\n        return True\\n\\n    async def batch_enforce(self, *, requests: Sequence[tuple[str, str]], **_kwargs: Any) -> list[bool]:\\n        # Should never run on the prefilter path; recorded so a test can assert it.\\n        self.batch_calls += 1\\n        return [True] * len(list(requests))\\n\\n    async def list_visible_resource_ids(self, *, resource_type: str, **_kwargs: Any) -> list[UUID] | None:\\n        return list(self._visible_by_type.get(resource_type, []))\\n\\n    async def get_resource_visibility(self, *, resource_type: str, **kwargs: Any) -> ResourceVisibilityScope | None:\\n        if resource_type in self._scope_by_type:\\n            return self._scope_by_type[resource_type]\\n        return await super().get_resource_visibility(resource_type=resource_type, **kwargs)\\n\\n\\n@contextlib.contextmanager\\ndef _install_prefilter_authz(\\n    settings_service: SettingsService,\\n    visible_by_type: dict[str, list[UUID]],\\n    *,\\n    auto_login: bool = False,\\n    scope_by_type: dict[str, ResourceVisibilityScope] | None = None,\\n) -> Iterator[_PrefilterAuthorizationService]:\\n    \\\"\\\"\\\"Install the prefilter double + enable AUTHZ (and optionally AUTO_LOGIN); restore on exit.\\\"\\\"\\\"\\n    from langflow.services.schema import ServiceType\\n    from lfx.services.manager import get_service_manager\\n\\n    auth_settings = settings_service.auth_settings\\n    saved_enabled = auth_settings.AUTHZ_ENABLED\\n    saved_bypass = auth_settings.AUTHZ_SUPERUSER_BYPASS\\n    saved_auto_login = auth_settings.AUTO_LOGIN\\n\\n    service_manager = get_service_manager()\\n    previous_service = service_manager.services.get(ServiceType.AUTHORIZATION_SERVICE)\\n\\n    auth_settings.AUTHZ_ENABLED = True\\n    auth_settings.AUTHZ_SUPERUSER_BYPASS = False\\n    auth_settings.AUTO_LOGIN = auto_login\\n    double = _PrefilterAuthorizationService(settings_service, visible_by_type, scope_by_type)\\n    service_manager.services[ServiceType.AUTHORIZATION_SERVICE] = double\\n    try:\\n        yield double\\n    finally:\\n        if previous_service is not None:\\n            service_manager.services[ServiceType.AUTHORIZATION_SERVICE] = previous_service\\n        else:\\n            service_manager.services.pop(ServiceType.AUTHORIZATION_SERVICE, None)\\n        auth_settings.AUTHZ_ENABLED = saved_enabled\\n        auth_settings.AUTHZ_SUPERUSER_BYPASS = saved_bypass\\n        auth_settings.AUTO_LOGIN = saved_auto_login\\n\\n\\nasync def _make_user(username: str) -> UUID:\\n    async with session_scope() as session:\\n        user = User(username=username, password=get_auth_service().get_password_hash(_PASSWORD), is_active=True)\\n        session.add(user)\\n        await session.flush()\\n        user_id = user.id\\n        await session.commit()\\n    return user_id\\n\\n\\nasync def _login(client, username: str) -> dict[str, str]:\\n    response = await client.post(\\\"api/v1/login\\\", data={\\\"username\\\": username, \\\"password\\\": _PASSWORD})\\n    assert response.status_code == 200, f\\\"login failed for {username}: {response.text}\\\"\\n    return {\\\"Authorization\\\": f\\\"Bearer {response.json()['access_token']}\\\"}\\n\\n\\nasync def _make_folder(name: str, *, user_id: UUID | None, workspace_id: UUID | None = None) -> UUID:\\n    async with session_scope() as session:\\n        folder = Folder(name=name, user_id=user_id, workspace_id=workspace_id)\\n        session.add(folder)\\n        await session.flush()\\n        folder_id = folder.id\\n        await session.commit()\\n    return folder_id\\n\\n\\nasync def _make_flow(\\n    name: str,\\n    *,\\n    user_id: UUID | None,\\n    folder_id: UUID | None = None,\\n    workspace_id: UUID | None = None,\\n) -> UUID:\\n    async with session_scope() as session:\\n        flow = Flow(\\n            name=name,\\n            user_id=user_id,\\n            folder_id=folder_id,\\n            workspace_id=workspace_id,\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        )\\n        session.add(flow)\\n        await session.flush()\\n        flow_id = flow.id\\n        await session.commit()\\n    return flow_id\\n\\n\\ndef _project_ids(response) -> set[UUID]:\\n    assert response.status_code == 200, response.text\\n    return {UUID(p[\\\"id\\\"]) for p in response.json()}\\n\\n\\ndef _flow_ids(response) -> set[UUID]:\\n    assert response.status_code == 200, response.text\\n    body = response.content\\n    # ``read_flows`` (get_all) gzips its body; httpx usually decodes it, but decode\\n    # defensively in case the transport leaves it compressed.\\n    if response.headers.get(\\\"content-encoding\\\") == \\\"gzip\\\":\\n        with contextlib.suppress(OSError):\\n            body = gzip.decompress(body)\\n    return {UUID(f[\\\"id\\\"]) for f in json.loads(body)}\\n\\n\\ndef _project_flow_ids(response, *, paginated: bool) -> set[UUID]:\\n    assert response.status_code == 200, response.text\\n    body = response.json()\\n    rows = body[\\\"flows\\\"][\\\"items\\\"] if paginated else body[\\\"flows\\\"]\\n    return {UUID(flow[\\\"id\\\"]) for flow in rows}\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Projects: a non-starter null-owner project must not leak through the prefilter.\\n# --------------------------------------------------------------------------- #\\n\\n\\nasync def test_projects_prefilter_excludes_unlisted_null_owner_project(client):\\n    settings = get_settings_service()\\n    username = f\\\"owner_{uuid4().hex}\\\"\\n    owner_id = await _make_user(username)\\n    other_id = await _make_user(f\\\"other_{uuid4().hex}\\\")\\n    headers = await _login(client, username)\\n\\n    owned_id = await _make_folder(f\\\"owned_{uuid4().hex}\\\", user_id=owner_id)\\n    foreign_id = await _make_folder(f\\\"foreign_{uuid4().hex}\\\", user_id=other_id)\\n    # A legacy / manually-seeded null-owner project (NOT the starter folder, so the\\n    # name filter in read_projects does not mask the bug being guarded here).\\n    orphan_id = await _make_folder(f\\\"orphan_{uuid4().hex}\\\", user_id=None)\\n\\n    # Plugin reports only the foreign project visible \u2014 orphan is NOT listed.\\n    with _install_prefilter_authz(settings, {\\\"project\\\": [foreign_id]}) as authz:\\n        ids = _project_ids(await client.get(\\\"api/v1/projects/\\\", headers=headers))\\n\\n    # Owner-override keeps the caller's own project; the plugin widens to the\\n    # foreign one; the null-owner project is gone (it used to leak via IS NULL).\\n    assert owned_id in ids\\n    assert foreign_id in ids\\n    assert orphan_id not in ids\\n    # Prefilter path is authoritative: no per-row in-memory enforce ran.\\n    assert authz.batch_calls == 0\\n\\n\\nasync def test_projects_prefilter_includes_null_owner_project_when_plugin_lists_it(client):\\n    settings = get_settings_service()\\n    username = f\\\"owner_{uuid4().hex}\\\"\\n    owner_id = await _make_user(username)\\n    headers = await _login(client, username)\\n\\n    owned_id = await _make_folder(f\\\"owned_{uuid4().hex}\\\", user_id=owner_id)\\n    orphan_id = await _make_folder(f\\\"orphan_{uuid4().hex}\\\", user_id=None)\\n\\n    # Now the plugin explicitly grants the null-owner project \u2014 it must appear,\\n    # proving it is reachable by policy, not unreachable by the fix.\\n    with _install_prefilter_authz(settings, {\\\"project\\\": [orphan_id]}):\\n        ids = _project_ids(await client.get(\\\"api/v1/projects/\\\", headers=headers))\\n\\n    assert owned_id in ids\\n    assert orphan_id in ids\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Flows under AUTO_LOGIN: the null-owner term is AUTO_LOGIN-only, and AUTHZ_ENABLED\\n# is an independent flag, so both can be set \u2014 the prefilter must still policy-check\\n# null-owner flows rather than blanket-including them.\\n# --------------------------------------------------------------------------- #\\n\\n\\nasync def test_flows_prefilter_excludes_unlisted_null_owner_flow_under_auto_login(client):\\n    settings = get_settings_service()\\n    username = f\\\"owner_{uuid4().hex}\\\"\\n    owner_id = await _make_user(username)\\n    other_id = await _make_user(f\\\"other_{uuid4().hex}\\\")\\n    # Log in BEFORE flipping AUTO_LOGIN so current_user resolves from the token\\n    # (get_current_user short-circuits on a present token regardless of AUTO_LOGIN).\\n    headers = await _login(client, username)\\n\\n    owned_id = await _make_flow(f\\\"owned_{uuid4().hex}\\\", user_id=owner_id)\\n    foreign_id = await _make_flow(f\\\"foreign_{uuid4().hex}\\\", user_id=other_id)\\n    null_id = await _make_flow(f\\\"orphan_{uuid4().hex}\\\", user_id=None)\\n\\n    with _install_prefilter_authz(settings, {\\\"flow\\\": [foreign_id]}, auto_login=True) as authz:\\n        ids = _flow_ids(await client.get(\\\"api/v1/flows/\\\", headers=headers))\\n\\n    assert owned_id in ids\\n    assert foreign_id in ids\\n    # Under AUTO_LOGIN the owner clause used to include ``Flow.user_id IS NULL``,\\n    # leaking this row through the prefilter union; the fix keeps it out.\\n    assert null_id not in ids\\n    assert authz.batch_calls == 0\\n\\n\\nasync def test_flows_prefilter_includes_null_owner_flow_when_plugin_lists_it(client):\\n    settings = get_settings_service()\\n    username = f\\\"owner_{uuid4().hex}\\\"\\n    owner_id = await _make_user(username)\\n    headers = await _login(client, username)\\n\\n    owned_id = await _make_flow(f\\\"owned_{uuid4().hex}\\\", user_id=owner_id)\\n    null_id = await _make_flow(f\\\"orphan_{uuid4().hex}\\\", user_id=None)\\n\\n    with _install_prefilter_authz(settings, {\\\"flow\\\": [null_id]}, auto_login=True):\\n        ids = _flow_ids(await client.get(\\\"api/v1/flows/\\\", headers=headers))\\n\\n    assert owned_id in ids\\n    assert null_id in ids\\n\\n\\nasync def test_flow_workspace_prefilter_uses_project_workspace_not_denormalized_flow_value(client):\\n    settings = get_settings_service()\\n    username = f\\\"owner_{uuid4().hex}\\\"\\n    await _make_user(username)\\n    other_id = await _make_user(f\\\"other_{uuid4().hex}\\\")\\n    headers = await _login(client, username)\\n    visible_workspace = uuid4()\\n    hidden_workspace = uuid4()\\n    hidden_project = await _make_folder(\\n        f\\\"hidden_project_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        workspace_id=hidden_workspace,\\n    )\\n    visible_project = await _make_folder(\\n        f\\\"visible_project_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        workspace_id=visible_workspace,\\n    )\\n    spoofed_visible = await _make_flow(\\n        f\\\"spoofed_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        folder_id=hidden_project,\\n        workspace_id=visible_workspace,\\n    )\\n    canonical_visible = await _make_flow(\\n        f\\\"canonical_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        folder_id=visible_project,\\n        workspace_id=hidden_workspace,\\n    )\\n\\n    scope = ResourceVisibilityScope(workspace_ids=(visible_workspace,))\\n    with _install_prefilter_authz(settings, {}, scope_by_type={\\\"flow\\\": scope}):\\n        ids = _flow_ids(await client.get(\\\"api/v1/flows/\\\", headers=headers))\\n\\n    assert canonical_visible in ids\\n    assert spoofed_visible not in ids\\n\\n\\nasync def test_shared_project_flow_listing_uses_project_workspace_for_both_response_shapes(client):\\n    settings = get_settings_service()\\n    username = f\\\"owner_{uuid4().hex}\\\"\\n    await _make_user(username)\\n    other_id = await _make_user(f\\\"other_{uuid4().hex}\\\")\\n    headers = await _login(client, username)\\n    visible_workspace = uuid4()\\n    hidden_workspace = uuid4()\\n    hidden_project = await _make_folder(\\n        f\\\"hidden_project_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        workspace_id=hidden_workspace,\\n    )\\n    visible_project = await _make_folder(\\n        f\\\"visible_project_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        workspace_id=visible_workspace,\\n    )\\n    spoofed_visible = await _make_flow(\\n        f\\\"spoofed_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        folder_id=hidden_project,\\n        workspace_id=visible_workspace,\\n    )\\n    canonical_visible = await _make_flow(\\n        f\\\"canonical_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        folder_id=visible_project,\\n        workspace_id=hidden_workspace,\\n    )\\n    scope = ResourceVisibilityScope(workspace_ids=(visible_workspace,))\\n\\n    with _install_prefilter_authz(settings, {}, scope_by_type={\\\"flow\\\": scope}):\\n        for paginated, params in ((False, {}), (True, {\\\"page\\\": 1, \\\"size\\\": 50})):\\n            hidden_ids = _project_flow_ids(\\n                await client.get(f\\\"api/v1/projects/{hidden_project}\\\", headers=headers, params=params),\\n                paginated=paginated,\\n            )\\n            visible_ids = _project_flow_ids(\\n                await client.get(f\\\"api/v1/projects/{visible_project}\\\", headers=headers, params=params),\\n                paginated=paginated,\\n            )\\n            assert spoofed_visible not in hidden_ids\\n            assert canonical_visible in visible_ids\\n\\n\\nasync def test_shared_unassigned_project_pagination_compiles_safely_for_asyncpg(client):\\n    from langflow.api.v1 import projects as projects_module\\n\\n    settings = get_settings_service()\\n    username = f\\\"owner_{uuid4().hex}\\\"\\n    await _make_user(username)\\n    other_id = await _make_user(f\\\"other_{uuid4().hex}\\\")\\n    headers = await _login(client, username)\\n    project_id = await _make_folder(\\n        f\\\"unassigned_project_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        workspace_id=None,\\n    )\\n    await _make_flow(\\n        f\\\"visible_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        folder_id=project_id,\\n        workspace_id=None,\\n    )\\n    scope = ResourceVisibilityScope(include_unassigned_workspace=True)\\n    compiled_statements = []\\n    original_apaginate = projects_module.apaginate\\n\\n    async def capture_statement(*args, **kwargs):\\n        statement = args[1]\\n        compiled_statements.append(statement.compile(dialect=PGDialect_asyncpg()))\\n        return await original_apaginate(*args, **kwargs)\\n\\n    with (\\n        _install_prefilter_authz(settings, {}, scope_by_type={\\\"flow\\\": scope}),\\n        patch.object(projects_module, \\\"apaginate\\\", new=capture_statement),\\n    ):\\n        response = await client.get(\\n            f\\\"api/v1/projects/{project_id}\\\",\\n            headers=headers,\\n            params={\\\"page\\\": 1, \\\"size\\\": 50},\\n        )\\n\\n    assert response.status_code == 200, response.text\\n    assert len(compiled_statements) == 1\\n    compiled = compiled_statements[0]\\n    assert \\\"NULL IS NULL\\\" in str(compiled)\\n    assert not any(isinstance(bind.type, NullType) for bind in compiled.binds.values())\\n\\n\\nasync def test_shared_project_get_does_not_delete_flows_hidden_from_response(client):\\n    settings = get_settings_service()\\n    username = f\\\"owner_{uuid4().hex}\\\"\\n    await _make_user(username)\\n    other_id = await _make_user(f\\\"other_{uuid4().hex}\\\")\\n    headers = await _login(client, username)\\n    project_id = await _make_folder(\\n        f\\\"shared_project_{uuid4().hex}\\\",\\n        user_id=other_id,\\n        workspace_id=uuid4(),\\n    )\\n    visible_id = await _make_flow(f\\\"visible_{uuid4().hex}\\\", user_id=other_id, folder_id=project_id)\\n    hidden_id = await _make_flow(f\\\"hidden_{uuid4().hex}\\\", user_id=other_id, folder_id=project_id)\\n    scope = ResourceVisibilityScope(resource_ids=(visible_id,))\\n\\n    with _install_prefilter_authz(settings, {}, scope_by_type={\\\"flow\\\": scope}):\\n        response_ids = _project_flow_ids(\\n            await client.get(f\\\"api/v1/projects/{project_id}\\\", headers=headers),\\n            paginated=False,\\n        )\\n\\n    assert response_ids == {visible_id}\\n    async with session_scope() as session:\\n        persisted = set((await session.exec(select(Flow.id).where(Flow.folder_id == project_id))).all())\\n    assert persisted == {visible_id, hidden_id}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_public_access_contract.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7901b1f3ea384fb0e71969bbedd0179971211468ac6b555f4e6dd0f931e3775f\",\"content\":\"\\\"\\\"\\\"Anonymous direct-link authorization contract (LE-1906).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\n\\n\\ndef _contract_module():\\n    return importlib.import_module(\\\"langflow.services.authorization.public_access\\\")\\n\\n\\ndef test_public_grants_only_confer_read_and_execute_actions():\\n    \\\"\\\"\\\"Even an admin-level PUBLIC row cannot grant anonymous mutation or deployment rights.\\\"\\\"\\\"\\n    module = _contract_module()\\n    action = module.PublicResourceAction\\n\\n    assert module.public_grant_allows(\\\"admin\\\", action.READ)\\n    assert module.public_grant_allows(\\\"admin\\\", action.EXECUTE)\\n    for forbidden in (action.WRITE, action.CREATE, action.DELETE, action.DEPLOY, action.ADMIN):\\n        assert not module.public_grant_allows(\\\"admin\\\", forbidden)\\n\\n\\ndef test_read_share_does_not_confer_execute_but_execute_share_includes_read():\\n    module = _contract_module()\\n    action = module.PublicResourceAction\\n\\n    assert module.public_grant_allows(\\\"read\\\", action.READ)\\n    assert not module.public_grant_allows(\\\"read\\\", action.EXECUTE)\\n    assert module.public_grant_allows(\\\"execute\\\", action.READ)\\n    assert module.public_grant_allows(\\\"execute\\\", action.EXECUTE)\\n\\n\\ndef test_anonymous_execution_user_is_stable_and_non_privileged():\\n    \\\"\\\"\\\"The runtime principal is deterministic but is not an owner or a persisted user identity.\\\"\\\"\\\"\\n    module = _contract_module()\\n\\n    first = module.public_execution_user()\\n    second = module.public_execution_user()\\n    assert first.id == second.id == module.PUBLIC_ANONYMOUS_ACTOR_ID\\n    assert first.username == \\\"anonymous-public\\\"\\n    assert first.is_superuser is False\\n    assert first.store_api_key is None\\n\\n\\n@pytest.mark.anyio\\n@pytest.mark.parametrize(\\\"action_name\\\", [\\\"WRITE\\\", \\\"CREATE\\\", \\\"DELETE\\\", \\\"DEPLOY\\\", \\\"ADMIN\\\"])\\nasync def test_compatibility_grants_cannot_bypass_action_floor(action_name):\\n    \\\"\\\"\\\"Legacy flags never become an alternate path to anonymous mutations.\\\"\\\"\\\"\\n    module = _contract_module()\\n\\n    source = await module._resolve_grant(\\n        flow=object(),\\n        action=getattr(module.PublicResourceAction, action_name),\\n        session=None,\\n        compatibility_grant=module.PublicGrantSource.A2A_AUTH_NONE,\\n    )\\n\\n    assert source is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_a2a_compatibility_grant_allows_execute_when_no_public_share():\\n    module = _contract_module()\\n    result = SimpleNamespace(first=lambda: None)\\n    session = SimpleNamespace(exec=AsyncMock(return_value=result))\\n    flow = SimpleNamespace(id=uuid4(), access_type=object())\\n\\n    source = await module._resolve_grant(\\n        flow=flow,\\n        action=module.PublicResourceAction.EXECUTE,\\n        session=session,\\n        compatibility_grant=module.PublicGrantSource.A2A_AUTH_NONE,\\n    )\\n\\n    assert source is module.PublicGrantSource.A2A_AUTH_NONE\\n\\n\\ndef _session_with_public_share(permission_level: str | None):\\n    result = SimpleNamespace(first=lambda: permission_level)\\n    return SimpleNamespace(exec=AsyncMock(return_value=result))\\n\\n\\n@pytest.mark.anyio\\nasync def test_canonical_read_share_bounds_a_still_public_legacy_flow():\\n    \\\"\\\"\\\"A read-only PUBLIC share is authoritative; the legacy flag cannot widen it to execute.\\\"\\\"\\\"\\n    module = _contract_module()\\n    flow = SimpleNamespace(id=uuid4(), access_type=module.AccessTypeEnum.PUBLIC)\\n\\n    read_source = await module._resolve_grant(\\n        flow=flow,\\n        action=module.PublicResourceAction.READ,\\n        session=_session_with_public_share(\\\"read\\\"),\\n        compatibility_grant=None,\\n    )\\n    execute_source = await module._resolve_grant(\\n        flow=flow,\\n        action=module.PublicResourceAction.EXECUTE,\\n        session=_session_with_public_share(\\\"read\\\"),\\n        compatibility_grant=None,\\n    )\\n\\n    assert read_source is module.PublicGrantSource.AUTHZ_SHARE\\n    assert execute_source is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_canonical_read_share_also_bounds_the_a2a_compatibility_grant():\\n    module = _contract_module()\\n    flow = SimpleNamespace(id=uuid4(), access_type=object())\\n\\n    source = await module._resolve_grant(\\n        flow=flow,\\n        action=module.PublicResourceAction.EXECUTE,\\n        session=_session_with_public_share(\\\"read\\\"),\\n        compatibility_grant=module.PublicGrantSource.A2A_AUTH_NONE,\\n    )\\n\\n    assert source is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_deleting_the_share_falls_back_to_the_documented_legacy_grant():\\n    \\\"\\\"\\\"With no share row the legacy flag is still the compatibility grant it claims to be.\\\"\\\"\\\"\\n    module = _contract_module()\\n    flow = SimpleNamespace(id=uuid4(), access_type=module.AccessTypeEnum.PUBLIC)\\n\\n    source = await module._resolve_grant(\\n        flow=flow,\\n        action=module.PublicResourceAction.EXECUTE,\\n        session=_session_with_public_share(None),\\n        compatibility_grant=None,\\n    )\\n\\n    assert source is module.PublicGrantSource.LEGACY_ACCESS_TYPE\\n\\n\\n@pytest.mark.anyio\\n@pytest.mark.parametrize(\\n    (\\\"permission_level\\\", \\\"legacy_public\\\", \\\"expected\\\"),\\n    [\\n        (\\\"execute\\\", False, (True, True)),\\n        (\\\"read\\\", False, (True, False)),\\n        (\\\"read\\\", True, (True, False)),\\n        (None, True, (True, True)),\\n        (None, False, (False, False)),\\n    ],\\n)\\nasync def test_capabilities_report_the_same_decision_the_guard_would_make(permission_level, legacy_public, expected):\\n    \\\"\\\"\\\"The advisory capability set never disagrees with authorize_public_flow_access.\\\"\\\"\\\"\\n    module = _contract_module()\\n    access_type = module.AccessTypeEnum.PUBLIC if legacy_public else module.AccessTypeEnum.PRIVATE\\n    flow = SimpleNamespace(id=uuid4(), access_type=access_type, workspace_id=None, folder_id=None)\\n\\n    capabilities = await module.public_flow_capabilities(\\n        flow=flow,\\n        session=_session_with_public_share(permission_level),\\n    )\\n\\n    assert (capabilities.can_read, capabilities.can_execute) == expected\\n\\n\\n@pytest.mark.anyio\\nasync def test_capabilities_are_advisory_and_never_audited(monkeypatch):\\n    \\\"\\\"\\\"A capability probe is not an access attempt, so it must not emit audit rows.\\n\\n    Auditing it would write a DENY row on every page view of a read-only share\\n    and drown the real anonymous-denial signal operators watch for.\\n    \\\"\\\"\\\"\\n    module = _contract_module()\\n    flow = SimpleNamespace(id=uuid4(), access_type=module.AccessTypeEnum.PRIVATE, workspace_id=None, folder_id=None)\\n    audit = AsyncMock()\\n    monkeypatch.setattr(module, \\\"audit_decision\\\", audit)\\n\\n    capabilities = await module.public_flow_capabilities(\\n        flow=flow,\\n        session=_session_with_public_share(\\\"read\\\"),\\n    )\\n\\n    assert (capabilities.can_read, capabilities.can_execute) == (True, False)\\n    audit.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_capabilities_fail_closed_when_an_enabled_plugin_denies(monkeypatch):\\n    \\\"\\\"\\\"An enabled plugin bounds the hint too, so the UI cannot offer a run the guard would refuse.\\\"\\\"\\\"\\n    module = _contract_module()\\n    flow = SimpleNamespace(id=uuid4(), access_type=module.AccessTypeEnum.PUBLIC, workspace_id=None, folder_id=None)\\n    service = SimpleNamespace(\\n        supports_public_principals=AsyncMock(return_value=True),\\n        resolve_public_tenant=AsyncMock(return_value=\\\"tenant-a\\\"),\\n        enforce_public=AsyncMock(\\n            side_effect=lambda request, tenant: request.action is module.PublicResourceAction.READ  # noqa: ARG005\\n        ),\\n    )\\n    settings = SimpleNamespace(auth_settings=SimpleNamespace(AUTHZ_ENABLED=True))\\n    monkeypatch.setattr(module, \\\"get_settings_service\\\", lambda: settings)\\n    monkeypatch.setattr(module, \\\"get_authorization_service\\\", lambda: service)\\n\\n    capabilities = await module.public_flow_capabilities(\\n        flow=flow,\\n        session=_session_with_public_share(None),\\n    )\\n\\n    assert capabilities.can_read is True\\n    assert capabilities.can_execute is False\\n\\n\\n@pytest.mark.anyio\\n@pytest.mark.parametrize(\\n    \\\"plugin_result\\\",\\n    [\\\"allow\\\", \\\"unsupported\\\", \\\"missing_tenant\\\", \\\"deny\\\", \\\"error\\\", \\\"service_unavailable\\\"],\\n)\\nasync def test_enabled_authorization_plugin_controls_public_execution(monkeypatch, plugin_result):\\n    module = _contract_module()\\n    flow = SimpleNamespace(id=uuid4(), workspace_id=None, folder_id=None)\\n    service = SimpleNamespace(\\n        supports_public_principals=AsyncMock(return_value=plugin_result != \\\"unsupported\\\"),\\n        resolve_public_tenant=AsyncMock(return_value=None if plugin_result == \\\"missing_tenant\\\" else \\\"tenant-a\\\"),\\n        enforce_public=AsyncMock(return_value=plugin_result == \\\"allow\\\"),\\n    )\\n    if plugin_result == \\\"error\\\":\\n        service.supports_public_principals.side_effect = RuntimeError(\\\"plugin detail\\\")\\n\\n    monkeypatch.setattr(module, \\\"_resolve_grant\\\", AsyncMock(return_value=module.PublicGrantSource.AUTHZ_SHARE))\\n    settings = SimpleNamespace(auth_settings=SimpleNamespace(AUTHZ_ENABLED=True))\\n    monkeypatch.setattr(module, \\\"get_settings_service\\\", lambda: settings)\\n    if plugin_result == \\\"service_unavailable\\\":\\n        # A service that cannot even be constructed must deny like any other\\n        # policy failure, not escape the handler as an unhandled 500.\\n        def _unavailable():\\n            msg = \\\"authorization service unavailable\\\"\\n            raise RuntimeError(msg)\\n\\n        monkeypatch.setattr(module, \\\"get_authorization_service\\\", _unavailable)\\n    else:\\n        monkeypatch.setattr(module, \\\"get_authorization_service\\\", lambda: service)\\n    audit = AsyncMock()\\n    monkeypatch.setattr(module, \\\"audit_decision\\\", audit)\\n\\n    if plugin_result == \\\"allow\\\":\\n        principal = await module.authorize_public_flow_access(\\n            flow=flow,\\n            action=module.PublicResourceAction.EXECUTE,\\n        )\\n        assert principal.actor_type == \\\"anonymous_public\\\"\\n    else:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await module.authorize_public_flow_access(\\n                flow=flow,\\n                action=module.PublicResourceAction.EXECUTE,\\n            )\\n        assert exc_info.value.status_code == 404\\n        assert exc_info.value.detail == module.PUBLIC_FLOW_NOT_FOUND_DETAIL\\n\\n    audit.assert_awaited_once()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_rbac_enforcement_integration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f20d06b3d822ab5589ac5c982f44527003d289695569ae2bb38bc1ba1564c5e4\",\"content\":\"\\\"\\\"\\\"End-to-end RBAC enforcement tests driven by an in-test allow/deny enforcer.\\n\\nThe OSS authorization service is a pass-through (``enforce()`` always allows and\\n``supports_cross_user_fetch()`` is False), so allow/deny semantics cannot be\\nasserted against it directly. These tests install :class:`PolicyTestAuthorizationService`\\n(see ``_policy_double``) with ``AUTHZ_ENABLED=True`` / ``AUTHZ_SUPERUSER_BYPASS=False``\\nand exercise the *real* flow routes over HTTP, validating that:\\n\\n* the per-route guards (``ensure_flow_permission`` via the ``Authorized*Flow``\\n  dependencies) actually gate read/write/delete/create/execute by role,\\n* cross-user denials are masked as 404 (not 403) on fetch routes, while\\n  write and delete denials on readable flows return an explicit 403,\\n* the share-aware fetch + ``authz_share`` rows grant cross-user access, and\\n* domain resolution (``_resolve_authz_domain``) scopes a domain-bound grant.\\n\\nRemoving a guard or regressing domain resolution flips one of these assertions.\\nEverything runs against the OSS package only \u2014 no EE Casbin enforcer required.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom unittest.mock import MagicMock\\nfrom uuid import UUID, uuid4\\n\\nfrom langflow.api.v1.knowledge_bases import KBStorageHelper\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import (\\n    get_auth_service,\\n    get_authorization_service,\\n    get_settings_service,\\n    session_scope,\\n)\\n\\nfrom ._policy_double import (\\n    assign_role,\\n    create_user_share,\\n    install_policy_authz,\\n    seed_system_roles,\\n)\\n\\n_PASSWORD = \\\"testpassword\\\"  # noqa: S105 \u2014 test-only credential  # pragma: allowlist secret\\n\\n\\nasync def _make_user(username: str) -> UUID:\\n    \\\"\\\"\\\"Insert an active, non-superuser user and return its id.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        user = User(username=username, password=get_auth_service().get_password_hash(_PASSWORD), is_active=True)\\n        session.add(user)\\n        await session.flush()\\n        user_id = user.id\\n        await session.commit()\\n    return user_id\\n\\n\\nasync def _login(client, username: str) -> dict[str, str]:\\n    \\\"\\\"\\\"Log in and return an Authorization header for ``username``.\\\"\\\"\\\"\\n    response = await client.post(\\\"api/v1/login\\\", data={\\\"username\\\": username, \\\"password\\\": _PASSWORD})\\n    assert response.status_code == 200, f\\\"login failed for {username}: {response.text}\\\"\\n    return {\\\"Authorization\\\": f\\\"Bearer {response.json()['access_token']}\\\"}\\n\\n\\nasync def _make_flow(owner_id: UUID, name: str, *, workspace_id: UUID | None = None) -> UUID:\\n    \\\"\\\"\\\"Insert a minimal flow owned by ``owner_id`` and return its id.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        flow = Flow(name=name, user_id=owner_id, workspace_id=workspace_id, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n        session.add(flow)\\n        await session.flush()\\n        flow_id = flow.id\\n        await session.commit()\\n    return flow_id\\n\\n\\nasync def _make_project(owner_id: UUID, name: str, *, workspace_id: UUID | None = None) -> UUID:\\n    \\\"\\\"\\\"Insert a project owned by ``owner_id`` and return its id.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        project = Folder(name=name, user_id=owner_id, workspace_id=workspace_id)\\n        session.add(project)\\n        await session.flush()\\n        assert project.id is not None\\n        project_id = project.id\\n        await session.commit()\\n    return project_id\\n\\n\\nasync def _seed_roles() -> dict[str, UUID]:\\n    async with session_scope() as session:\\n        return await seed_system_roles(session)\\n\\n\\nasync def _role_user(\\n    client,\\n    role_name: str,\\n    role_ids: dict[str, UUID],\\n    *,\\n    domain_type: str = \\\"global\\\",\\n    domain_id: UUID | None = None,\\n) -> tuple[UUID, dict[str, str]]:\\n    \\\"\\\"\\\"Create a user, assign ``role_name`` (optionally domain-scoped), return (id, headers).\\\"\\\"\\\"\\n    username = f\\\"{role_name}_{uuid4().hex}\\\"\\n    user_id = await _make_user(username)\\n    async with session_scope() as session:\\n        await assign_role(\\n            session,\\n            user_id=user_id,\\n            role_id=role_ids[role_name],\\n            domain_type=domain_type,\\n            domain_id=domain_id,\\n        )\\n    headers = await _login(client, username)\\n    return user_id, headers\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Role matrix (Phase 1.11): viewer / developer / admin on flow routes.\\n# Flows are owned by a separate user so the guards' owner-override does not mask\\n# the role decision \u2014 these assertions exercise the *role*, not ownership.\\n# --------------------------------------------------------------------------- #\\n\\n\\nasync def test_viewer_can_read_and_execute_but_not_write_delete_or_create(client):\\n    role_ids = await _seed_roles()\\n    owner_id = await _make_user(f\\\"owner_{uuid4().hex}\\\")\\n    flow_id = await _make_flow(owner_id, f\\\"flow_{uuid4().hex}\\\")\\n    _viewer_id, headers = await _role_user(client, \\\"viewer\\\", role_ids)\\n\\n    with install_policy_authz(get_settings_service()):\\n        # read -> allowed\\n        assert (await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=headers)).status_code == 200\\n        # execute (build) -> allowed (viewer has flow:execute)\\n        build = await client.post(f\\\"api/v1/build/{flow_id}/flow\\\", headers=headers, json={})\\n        assert build.status_code == 200, build.text\\n        # write -> denied, but the flow is readable so return an edit-permission 403.\\n        patch = await client.patch(f\\\"api/v1/flows/{flow_id}\\\", headers=headers, json={\\\"name\\\": f\\\"x_{uuid4().hex}\\\"})\\n        assert patch.status_code == 403\\n        assert patch.json()[\\\"detail\\\"] == \\\"You don't have permission to edit this flow.\\\"\\n        # delete -> denied, but the flow is readable so return a delete-permission 403.\\n        delete = await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=headers)\\n        assert delete.status_code == 403\\n        assert delete.json()[\\\"detail\\\"] == \\\"You don't have permission to delete this flow.\\\"\\n        # create into the *owner's* project -> denied; 403 is correct here (no\\n        # existing resource UUID to protect).\\n        owner_project_id = await _make_project(owner_id, f\\\"owner_project_{uuid4().hex}\\\")\\n        create_elsewhere = await client.post(\\n            \\\"api/v1/flows/\\\",\\n            headers=headers,\\n            json={\\n                \\\"name\\\": f\\\"new_{uuid4().hex}\\\",\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n                \\\"folder_id\\\": str(owner_project_id),\\n            },\\n        )\\n        assert create_elsewhere.status_code == 403\\n        # create into a project the viewer owns -> allowed by owner override.\\n        # Ownership is checked before any policy rule, and a project is the\\n        # only ownership a not-yet-created flow can inherit. Without this a\\n        # read-only role cannot use the default project created for them\\n        # (LE-1905 finding 11).\\n        create_own = await client.post(\\n            \\\"api/v1/flows/\\\", headers=headers, json={\\\"name\\\": f\\\"new_{uuid4().hex}\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        )\\n        assert create_own.status_code == 201, create_own.text\\n\\n\\nasync def test_developer_can_write_and_create_but_not_delete(client):\\n    role_ids = await _seed_roles()\\n    owner_id = await _make_user(f\\\"owner_{uuid4().hex}\\\")\\n    flow_id = await _make_flow(owner_id, f\\\"flow_{uuid4().hex}\\\")\\n    _dev_id, headers = await _role_user(client, \\\"developer\\\", role_ids)\\n\\n    with install_policy_authz(get_settings_service()):\\n        assert (await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=headers)).status_code == 200\\n        # write someone else's flow -> allowed via the developer role (not ownership)\\n        patch = await client.patch(f\\\"api/v1/flows/{flow_id}\\\", headers=headers, json={\\\"name\\\": f\\\"renamed_{uuid4().hex}\\\"})\\n        assert patch.status_code == 200, patch.text\\n        # create -> allowed\\n        create = await client.post(\\n            \\\"api/v1/flows/\\\", headers=headers, json={\\\"name\\\": f\\\"dev_{uuid4().hex}\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        )\\n        assert create.status_code == 201, create.text\\n        # delete -> denied (developer lacks flow:delete) but readable -> 403\\n        delete = await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=headers)\\n        assert delete.status_code == 403\\n        assert delete.json()[\\\"detail\\\"] == \\\"You don't have permission to delete this flow.\\\"\\n\\n\\nasync def test_admin_has_full_flow_access(client):\\n    role_ids = await _seed_roles()\\n    owner_id = await _make_user(f\\\"owner_{uuid4().hex}\\\")\\n    flow_id = await _make_flow(owner_id, f\\\"flow_{uuid4().hex}\\\")\\n    _admin_id, headers = await _role_user(client, \\\"admin\\\", role_ids)\\n\\n    with install_policy_authz(get_settings_service()):\\n        assert (await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=headers)).status_code == 200\\n        patch = await client.patch(f\\\"api/v1/flows/{flow_id}\\\", headers=headers, json={\\\"name\\\": f\\\"a_{uuid4().hex}\\\"})\\n        assert patch.status_code == 200, patch.text\\n        create = await client.post(\\n            \\\"api/v1/flows/\\\", headers=headers, json={\\\"name\\\": f\\\"adm_{uuid4().hex}\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        )\\n        assert create.status_code == 201, create.text\\n        # delete -> allowed (admin has flow:delete)\\n        assert (await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=headers)).status_code == 200\\n        # the flow is gone -> now 404 for everyone (sanity)\\n        assert (await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=headers)).status_code == 404\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Share lifecycle (Phase 3.13): Alice shares a flow with Bob.\\n# --------------------------------------------------------------------------- #\\n\\n\\nasync def test_share_grants_cross_user_access_and_absence_is_404(client):\\n    settings = get_settings_service()\\n    alice_id = await _make_user(f\\\"alice_{uuid4().hex}\\\")\\n    bob_username = f\\\"bob_{uuid4().hex}\\\"\\n    bob_id = await _make_user(bob_username)\\n    flow_id = await _make_flow(alice_id, f\\\"aliceflow_{uuid4().hex}\\\")\\n    bob_headers = await _login(client, bob_username)\\n\\n    # Without a share, Bob cannot reach Alice's flow at all \u2014 and the denial is a\\n    # 404 (UUID-privacy mask), not a 403, on every fetch route.\\n    with install_policy_authz(settings):\\n        assert (await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=bob_headers)).status_code == 404\\n        assert (\\n            await client.patch(f\\\"api/v1/flows/{flow_id}\\\", headers=bob_headers, json={\\\"name\\\": \\\"x\\\"})\\n        ).status_code == 404\\n        assert (await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=bob_headers)).status_code == 404\\n        assert (await client.post(f\\\"api/v1/build/{flow_id}/flow\\\", headers=bob_headers, json={})).status_code == 404\\n\\n    # Alice grants Bob an admin-level share (read + write + execute).\\n    async with session_scope() as session:\\n        await create_user_share(\\n            session,\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow_id,\\n            target_user_id=bob_id,\\n            permission_level=\\\"admin\\\",\\n            created_by=alice_id,\\n        )\\n\\n    with install_policy_authz(settings):\\n        assert (await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=bob_headers)).status_code == 200\\n        patch = await client.patch(f\\\"api/v1/flows/{flow_id}\\\", headers=bob_headers, json={\\\"name\\\": f\\\"bob_{uuid4().hex}\\\"})\\n        assert patch.status_code == 200, patch.text\\n        build = await client.post(f\\\"api/v1/build/{flow_id}/flow\\\", headers=bob_headers, json={})\\n        assert build.status_code == 200, build.text\\n\\n\\nasync def test_read_only_share_allows_get_but_denies_write_and_execute(client):\\n    \\\"\\\"\\\"A read-level share grants GET but neither PATCH nor build \u2014 permission_level is enforced, not mere presence.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    alice_id = await _make_user(f\\\"alice_{uuid4().hex}\\\")\\n    bob_username = f\\\"bob_{uuid4().hex}\\\"\\n    bob_id = await _make_user(bob_username)\\n    flow_id = await _make_flow(alice_id, f\\\"aliceflow_{uuid4().hex}\\\")\\n    bob_headers = await _login(client, bob_username)\\n\\n    async with session_scope() as session:\\n        await create_user_share(\\n            session,\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow_id,\\n            target_user_id=bob_id,\\n            permission_level=\\\"read\\\",\\n            created_by=alice_id,\\n        )\\n\\n    with install_policy_authz(settings):\\n        assert (await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=bob_headers)).status_code == 200\\n        # write is not granted by a read-level share, but the flow is readable\\n        # so return an edit-permission 403 instead of a \\\"not found\\\" mask.\\n        patch = await client.patch(f\\\"api/v1/flows/{flow_id}\\\", headers=bob_headers, json={\\\"name\\\": \\\"nope\\\"})\\n        assert patch.status_code == 403\\n        assert patch.json()[\\\"detail\\\"] == \\\"You don't have permission to edit this flow.\\\"\\n        # delete is likewise denied on a readable flow -> delete-permission 403,\\n        # matching the write behavior (LE-1738 B9: a flow the caller can GET must\\n        # not flip to 404 on a denied DELETE).\\n        delete = await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=bob_headers)\\n        assert delete.status_code == 403\\n        assert delete.json()[\\\"detail\\\"] == \\\"You don't have permission to delete this flow.\\\"\\n        # execute is modeled independently from write \u2014 a read-level share must\\n        # not grant build either -> deny -> 404\\n        build = await client.post(f\\\"api/v1/build/{flow_id}/flow\\\", headers=bob_headers, json={})\\n        # execute -> denied. Bob can read this flow, so answering \\\"not found\\\"\\n        # would hide a resource he has already opened and send him to debug a\\n        # flow id that is correct (LE-1905 finding 8).\\n        assert build.status_code == 403\\n        assert build.json()[\\\"detail\\\"] == \\\"You don't have permission to execute this flow.\\\"\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Flow create destinations: plugin grants may target a foreign-owned project,\\n# while the OSS pass-through must keep its existing owner-scoped fallback.\\n# --------------------------------------------------------------------------- #\\n\\n\\nasync def test_project_scoped_developer_can_create_flow_in_foreign_project(client):\\n    \\\"\\\"\\\"A plugin-authorized non-owner must retain the project destination it was granted.\\\"\\\"\\\"\\n    role_ids = await _seed_roles()\\n    project_owner_id = await _make_user(f\\\"project_owner_{uuid4().hex}\\\")\\n    workspace_id = uuid4()\\n    project_id = await _make_project(\\n        project_owner_id,\\n        f\\\"shared_project_{uuid4().hex}\\\",\\n        workspace_id=workspace_id,\\n    )\\n    developer_id, headers = await _role_user(\\n        client,\\n        \\\"developer\\\",\\n        role_ids,\\n        domain_type=\\\"project\\\",\\n        domain_id=project_id,\\n    )\\n\\n    with install_policy_authz(get_settings_service()):\\n        response = await client.post(\\n            \\\"api/v1/flows/\\\",\\n            headers=headers,\\n            json={\\n                \\\"name\\\": f\\\"shared_project_flow_{uuid4().hex}\\\",\\n                \\\"folder_id\\\": str(project_id),\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            },\\n        )\\n        assert response.status_code == 201, response.text\\n        created = response.json()\\n        edit = await client.patch(\\n            f\\\"api/v1/flows/{created['id']}\\\",\\n            headers=headers,\\n            json={\\\"name\\\": f\\\"edited_shared_project_flow_{uuid4().hex}\\\"},\\n        )\\n        upload = await client.post(\\n            \\\"api/v1/flows/upload/\\\",\\n            headers=headers,\\n            files={\\n                \\\"file\\\": (\\n                    \\\"shared-project-flow.json\\\",\\n                    json.dumps(\\n                        {\\n                            \\\"id\\\": created[\\\"id\\\"],\\n                            \\\"name\\\": f\\\"uploaded_shared_project_flow_{uuid4().hex}\\\",\\n                        }\\n                    ),\\n                    \\\"application/json\\\",\\n                )\\n            },\\n        )\\n\\n    assert created[\\\"user_id\\\"] == str(developer_id)\\n    assert created[\\\"folder_id\\\"] == str(project_id)\\n    assert created[\\\"workspace_id\\\"] == str(workspace_id)\\n    assert edit.status_code == 200, edit.text\\n    assert edit.json()[\\\"folder_id\\\"] == str(project_id)\\n    assert edit.json()[\\\"workspace_id\\\"] == str(workspace_id)\\n    assert upload.status_code == 201, upload.text\\n    assert upload.json()[0][\\\"id\\\"] == created[\\\"id\\\"]\\n    assert upload.json()[0][\\\"folder_id\\\"] == str(project_id)\\n    assert upload.json()[0][\\\"workspace_id\\\"] == str(workspace_id)\\n\\n\\nasync def test_oss_create_flow_keeps_foreign_project_owner_scoped(client):\\n    \\\"\\\"\\\"The OSS service must not widen a foreign project merely because authz is enabled.\\\"\\\"\\\"\\n    project_owner_id = await _make_user(f\\\"project_owner_{uuid4().hex}\\\")\\n    foreign_project_id = await _make_project(project_owner_id, f\\\"foreign_project_{uuid4().hex}\\\")\\n    creator_username = f\\\"creator_{uuid4().hex}\\\"\\n    creator_id = await _make_user(creator_username)\\n    headers = await _login(client, creator_username)\\n\\n    settings = get_settings_service()\\n    authz = get_authorization_service()\\n    assert await authz.supports_cross_user_fetch() is False\\n    saved_authz_enabled = settings.auth_settings.AUTHZ_ENABLED\\n    settings.auth_settings.AUTHZ_ENABLED = True\\n    try:\\n        response = await client.post(\\n            \\\"api/v1/flows/\\\",\\n            headers=headers,\\n            json={\\n                \\\"name\\\": f\\\"oss_owner_scoped_flow_{uuid4().hex}\\\",\\n                \\\"folder_id\\\": str(foreign_project_id),\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            },\\n        )\\n    finally:\\n        settings.auth_settings.AUTHZ_ENABLED = saved_authz_enabled\\n\\n    assert response.status_code == 201, response.text\\n    created = response.json()\\n    assert created[\\\"folder_id\\\"] != str(foreign_project_id)\\n    async with session_scope() as session:\\n        destination = await session.get(Folder, UUID(created[\\\"folder_id\\\"]))\\n    assert destination is not None\\n    assert destination.user_id == creator_id\\n\\n\\nasync def test_cross_user_destination_resolution_does_not_widen_flow_moves(client):\\n    \\\"\\\"\\\"Cross-user destination fetch is limited to CREATE and cannot bypass move authorization.\\\"\\\"\\\"\\n    project_owner_id = await _make_user(f\\\"move_project_owner_{uuid4().hex}\\\")\\n    foreign_project_id = await _make_project(project_owner_id, f\\\"move_target_{uuid4().hex}\\\")\\n    creator_username = f\\\"move_creator_{uuid4().hex}\\\"\\n    await _make_user(creator_username)\\n    headers = await _login(client, creator_username)\\n\\n    create = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        headers=headers,\\n        json={\\\"name\\\": f\\\"move_source_{uuid4().hex}\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}},\\n    )\\n    assert create.status_code == 201, create.text\\n    original_folder_id = create.json()[\\\"folder_id\\\"]\\n\\n    with install_policy_authz(get_settings_service()):\\n        move = await client.patch(\\n            f\\\"api/v1/flows/{create.json()['id']}\\\",\\n            headers=headers,\\n            json={\\\"folder_id\\\": str(foreign_project_id)},\\n        )\\n\\n    assert move.status_code == 200, move.text\\n    assert move.json()[\\\"folder_id\\\"] == original_folder_id\\n    assert move.json()[\\\"folder_id\\\"] != str(foreign_project_id)\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Domain resolution: a workspace-scoped grant must only apply in its workspace.\\n# --------------------------------------------------------------------------- #\\n\\n\\nasync def test_domain_scoped_role_applies_only_in_matching_domain(client):\\n    role_ids = await _seed_roles()\\n    owner_id = await _make_user(f\\\"owner_{uuid4().hex}\\\")\\n    workspace_a = uuid4()\\n    workspace_b = uuid4()\\n    flow_a = await _make_flow(owner_id, f\\\"a_{uuid4().hex}\\\", workspace_id=workspace_a)\\n    flow_b = await _make_flow(owner_id, f\\\"b_{uuid4().hex}\\\", workspace_id=workspace_b)\\n    # viewer scoped to workspace A only.\\n    _viewer_id, headers = await _role_user(client, \\\"viewer\\\", role_ids, domain_type=\\\"workspace\\\", domain_id=workspace_a)\\n\\n    with install_policy_authz(get_settings_service()):\\n        # flow A resolves to domain workspace:{A} -> grant covers -> read allowed.\\n        assert (await client.get(f\\\"api/v1/flows/{flow_a}\\\", headers=headers)).status_code == 200\\n        # flow B resolves to workspace:{B} -> grant does NOT cover -> denied -> 404.\\n        # (If domain resolution regressed to '*', the workspace-A grant would stop\\n        # matching flow A and the assertion above would fail instead.)\\n        assert (await client.get(f\\\"api/v1/flows/{flow_b}\\\", headers=headers)).status_code == 404\\n\\n\\n# --------------------------------------------------------------------------- #\\n# File / Knowledge Base create guards (QA BUG-2).\\n# Create has no existing resource owner, so the prospective owner must not\\n# trigger the existing-resource owner override before the policy service runs.\\n# --------------------------------------------------------------------------- #\\n\\n\\ndef _knowledge_base_payload(name: str) -> dict[str, object]:\\n    return {\\n        \\\"name\\\": name,\\n        \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n        \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n        \\\"backend_type\\\": \\\"chroma\\\",\\n        \\\"backend_config\\\": {},\\n    }\\n\\n\\nasync def test_roleless_user_cannot_create_files_or_knowledge_bases(client, monkeypatch, tmp_path):\\n    username = f\\\"roleless_{uuid4().hex}\\\"\\n    await _make_user(username)\\n    headers = await _login(client, username)\\n\\n    monkeypatch.setattr(KBStorageHelper, \\\"get_root_path\\\", lambda: tmp_path)\\n    monkeypatch.setattr(KBStorageHelper, \\\"get_fresh_chroma_client\\\", lambda _path: MagicMock())\\n    monkeypatch.setattr(KBStorageHelper, \\\"release_chroma_resources\\\", lambda _path: None)\\n\\n    with install_policy_authz(get_settings_service()):\\n        upload = await client.post(\\n            \\\"api/v2/files\\\",\\n            headers=headers,\\n            files={\\\"file\\\": (\\\"roleless.txt\\\", b\\\"not allowed\\\", \\\"text/plain\\\")},\\n        )\\n        test_connection = await client.post(\\n            \\\"api/v1/knowledge_bases/test-connection\\\",\\n            headers=headers,\\n            json={\\\"backend_type\\\": \\\"chroma\\\", \\\"backend_config\\\": {}},\\n        )\\n        create = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=headers,\\n            json=_knowledge_base_payload(f\\\"Roleless_{uuid4().hex}\\\"),\\n        )\\n        preview = await client.post(\\n            \\\"api/v1/knowledge_bases/preview-chunks\\\",\\n            headers=headers,\\n            files={\\\"files\\\": (\\\"roleless.txt\\\", b\\\"not allowed\\\", \\\"text/plain\\\")},\\n        )\\n\\n        assert {\\n            \\\"file upload\\\": upload.status_code,\\n            \\\"knowledge-base test connection\\\": test_connection.status_code,\\n            \\\"knowledge-base create\\\": create.status_code,\\n            \\\"knowledge-base preview chunks\\\": preview.status_code,\\n        } == {\\n            \\\"file upload\\\": 403,\\n            \\\"knowledge-base test connection\\\": 403,\\n            \\\"knowledge-base create\\\": 403,\\n            \\\"knowledge-base preview chunks\\\": 403,\\n        }\\n\\n\\nasync def test_developer_can_create_files_and_knowledge_bases(client, monkeypatch, tmp_path):\\n    role_ids = await _seed_roles()\\n    _developer_id, headers = await _role_user(client, \\\"developer\\\", role_ids)\\n\\n    monkeypatch.setattr(KBStorageHelper, \\\"get_root_path\\\", lambda: tmp_path)\\n    chroma_client = MagicMock()\\n    monkeypatch.setattr(KBStorageHelper, \\\"get_fresh_chroma_client\\\", lambda _path: chroma_client)\\n    monkeypatch.setattr(KBStorageHelper, \\\"release_chroma_resources\\\", lambda _path: None)\\n\\n    with install_policy_authz(get_settings_service()):\\n        upload = await client.post(\\n            \\\"api/v2/files\\\",\\n            headers=headers,\\n            files={\\\"file\\\": (\\\"developer.txt\\\", b\\\"allowed\\\", \\\"text/plain\\\")},\\n        )\\n        assert upload.status_code == 201, upload.text\\n\\n        test_connection = await client.post(\\n            \\\"api/v1/knowledge_bases/test-connection\\\",\\n            headers=headers,\\n            json={\\\"backend_type\\\": \\\"chroma\\\", \\\"backend_config\\\": {}},\\n        )\\n        assert test_connection.status_code == 200, test_connection.text\\n\\n        create = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=headers,\\n            json=_knowledge_base_payload(f\\\"Developer_{uuid4().hex}\\\"),\\n        )\\n        assert create.status_code == 201, create.text\\n\\n        preview = await client.post(\\n            \\\"api/v1/knowledge_bases/preview-chunks\\\",\\n            headers=headers,\\n            files={\\\"files\\\": (\\\"developer.txt\\\", b\\\"allowed\\\", \\\"text/plain\\\")},\\n        )\\n        assert preview.status_code == 200, preview.text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_route_ceiling_guards.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6044387adba52fe602f9c6ea6402d80cc98ace578e58ac430cc21d14dfb71c50\",\"content\":\"\\\"\\\"\\\"Regression tests for access-ceiling guards added to execution / mutation routes.\\n\\nPR #13293 added ``ensure_*_permission`` guards to four route areas that\\npreviously escaped the external access ceiling:\\n\\n* ``mcp_utils.handle_call_tool`` (flow EXECUTE)\\n* ``flow_version`` create/activate/delete (flow WRITE/DELETE)\\n* ``files`` upload/delete (flow WRITE)\\n* ``memories`` create/update/delete/flush/regenerate (knowledge-base actions)\\n\\nThese tests drive the real route handlers with the data services mocked,\\nverifying two invariants for each newly-guarded action:\\n\\n1. A viewer-ceiling caller is denied *before* the mutating data service is\\n   touched (normally with HTTP 403; UUID-private resources may mask it as 404).\\n2. With no ceiling installed, the owner-override path returns early and the\\n   route proceeds to the underlying service \u2014 preserving feature-off behavior.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.services.authorization.access_ceiling import (\\n    ExternalAccessContext,\\n    set_current_external_access_context,\\n)\\n\\nfrom ._common import (\\n    _StubAuthorizationService,\\n    install_audit_recorder,\\n    install_authz,\\n    install_settings,\\n)\\n\\n\\n@pytest.fixture\\ndef owner():\\n    \\\"\\\"\\\"A non-superuser acting as the resource owner.\\\"\\\"\\\"\\n    return SimpleNamespace(id=uuid4(), username=\\\"owner\\\", is_superuser=False)\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _wire_guard_services(monkeypatch):\\n    \\\"\\\"\\\"Install pass-through authz services so guards run the real ceiling path.\\n\\n    ``AUTHZ_ENABLED=False`` mirrors the OSS default: the only thing that can deny\\n    is the external access ceiling, which is checked before the gate.\\n    \\\"\\\"\\\"\\n    install_settings(monkeypatch, authz_enabled=False, audit_enabled=True)\\n    install_authz(monkeypatch, _StubAuthorizationService(allow=True))\\n    install_audit_recorder(monkeypatch)\\n\\n\\ndef _viewer_ceiling() -> ExternalAccessContext:\\n    return ExternalAccessContext(provider=\\\"openrag\\\", subject=\\\"s-1\\\", level=\\\"viewer\\\")\\n\\n\\ndef _make_flow(owner_id):\\n    return SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        workspace_id=None,\\n        folder_id=None,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        name=\\\"flow\\\",\\n    )\\n\\n\\n# --------------------------------------------------------------------------- #\\n# C1 \u2014 mcp_utils.handle_call_tool (flow EXECUTE)\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_mcp_call_tool_viewer_denied_before_run(monkeypatch, owner):\\n    from langflow.api.v1 import mcp_utils\\n\\n    flow = _make_flow(owner.id)\\n    monkeypatch.setattr(mcp_utils, \\\"get_flow_snake_case\\\", AsyncMock(return_value=flow))\\n    monkeypatch.setattr(mcp_utils, \\\"get_mcp_config\\\", lambda: SimpleNamespace(enable_progress_notifications=False))\\n    run_spy = AsyncMock()\\n    monkeypatch.setattr(mcp_utils, \\\"simple_run_flow\\\", run_spy)\\n    monkeypatch.setattr(mcp_utils, \\\"with_db_session\\\", lambda fn: fn(MagicMock()))\\n    mcp_utils.current_user_ctx.set(owner)\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await mcp_utils.handle_call_tool(name=\\\"flow\\\", arguments={}, server=MagicMock())\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    run_spy.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_mcp_call_tool_owner_runs_without_ceiling(monkeypatch, owner):\\n    from langflow.api.v1 import mcp_utils\\n\\n    flow = _make_flow(owner.id)\\n    monkeypatch.setattr(mcp_utils, \\\"get_flow_snake_case\\\", AsyncMock(return_value=flow))\\n    monkeypatch.setattr(mcp_utils, \\\"get_mcp_config\\\", lambda: SimpleNamespace(enable_progress_notifications=False))\\n    run_spy = AsyncMock(return_value=SimpleNamespace(outputs=[]))\\n    monkeypatch.setattr(mcp_utils, \\\"simple_run_flow\\\", run_spy)\\n    monkeypatch.setattr(mcp_utils, \\\"with_db_session\\\", lambda fn: fn(MagicMock()))\\n    mcp_utils.current_user_ctx.set(owner)\\n\\n    await mcp_utils.handle_call_tool(name=\\\"flow\\\", arguments={}, server=MagicMock())\\n\\n    run_spy.assert_awaited_once()\\n\\n\\n# --------------------------------------------------------------------------- #\\n# H2 \u2014 flow_version create / activate / delete\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_flow_version_create_snapshot_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import flow_version\\n\\n    flow = _make_flow(owner.id)\\n    monkeypatch.setattr(flow_version, \\\"_get_user_flow\\\", AsyncMock(return_value=flow))\\n    create_spy = AsyncMock()\\n    monkeypatch.setattr(flow_version, \\\"create_flow_version_entry\\\", create_spy)\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await flow_version.create_snapshot(flow_id=flow.id, current_user=owner, session=MagicMock(), body=None)\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    create_spy.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_flow_version_delete_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import flow_version\\n\\n    flow = _make_flow(owner.id)\\n    monkeypatch.setattr(flow_version, \\\"_get_user_flow\\\", AsyncMock(return_value=flow))\\n    delete_spy = AsyncMock()\\n    monkeypatch.setattr(flow_version, \\\"delete_flow_version_entry\\\", delete_spy)\\n    monkeypatch.setattr(flow_version, \\\"get_flow_version_entry_or_raise\\\", AsyncMock())\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await flow_version.delete_version_entry(\\n                flow_id=flow.id, version_id=uuid4(), current_user=owner, session=MagicMock()\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    delete_spy.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_flow_version_create_snapshot_owner_proceeds(monkeypatch, owner):\\n    from langflow.api.v1 import flow_version\\n\\n    flow = _make_flow(owner.id)\\n    monkeypatch.setattr(flow_version, \\\"_get_user_flow\\\", AsyncMock(return_value=flow))\\n    entry = SimpleNamespace(id=uuid4())\\n    create_spy = AsyncMock(return_value=entry)\\n    monkeypatch.setattr(flow_version, \\\"create_flow_version_entry\\\", create_spy)\\n    monkeypatch.setattr(flow_version, \\\"_version_to_read\\\", lambda e: e)\\n\\n    result = await flow_version.create_snapshot(flow_id=flow.id, current_user=owner, session=MagicMock(), body=None)\\n\\n    create_spy.assert_awaited_once()\\n    assert result is entry\\n\\n\\n# --------------------------------------------------------------------------- #\\n# F19 \u2014 files upload / delete (flow WRITE)\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_files_upload_viewer_denied(owner):\\n    from langflow.api.v1 import files\\n\\n    flow = _make_flow(owner.id)\\n    storage = MagicMock(save_file=AsyncMock())\\n    settings_service = SimpleNamespace(settings=SimpleNamespace(max_file_size_upload=100))\\n    upload = SimpleNamespace(size=1, filename=\\\"x.txt\\\", read=AsyncMock(return_value=b\\\"data\\\"))\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await files.upload_file(\\n                file=upload,\\n                flow=flow,\\n                current_user=owner,\\n                storage_service=storage,\\n                settings_service=settings_service,\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    storage.save_file.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_files_delete_viewer_denied(owner):\\n    from langflow.api.v1 import files\\n\\n    flow = _make_flow(owner.id)\\n    storage = MagicMock(delete_file=AsyncMock())\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await files.delete_file(file_name=\\\"x.txt\\\", flow=flow, current_user=owner, storage_service=storage)\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    storage.delete_file.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_files_delete_owner_proceeds(owner):\\n    from langflow.api.v1 import files\\n\\n    flow = _make_flow(owner.id)\\n    storage = MagicMock(delete_file=AsyncMock())\\n\\n    result = await files.delete_file(file_name=\\\"x.txt\\\", flow=flow, current_user=owner, storage_service=storage)\\n\\n    storage.delete_file.assert_awaited_once()\\n    assert \\\"deleted successfully\\\" in result[\\\"message\\\"]\\n\\n\\n# --------------------------------------------------------------------------- #\\n# F20 \u2014 memories create / update / delete / flush / regenerate\\n# --------------------------------------------------------------------------- #\\n\\n\\ndef _install_memory_service(monkeypatch, **methods):\\n    from langflow.api.v1 import memories\\n\\n    service = SimpleNamespace(**methods)\\n    monkeypatch.setattr(memories, \\\"get_memory_base_service\\\", lambda: service)\\n    return service\\n\\n\\n@pytest.mark.anyio\\nasync def test_memory_create_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import memories\\n\\n    create_spy = AsyncMock()\\n    _install_memory_service(monkeypatch, create=create_spy)\\n    payload = SimpleNamespace()\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await memories.create_memory_base(current_user=owner, payload=payload)\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    create_spy.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_memory_delete_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import memories\\n\\n    delete_spy = AsyncMock(return_value=True)\\n    mb = SimpleNamespace(id=uuid4(), user_id=owner.id, kb_name=\\\"kb\\\")\\n    _install_memory_service(monkeypatch, delete=delete_spy, get=AsyncMock(return_value=mb))\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await memories.delete_memory_base(memory_base_id=uuid4(), current_user=owner)\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 404\\n    delete_spy.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_memory_flush_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import memories\\n\\n    trigger_spy = AsyncMock(return_value=uuid4())\\n    mb = SimpleNamespace(id=uuid4(), user_id=owner.id, kb_name=\\\"kb\\\")\\n    _install_memory_service(monkeypatch, trigger_ingestion=trigger_spy, get=AsyncMock(return_value=mb))\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await memories.flush_memory_base(\\n                memory_base_id=uuid4(), current_user=owner, body=SimpleNamespace(session_id=\\\"s\\\")\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 404\\n    trigger_spy.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_memory_regenerate_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import memories\\n\\n    regen_spy = AsyncMock(return_value=[])\\n    mb = SimpleNamespace(id=uuid4(), user_id=owner.id, kb_name=\\\"kb\\\")\\n    _install_memory_service(monkeypatch, regenerate=regen_spy, get=AsyncMock(return_value=mb))\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await memories.regenerate_memory_base(memory_base_id=uuid4(), current_user=owner)\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 404\\n    regen_spy.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_memory_delete_owner_proceeds(monkeypatch, owner):\\n    \\\"\\\"\\\"An editor (delete is now in the editor ceiling) deletes their own memory base.\\\"\\\"\\\"\\n    from langflow.api.v1 import memories\\n\\n    delete_spy = AsyncMock(return_value=True)\\n    mb = SimpleNamespace(id=uuid4(), user_id=owner.id, kb_name=\\\"kb\\\")\\n    _install_memory_service(monkeypatch, delete=delete_spy, get=AsyncMock(return_value=mb))\\n\\n    set_current_external_access_context(ExternalAccessContext(provider=\\\"openrag\\\", subject=\\\"s-1\\\", level=\\\"editor\\\"))\\n    try:\\n        await memories.delete_memory_base(memory_base_id=uuid4(), current_user=owner)\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    delete_spy.assert_awaited_once()\\n\\n\\n# --------------------------------------------------------------------------- #\\n# endpoints.custom_component / custom_component_update (direct ceiling, \\\"create\\\")\\n#\\n# These routes instantiate posted component code and are not tied to a single\\n# owned resource, so they enforce the deny-only ceiling primitive directly\\n# instead of an ``ensure_*_permission`` guard.\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_custom_component_viewer_denied_before_build(monkeypatch, owner):\\n    from langflow.api.v1 import endpoints\\n\\n    build_spy = MagicMock()\\n    monkeypatch.setattr(endpoints, \\\"build_custom_component_template\\\", build_spy)\\n    raw_code = SimpleNamespace(code=\\\"print('x')\\\", frontend_node=None)\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await endpoints.custom_component(\\n                raw_code=raw_code,\\n                user=owner,\\n                request=MagicMock(),\\n                provider_policy_attributes={},\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    build_spy.assert_not_called()\\n\\n\\n@pytest.mark.anyio\\nasync def test_custom_component_update_viewer_denied_before_build(monkeypatch, owner):\\n    from langflow.api.v1 import endpoints\\n\\n    build_spy = MagicMock()\\n    monkeypatch.setattr(endpoints, \\\"build_custom_component_template\\\", build_spy)\\n    code_request = SimpleNamespace(code=\\\"print('x')\\\", tool_mode=False, get_template=dict)\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await endpoints.custom_component_update(\\n                code_request=code_request,\\n                user=owner,\\n                request=MagicMock(),\\n                provider_policy_attributes={},\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    build_spy.assert_not_called()\\n\\n\\n@pytest.mark.anyio\\nasync def test_custom_component_editor_passes_ceiling(monkeypatch, owner):\\n    \\\"\\\"\\\"An editor ceiling allows component instantiation (create is in the editor set).\\\"\\\"\\\"\\n    from langflow.api.v1 import endpoints\\n\\n    # Stub the build pipeline so the route returns without real execution; the\\n    # point is that the ceiling check does NOT short-circuit for an editor.\\n    instance = MagicMock()\\n    instance.update_frontend_node = AsyncMock(return_value={\\\"tool_mode\\\": False})\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"build_custom_component_template\\\",\\n        MagicMock(return_value=({\\\"tool_mode\\\": False}, instance)),\\n    )\\n    monkeypatch.setattr(endpoints, \\\"get_instance_name\\\", lambda _i: \\\"MyComponent\\\")\\n    # Settings: custom components allowed, no admin-only gate.\\n    settings = SimpleNamespace(allow_custom_components=True, custom_component_admin_only=False)\\n    monkeypatch.setattr(endpoints, \\\"get_settings_service\\\", lambda: SimpleNamespace(settings=settings))\\n    # ``isinstance(instance, Component)`` must be False so the optional\\n    # run_and_validate_update_outputs branch is skipped for this MagicMock.\\n    raw_code = SimpleNamespace(code=\\\"print('x')\\\", frontend_node=None)\\n    request = SimpleNamespace(state=SimpleNamespace(locale=\\\"en\\\"))\\n\\n    set_current_external_access_context(ExternalAccessContext(provider=\\\"openrag\\\", subject=\\\"s-1\\\", level=\\\"editor\\\"))\\n    try:\\n        result = await endpoints.custom_component(\\n            raw_code=raw_code,\\n            user=owner,\\n            request=request,\\n            provider_policy_attributes={},\\n        )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert result.type == \\\"MyComponent\\\"\\n\\n\\n# --------------------------------------------------------------------------- #\\n# endpoints.create_upload_file \u2014 deprecated upload (flow WRITE)\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_deprecated_upload_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import endpoints\\n\\n    flow = _make_flow(owner.id)\\n    save_spy = MagicMock()\\n    monkeypatch.setattr(endpoints, \\\"save_uploaded_file\\\", save_spy)\\n    settings_service = SimpleNamespace(settings=SimpleNamespace(max_file_size_upload=100))\\n    upload = SimpleNamespace(size=1, filename=\\\"x.txt\\\")\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await endpoints.create_upload_file(\\n                file=upload, flow=flow, current_user=owner, settings_service=settings_service\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    save_spy.assert_not_called()\\n\\n\\n@pytest.mark.anyio\\nasync def test_deprecated_upload_owner_proceeds(monkeypatch, owner):\\n    from pathlib import Path\\n\\n    from langflow.api.v1 import endpoints\\n\\n    flow = _make_flow(owner.id)\\n    save_spy = MagicMock(return_value=Path(\\\"flow/x.txt\\\"))\\n    monkeypatch.setattr(endpoints, \\\"save_uploaded_file\\\", save_spy)\\n    settings_service = SimpleNamespace(settings=SimpleNamespace(max_file_size_upload=100))\\n    upload = SimpleNamespace(size=1, filename=\\\"x.txt\\\")\\n\\n    result = await endpoints.create_upload_file(\\n        file=upload, flow=flow, current_user=owner, settings_service=settings_service\\n    )\\n\\n    save_spy.assert_called_once()\\n    assert result.flow_id == str(flow.id)\\n\\n\\n# --------------------------------------------------------------------------- #\\n# mcp_projects.update_project_mcp_settings \u2014 project WRITE\\n# --------------------------------------------------------------------------- #\\n\\n\\ndef _install_mcp_session(monkeypatch, project):\\n    \\\"\\\"\\\"Patch ``session_scope`` so the route's project fetch returns ``project``.\\\"\\\"\\\"\\n    from contextlib import asynccontextmanager\\n\\n    from langflow.api.v1 import mcp_projects\\n\\n    exec_result = SimpleNamespace(first=lambda: project, all=list)\\n    session = SimpleNamespace(\\n        exec=AsyncMock(return_value=exec_result),\\n        flush=AsyncMock(),\\n        add=MagicMock(),\\n    )\\n\\n    @asynccontextmanager\\n    async def _scope():\\n        yield session\\n\\n    monkeypatch.setattr(mcp_projects, \\\"session_scope\\\", _scope)\\n    return session\\n\\n\\n@pytest.mark.anyio\\nasync def test_mcp_update_settings_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import mcp_projects\\n\\n    project = SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner.id,\\n        workspace_id=None,\\n        auth_settings=None,\\n        flows=[],\\n        name=\\\"proj\\\",\\n    )\\n    session = _install_mcp_session(monkeypatch, project)\\n    request = SimpleNamespace(settings=[], auth_settings=None, model_fields_set=set())\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await mcp_projects.update_project_mcp_settings(project_id=project.id, request=request, current_user=owner)\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    session.flush.assert_not_awaited()\\n\\n\\n# --------------------------------------------------------------------------- #\\n# models.py variable-mutating routes (variable WRITE / DELETE)\\n# --------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.anyio\\nasync def test_update_enabled_models_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import models\\n\\n    svc_spy = MagicMock()\\n    monkeypatch.setattr(models, \\\"get_variable_service\\\", svc_spy)\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await models.update_enabled_models(\\n                session=MagicMock(),\\n                current_user=owner,\\n                provider_policy_attributes={},\\n                updates=[],\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    svc_spy.assert_not_called()\\n\\n\\n@pytest.mark.anyio\\nasync def test_set_default_model_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import models\\n\\n    svc_spy = MagicMock()\\n    monkeypatch.setattr(models, \\\"get_variable_service\\\", svc_spy)\\n    request = SimpleNamespace(model_type=\\\"language\\\", model_name=\\\"m\\\", provider=\\\"OpenAI\\\")\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await models.set_default_model(\\n                session=MagicMock(),\\n                current_user=owner,\\n                provider_policy_attributes={},\\n                request=request,\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    svc_spy.assert_not_called()\\n\\n\\n@pytest.mark.anyio\\nasync def test_clear_default_model_viewer_denied(monkeypatch, owner):\\n    from langflow.api.v1 import models\\n\\n    svc_spy = MagicMock()\\n    monkeypatch.setattr(models, \\\"get_variable_service\\\", svc_spy)\\n\\n    set_current_external_access_context(_viewer_ceiling())\\n    try:\\n        with pytest.raises(HTTPException) as exc_info:\\n            await models.clear_default_model(\\n                session=MagicMock(),\\n                current_user=owner,\\n                _provider_policy_attributes={},\\n                model_type=\\\"language\\\",\\n            )\\n    finally:\\n        set_current_external_access_context(None)\\n\\n    assert exc_info.value.status_code == 403\\n    svc_spy.assert_not_called()\\n\\n\\n@pytest.mark.anyio\\nasync def test_set_default_model_owner_proceeds(monkeypatch, owner):\\n    \\\"\\\"\\\"Owner with no ceiling reaches the variable service (owner-override path).\\\"\\\"\\\"\\n    from langflow.api.v1 import models\\n\\n    var_service = MagicMock(spec=models.DatabaseVariableService)\\n    var_service.get_variable_object = AsyncMock(return_value=SimpleNamespace(id=uuid4()))\\n    var_service.update_variable_fields = AsyncMock()\\n    monkeypatch.setattr(models, \\\"get_variable_service\\\", lambda: var_service)\\n    request = SimpleNamespace(model_type=\\\"language\\\", model_name=\\\"m\\\", provider=\\\"OpenAI\\\")\\n\\n    result = await models.set_default_model(\\n        session=MagicMock(),\\n        current_user=owner,\\n        provider_policy_attributes={},\\n        request=request,\\n    )\\n\\n    var_service.update_variable_fields.assert_awaited_once()\\n    assert result[\\\"default_model\\\"][\\\"model_name\\\"] == \\\"m\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_route_guard_regressions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f5af167725a92d28657a99ebd001e5b702decbe25ba3a181995f999743c77a9c\",\"content\":\"\\\"\\\"\\\"Source-level regression tests for authorization route guard wiring.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n_API_V1 = Path(__file__).resolve().parents[4] / \\\"base\\\" / \\\"langflow\\\" / \\\"api\\\" / \\\"v1\\\"\\n_FLOWS_FILE = _API_V1 / \\\"flows.py\\\"\\n_PROJECTS_FILE = _API_V1 / \\\"projects.py\\\"\\n_DEPLOYMENTS_FILE = _API_V1 / \\\"deployments.py\\\"\\n_HELPERS_FLOW = Path(__file__).resolve().parents[4] / \\\"base\\\" / \\\"langflow\\\" / \\\"helpers\\\" / \\\"flow.py\\\"\\n\\n\\ndef _parse_async_funcs(path: Path) -> dict[str, ast.AsyncFunctionDef]:\\n    tree = ast.parse(path.read_text())\\n    return {node.name: node for node in ast.walk(tree) if isinstance(node, ast.AsyncFunctionDef)}\\n\\n\\ndef _calls(func: ast.AsyncFunctionDef, name: str) -> list[ast.Call]:\\n    out: list[ast.Call] = []\\n    for node in ast.walk(func):\\n        if not isinstance(node, ast.Call):\\n            continue\\n        target = node.func\\n        is_named = isinstance(target, ast.Name) and target.id == name\\n        is_attr = isinstance(target, ast.Attribute) and target.attr == name\\n        if is_named or is_attr:\\n            out.append(node)\\n    return out\\n\\n\\ndef _has_keyword(call: ast.Call, name: str) -> bool:\\n    return any(kw.arg == name for kw in call.keywords)\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef flows_routes() -> dict[str, ast.AsyncFunctionDef]:\\n    return _parse_async_funcs(_FLOWS_FILE)\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef projects_routes() -> dict[str, ast.AsyncFunctionDef]:\\n    return _parse_async_funcs(_PROJECTS_FILE)\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef deployments_routes() -> dict[str, ast.AsyncFunctionDef]:\\n    return _parse_async_funcs(_DEPLOYMENTS_FILE)\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef helpers_funcs() -> dict[str, ast.AsyncFunctionDef]:\\n    return _parse_async_funcs(_HELPERS_FLOW)\\n\\n\\ndef test_read_flows_paginated_branch_passes_owner_extractor(flows_routes):\\n    \\\"\\\"\\\"The paginated filter_visible_resources call must pass owner_extractor.\\n\\n    Both branches of read_flows (``get_all=True`` and pagination) must give\\n    the enforcer the same hint about which flows are owner-owned. Omitting it\\n    on the paginated branch lets an authorization plugin without an explicit\\n    owner-allow policy hide the caller's own flows when paginating.\\n    \\\"\\\"\\\"\\n    func = flows_routes[\\\"read_flows\\\"]\\n    fvr_calls = _calls(func, \\\"filter_visible_resources\\\")\\n    assert len(fvr_calls) >= 2, \\\"read_flows should call filter_visible_resources on both branches\\\"\\n    for call in fvr_calls:\\n        assert _has_keyword(call, \\\"owner_extractor\\\"), (\\n            \\\"Every filter_visible_resources call in read_flows must pass owner_extractor \\\"\\n            \\\"so the enforcer short-circuits on owner-allow\\\"\\n        )\\n\\n\\ndef test_upsert_flow_consults_cross_user_fetch_capability(flows_routes):\\n    \\\"\\\"\\\"upsert_flow must not unconditionally raise 404 for non-owners.\\n\\n    With an authorization plugin registered, a valid WRITE share grant must be\\n    honored. The current shape gates the hardcoded ownership floor on\\n    ``supports_cross_user_fetch() and is_enabled()``.\\n    \\\"\\\"\\\"\\n    func = flows_routes[\\\"upsert_flow\\\"]\\n    src = ast.unparse(func)\\n    assert \\\"supports_cross_user_fetch\\\" in src, \\\"upsert_flow must consult cross-user-fetch capability\\\"\\n    assert \\\"is_enabled\\\" in src, \\\"upsert_flow must consult is_enabled before the OSS floor\\\"\\n\\n\\ndef test_upsert_flow_wraps_ensure_in_deny_to_404(flows_routes):\\n    \\\"\\\"\\\"upsert_flow must convert ensure_flow_permission 403 to 404 for UUID privacy.\\\"\\\"\\\"\\n    func = flows_routes[\\\"upsert_flow\\\"]\\n    src = ast.unparse(func)\\n    assert \\\"deny_to_404\\\" in src, \\\"upsert_flow must wrap ensure_flow_permission with deny_to_404\\\"\\n\\n\\ndef test_delete_multiple_flows_does_not_unconditionally_prescope(flows_routes):\\n    \\\"\\\"\\\"Bulk delete must not unconditionally filter by Flow.user_id == user.id.\\n\\n    The pre-scope is now gated on whether the registered service supports\\n    cross-user fetch \u2014 otherwise valid share DELETE grants are silently\\n    dropped from the working set.\\n    \\\"\\\"\\\"\\n    func = flows_routes[\\\"delete_multiple_flows\\\"]\\n    src = ast.unparse(func)\\n    assert \\\"supports_cross_user_fetch\\\" in src, (\\n        \\\"delete_multiple_flows must gate the owner pre-scope on cross-user-fetch capability\\\"\\n    )\\n\\n\\ndef test_download_multiple_file_does_not_unconditionally_prescope(flows_routes):\\n    \\\"\\\"\\\"Same as above for the bulk download endpoint.\\\"\\\"\\\"\\n    func = flows_routes[\\\"download_multiple_file\\\"]\\n    src = ast.unparse(func)\\n    assert \\\"supports_cross_user_fetch\\\" in src, (\\n        \\\"download_multiple_file must gate the owner pre-scope on cross-user-fetch capability\\\"\\n    )\\n    assert \\\"deny_to_404\\\" in src, (\\n        \\\"download_multiple_file must convert ensure_flow_permission 403 to 404 for UUID privacy\\\"\\n    )\\n\\n\\ndef test_read_project_paginated_branch_filters_via_filter_visible_resources(projects_routes):\\n    \\\"\\\"\\\"The paginated branch of ``read_project`` must apply per-flow authz too.\\n\\n    A project READ grant must not bypass finer-grained per-flow policy just\\n    because the caller asked for pagination. Both the non-paginated and\\n    paginated branches must call ``filter_visible_resources`` when the\\n    project is reached via a share grant (``treat_as_shared``); otherwise\\n    shared-project reads behave differently depending on page/size.\\n    \\\"\\\"\\\"\\n    func = projects_routes[\\\"read_project\\\"]\\n    fvr_calls = _calls(func, \\\"filter_visible_resources\\\")\\n    assert len(fvr_calls) >= 2, (\\n        \\\"read_project must call filter_visible_resources on both the paginated \\\"\\n        \\\"and non-paginated shared-project branches\\\"\\n    )\\n\\n\\ndef test_read_flows_wires_db_layer_prefilter(flows_routes):\\n    \\\"\\\"\\\"read_flows must call ``visible_scope_prefilter`` so an EE plugin can prefilter at the DB.\\n\\n    Without this the plugin's ``get_resource_visibility`` override has no\\n    effect on the listing \u2014 every candidate row is fetched and filtered in\\n    memory, defeating the hook at large-tenant scale.\\n    \\\"\\\"\\\"\\n    func = flows_routes[\\\"read_flows\\\"]\\n    assert _calls(func, \\\"visible_scope_prefilter\\\"), \\\"read_flows must consult visible_scope_prefilter\\\"\\n\\n\\ndef test_read_projects_wires_db_layer_prefilter(projects_routes):\\n    \\\"\\\"\\\"read_projects must call ``visible_scope_prefilter`` (DB-layer prefilter).\\\"\\\"\\\"\\n    func = projects_routes[\\\"read_projects\\\"]\\n    assert _calls(func, \\\"visible_scope_prefilter\\\"), \\\"read_projects must consult visible_scope_prefilter\\\"\\n\\n\\ndef test_read_project_wires_db_layer_prefilter(projects_routes):\\n    \\\"\\\"\\\"read_project (flows-in-project) must call ``visible_scope_prefilter`` too.\\\"\\\"\\\"\\n    func = projects_routes[\\\"read_project\\\"]\\n    assert _calls(func, \\\"visible_scope_prefilter\\\"), \\\"read_project must consult visible_scope_prefilter\\\"\\n\\n\\ndef test_list_deployments_threads_prefilter_into_synced_query(deployments_routes):\\n    \\\"\\\"\\\"list_deployments must consult the prefilter AND thread it into the synced query.\\n\\n    Passing ``visibility_scope`` into ``list_deployments_synced`` is what pushes the\\n    prefilter down to both the page query and its count, so pagination totals\\n    reflect the constraint instead of overcounting denied rows.\\n    \\\"\\\"\\\"\\n    func = deployments_routes[\\\"list_deployments\\\"]\\n    assert _calls(func, \\\"visible_scope_prefilter\\\"), \\\"list_deployments must consult visible_scope_prefilter\\\"\\n    synced_calls = _calls(func, \\\"list_deployments_synced\\\")\\n    assert synced_calls, \\\"list_deployments must call list_deployments_synced\\\"\\n    assert any(_has_keyword(call, \\\"visibility_scope\\\") for call in synced_calls), (\\n        \\\"list_deployments must thread visibility_scope into list_deployments_synced so the \\\"\\n        \\\"page query and its total share the prefilter\\\"\\n    )\\n\\n\\ndef test_list_deployments_relaxes_provider_gate_on_prefilter(deployments_routes):\\n    \\\"\\\"\\\"list_deployments must not unconditionally apply the owner-scoped provider gate.\\n\\n    A shared deployment lives under its *owner's* provider account, so the strict\\n    ``get_owned_provider_account_or_404`` 404s a cross-user reader before the\\n    ``(owner \u2295 visible)`` prefilter union can surface the row. When\\n    ``visible_scope_prefilter`` returns cross-user visibility, the handler must resolve the\\n    provider account by id alone (``get_shared_listing_provider_account_or_404``)\\n    so ``visibility_scope`` can actually widen cross-user shared listing \u2014 while the\\n    OSS / no-plugin path keeps the strict owner gate.\\n    \\\"\\\"\\\"\\n    func = deployments_routes[\\\"list_deployments\\\"]\\n    src = ast.unparse(func)\\n    assert _calls(func, \\\"get_shared_listing_provider_account_or_404\\\"), (\\n        \\\"list_deployments must resolve the provider account by id alone on the \\\"\\n        \\\"prefilter path so shared deployments under another user's provider \\\"\\n        \\\"account are listable\\\"\\n    )\\n    assert \\\"get_owned_provider_account_or_404\\\" in src, (\\n        \\\"list_deployments must keep the strict owner gate for the OSS / no-plugin path\\\"\\n    )\\n\\n\\ndef test_load_flow_calls_ensure_flow_permission(helpers_funcs):\\n    \\\"\\\"\\\"load_flow (component-reachable graph loader) must authorize EXECUTE.\\n\\n    Reachable from custom components, sub-flow runners, and ``run_flow``.\\n    Without this guard, a caller can pass an arbitrary flow_id and pull\\n    another user's flow definition (prompts, tools, embedded credentials).\\n    \\\"\\\"\\\"\\n    load_flow = helpers_funcs[\\\"load_flow\\\"]\\n    assert _calls(load_flow, \\\"scoped_model_provider_policy_for_target_flow\\\"), (\\n        \\\"load_flow must enter the target-flow authorization and provider-policy scope\\\"\\n    )\\n\\n    target_scope = helpers_funcs[\\\"scoped_model_provider_policy_for_target_flow\\\"]\\n    assert _calls(target_scope, \\\"_resolve_authorized_target_flow\\\"), (\\n        \\\"the target-flow scope must resolve and authorize the requested flow\\\"\\n    )\\n\\n    resolver = helpers_funcs[\\\"_resolve_authorized_target_flow\\\"]\\n    ensure_calls = _calls(resolver, \\\"ensure_flow_permission\\\")\\n    assert ensure_calls, \\\"the target-flow resolver must call ensure_flow_permission\\\"\\n    assert any(\\n        len(call.args) >= 2 and isinstance(call.args[1], ast.Attribute) and call.args[1].attr == \\\"EXECUTE\\\"\\n        for call in ensure_calls\\n    ), \\\"the target-flow resolver must authorize FlowAction.EXECUTE\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_unscoped_list_visibility.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6104f464ef91e842b81c22e1ed0ecaba7000ef13baafa5774402d6e9393e386c\",\"content\":\"\\\"\\\"\\\"Structured visibility coverage for resources without domain columns.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom contextlib import asynccontextmanager\\nfrom types import SimpleNamespace\\nfrom unittest.mock import ANY, AsyncMock, MagicMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.api.v1 import knowledge_bases as knowledge_bases_api\\nfrom langflow.api.v1 import memories as memories_api\\nfrom langflow.api.v1 import variable as variable_api\\nfrom langflow.api.v2 import files as files_api\\nfrom langflow.services.authorization.listing import restrict_to_owned_or_visible_scope\\nfrom langflow.services.database.models.file.model import File as UserFile\\nfrom langflow.services.database.models.variable.model import Variable\\nfrom langflow.services.deps import get_settings_service\\nfrom langflow.services.variable.service import DatabaseVariableService\\nfrom lfx.services.authorization.base import ResourceVisibilityScope\\nfrom sqlmodel import select\\n\\n\\nclass _CapturingSession:\\n    def __init__(self, rows=None) -> None:\\n        self.statement = None\\n        self.rows = rows or []\\n\\n    async def exec(self, statement):\\n        self.statement = statement\\n        return self.rows\\n\\n\\n@pytest.mark.anyio\\nasync def test_file_list_uses_global_structured_visibility(monkeypatch):\\n    actor = SimpleNamespace(id=uuid4())\\n    session = _CapturingSession()\\n    visibility = ResourceVisibilityScope(all_resources=True)\\n\\n    monkeypatch.setattr(files_api, \\\"ensure_file_permission\\\", AsyncMock())\\n    monkeypatch.setattr(files_api, \\\"get_mcp_file\\\", AsyncMock(return_value=\\\"_mcp_servers\\\"))\\n    monkeypatch.setattr(files_api, \\\"visible_scope_prefilter\\\", AsyncMock(return_value=visibility), raising=False)\\n    monkeypatch.setattr(\\n        files_api,\\n        \\\"visible_id_prefilter\\\",\\n        AsyncMock(side_effect=AssertionError(\\\"legacy visibility hook used\\\")),\\n        raising=False,\\n    )\\n\\n    await files_api.list_files(current_user=actor, session=session)\\n\\n    assert session.statement is not None\\n    assert UserFile.user_id.key not in str(session.statement.whereclause)\\n\\n\\n@pytest.mark.anyio\\nasync def test_file_list_excludes_reserved_mcp_file_for_every_owner(monkeypatch):\\n    actor_id = uuid4()\\n    owner_id = uuid4()\\n    actor = SimpleNamespace(id=actor_id)\\n    actor_mcp_file = UserFile(\\n        id=uuid4(),\\n        user_id=actor_id,\\n        name=f\\\"{files_api.MCP_SERVERS_FILE}_{actor_id}\\\",\\n        path=f\\\"{actor_id}/mcp.json\\\",\\n        size=1,\\n    )\\n    owner_mcp_file = UserFile(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        name=f\\\"{files_api.MCP_SERVERS_FILE}_{owner_id}\\\",\\n        path=f\\\"{owner_id}/mcp.json\\\",\\n        size=1,\\n    )\\n    shared_file = UserFile(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        name=\\\"shared-notes\\\",\\n        path=f\\\"{owner_id}/shared-notes.txt\\\",\\n        size=1,\\n    )\\n    session = _CapturingSession([actor_mcp_file, owner_mcp_file, shared_file])\\n\\n    monkeypatch.setattr(files_api, \\\"ensure_file_permission\\\", AsyncMock())\\n    monkeypatch.setattr(\\n        files_api,\\n        \\\"visible_scope_prefilter\\\",\\n        AsyncMock(return_value=ResourceVisibilityScope(all_resources=True)),\\n    )\\n\\n    result = await files_api.list_files(current_user=actor, session=session)\\n\\n    assert result == [shared_file]\\n\\n\\n@pytest.mark.anyio\\nasync def test_knowledge_base_list_forwards_concrete_structured_visibility(monkeypatch, tmp_path):\\n    actor = SimpleNamespace(id=uuid4(), username=\\\"actor\\\")\\n    visibility = ResourceVisibilityScope(resource_ids=(uuid4(),))\\n    list_owned_or_visible = AsyncMock(return_value=[])\\n    list_by_user = AsyncMock(return_value=[])\\n\\n    monkeypatch.setattr(knowledge_bases_api, \\\"_guard_kb_action\\\", AsyncMock())\\n    monkeypatch.setattr(knowledge_bases_api.KBStorageHelper, \\\"get_root_path\\\", lambda: tmp_path)\\n    monkeypatch.setattr(\\n        knowledge_bases_api,\\n        \\\"visible_scope_prefilter\\\",\\n        AsyncMock(return_value=visibility),\\n        raising=False,\\n    )\\n    monkeypatch.setattr(\\n        knowledge_bases_api,\\n        \\\"visible_id_prefilter\\\",\\n        AsyncMock(side_effect=AssertionError(\\\"legacy visibility hook used\\\")),\\n        raising=False,\\n    )\\n    monkeypatch.setattr(knowledge_bases_api.knowledge_base_service, \\\"list_by_user\\\", list_by_user)\\n    monkeypatch.setattr(\\n        knowledge_bases_api.knowledge_base_service,\\n        \\\"list_owned_or_visible\\\",\\n        list_owned_or_visible,\\n    )\\n\\n    result = await knowledge_bases_api.list_knowledge_bases(\\n        current_user=actor,\\n        job_service=MagicMock(),\\n    )\\n\\n    assert result == []\\n    list_owned_or_visible.assert_awaited_once_with(actor.id, visibility)\\n    list_by_user.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_memory_base_list_forwards_structured_visibility(monkeypatch):\\n    actor = SimpleNamespace(id=uuid4())\\n    visibility = ResourceVisibilityScope(project_ids=(uuid4(),))\\n    service = MagicMock()\\n    service.list_for_user_stmt.return_value = select(Variable)\\n    page = MagicMock()\\n\\n    @asynccontextmanager\\n    async def fake_session_scope():\\n        yield MagicMock()\\n\\n    monkeypatch.setattr(memories_api, \\\"session_scope\\\", fake_session_scope)\\n    monkeypatch.setattr(memories_api, \\\"get_memory_base_service\\\", lambda: service)\\n    monkeypatch.setattr(memories_api, \\\"apaginate\\\", AsyncMock(return_value=page))\\n    monkeypatch.setattr(memories_api, \\\"visible_scope_prefilter\\\", AsyncMock(return_value=visibility), raising=False)\\n    monkeypatch.setattr(\\n        memories_api,\\n        \\\"visible_id_prefilter\\\",\\n        AsyncMock(side_effect=AssertionError(\\\"legacy visibility hook used\\\")),\\n        raising=False,\\n  ";
